	/* Be careful for the criteria for == two doubles */
	/* Relative or Absolute? */
	struct Double{
		double x;
		Double(double x=0):x(x){}
		Double(const Double& rhs){x=rhs.x;}
		Double operator+(const Double& rhs)const{return Double(x+rhs.x);}
		Double& operator+=(const Double& rhs){return x+=rhs.x,*this;}
		Double operator-(const Double& rhs)const{return Double(x-rhs.x);}
		Double& operator-=(const Double& rhs){return x-=rhs.x,*this;}
		Double operator*(const Double& rhs)const{return Double(x*rhs.x);}
		Double& operator*=(const Double& rhs){return x*=rhs.x,*this;}
		Double operator/(const Double& rhs)const{return Double(x/rhs.x);}
		Double& operator/=(const Double& rhs){return x/=rhs.x,*this;}
		Double operator-()const{return Double(-x);}
		Double operator^(const Double& rhs)const{return pow(x,rhs.x);}
		Double operator^(const int& rhs)const{
			double res = 1, base = x;
			int b = rhs;
			while(b){
				if(b&1)	res = res * base;
				b >>= 1;
				base *= base;
			}
			return res;
		}
		Double& operator++(){return ++x,*this;}
		Double& operator--(){return --x,*this;}
		Double operator++(int){Double res(x);return x++,res;}
		Double operator--(int){Double res(x);return x--,res;}
		bool operator==(const Double& rhs)const{return x+eps>=rhs.x&&x<=rhs.x+eps;}
		bool operator!=(const Double& rhs)const{return !(*this==rhs);}
