		Point operator/(const T& rhs)const{return Point(x/rhs,y/rhs);}
		T operator^(const Point& rhs)const{return x*rhs.y-y*rhs.x;}
		Double len()const{return sqrt(x*x+y*y);}
		T len2()const{return x*x+y*y;}
		Double dist(const Point& rhs)const{Point delta = *this - rhs;return delta.len();}
		T dist2(const Point& rhs)const{Point delta = *this - rhs;return delta.len2();}
		Point norm()const{Double l = len();return *this/l;}
		Point resize(Double l)const{return norm()*l;}
		Point rotpos()const{return Point(-y,x);}
		Point rotneg()const{return Point(y,-x);}
		Point rot(const Double& ang)const{return Point(x*cos(ang)-y*sin(ang),y*cos(ang)+x*sin(ang));}
		/* friend function */
		/* the angle of ABC <= 180 */
		friend Double angle(const Point& A,const Point& B,const Point& C){
			return abs(atan2(abs((A-B)^(C-B)),(A-B)*(C-B)));
		}
		friend ostream & operator << (ostream& os, const Point& rhs){
			os << rhs.x << ' ' << rhs.y;
			return os;
		}
