			is >> rhs.x >> rhs.y;
			return is;
		}
	};
	/* ccw, call hull for Pp,Pq beforehand */
	vector<Point> Minkowski(vector<Point>& Pp,vector<Point>& Pq){
		int n=Pp.size(),m=Pq.size();
		vector<Point> Pr;
		Pr.emplace_back(Pp[0]+Pq[0]);
		Pp.emplace_back(Pp[0]);Pq.emplace_back(Pq[0]);
		for(int i=0,j=0;i!=n||j!=m;){
			Point nxt;
			if((j==m)||(i!=n&&((Pp[i+1]-Pp[i])^(Pq[j+1]-Pq[j]))>=0)){
				nxt=Pr.back()+Pp[i+1]-Pp[i];
				i++;
			}
			else{
				nxt=Pr.back()+Pq[j+1]-Pq[j];
				j++;
			}
			while(Pr.size()>=2&&((Pr.back()-nxt)^(Pr[Pr.size()-2]-nxt))==0)
				Pr.pop_back();
			Pr.emplace_back(nxt);
		}
		Pp.pop_back();Pq.pop_back();Pr.pop_back();
		return Pr;
	}
	bool inConvex(vector<Point>& c,const Point& p){
		int L=1,R=c.size()-1;
		if(((p-c[0])^(c[L]-c[0]))>0)	return false;
		if(((p-c[0])^(c[R]-c[0]))<0)	return false;
		while(L<R){
			int mid=(L+R+1)>>1;
			if(((p-c[0])^(c[mid]-c[0]))<=0)	L=mid;
			else	R=mid-1;
		}
		if(L==c.size()-1)	L--;
		return ((p-c[L])^(c[L+1]-c[L]))<=0;
	}
	/* (-pi,pi] */
	Double norm(Double ang){
		ang = ang-round(ang/pi/2)*pi*2;
		if(ang<=-pi)	ang+=2*pi;
		if(ang>pi)	ang-=2*pi;
		return ang;
	}
	struct Line{
		Point s,e;
		Line(Point s=Point(),Point e=Point()):s(s),e(e){}
		Line(Point p,Double ang):s(p){
			ang=norm(ang);
			if(ang==pi/2)	e=s+Point(0,1);
			else if(ang==-pi/2)	e=s-Point(0,1);
			else	e=s+Point(1,tan(ang));
		}
		/* ax+by+c==0 */
		Line(Double a,Double b,Double c){
			if(a==0){
				s=Point(0,-c/b);
				e=Point(1,-c/b);
			}
			else if(b==0){
				s=Point(-c/a,0);
				e=Point(-c/a,1);
			}
			else{
				s=Point(0,-c/b);
				e=Point(-c/a,0);
			}
		}
		bool operator==(const Line& rhs)const{return s==rhs.s&&e==rhs.e;}
		Double len()const{return s.dist(e);}
		T len2()const{return s.dist2(e);}
		Double angle()const{return atan2(e.y-s.y,e.x-s.x);}
		Point projection(const Point& p)const{
			return s+((e-s)*((e-s)*(p-s)))/(e-s).len2();
		}
		Point symmetry(const Point& p)const{
			return projection(p)*2-p;
		}
		/* -1: at left, 0: on line, 1: at right */
		int where(const Point& p)const{
			auto x = (p-s)^(e-s);
			if(x==0)	return 0;
			else if(x>0)	return 1;
			else return -1;
		}
		/* 0: parallel, 1: same, 2: orthogonal, 3: intersect */
		int relation(const Line& l)const{
			if(parallel(l))	return where(l.s)==0;
			else if(orthogonal(l))	return 2;
			else return 3;
		}
		bool onseg(const Point& p)const{return ((p-s)^(e-s))==0&&((p-s)*(p-e))<=0;}
		bool parallel(const Line& l)const{return ((e-s)^(l.e-l.s))==0;}
		bool orthogonal(const Line& l)const{return ((e-s)*(l.e-l.s))==0;}
		/* 0: no intersection, 1: not normal, 2: normal */
		/* *this is line, l is seg */
		int linecrossseg(const Line& l)const{
			int d0 = sign((e-s)^(l.s-s));
			int d1 = sign((e-s)^(l.e-s));
			if((d0^d1)==-2)	return 2;
			return d0==0||d1==0;
		}
		/* 0: no intersection, 1: not normal, 2: normal */
		int segcrossseg(const Line& l)const{
			int d0 = sign((e-s)^(l.s-s));
			int d1 = sign((e-s)^(l.e-s));
			int d2 = sign((l.e-l.s)^(s-l.s));
			int d3 = sign((l.e-l.s)^(e-l.s));
			if((d0^d1)==-2&&(d2^d3)==-2)	return 2;
			return (d0==0&&onseg(l.s))||(d1==0&&onseg(l.e))||(d2==0&&l.onseg(s))||(d3==0&&l.onseg(e));
		}
		Double distasline(const Point& p)const{return abs(((p-s)^(e-s))/len());}
		Double distasseg(const Point& p)const{
			if(((p-s)*(e-s))<0||((p-e)*(s-e))<0)
				return min(s.dist(p),e.dist(p));
			return distasline(p);
		}
		/* both are segs */
		Double distsegseg(const Line& l)const{
			if(segcrossseg(l)!=0)	return 0;
			return min(min(distasseg(l.s),distasseg(l.e)),min(l.distasseg(s),l.distasseg(e)));
		}
		/* *this is line */
		Double distlineseg(const Line& l)const{
			if(linecrossseg(l)==0)
				return min(distasline(l.s),distasline(l.e));
			return 0;
		}

		friend ostream & operator << (ostream& os, const Line& rhs){
			os << rhs.s << ' ' << rhs.e;
			return os;
		}
		friend istream & operator >> (istream& is, Line& rhs){
			is >> rhs.s >> rhs.e;
			return is;
		}
		friend Point intersectLL(const Line& l,const Line& r){
			Double s1=(r.e-r.s)^(l.s-r.s), s2=-((r.e-r.s)^(l.e-r.s));
			return (l.s*s2+l.e*s1)/(s1+s2);
		}
	};
	/* not necessary convex */
	struct Polygon:vector<Point>{
		bool isconvex()const{
			bool flagl=false,flagr=false;
			for(int i=0;i<size();i++){
				int j=(i+1)%size(),k=(j+1)%size();
				auto z=(at(i)-at(j))^(at(k)-at(j));
				if(z<0)	flagl=true;
				if(z>0)	flagr=true;
				if(flagl&&flagr)	return false;
			}
			return true;
		}
		/* negative then clockwise, ccw if positive */
		T area2()const{
			T res=0;
			for(int i=0;i<size();i++)
				res+=(at(i)^at((i+1)%size()));
			return res;
		}
		Double area()const{return abs(area2())/2;}
		Double circum()const{
			Double res=0;
			for(int i=0;i<size();i++)
				res+=at(i).dist(at((i+1)%size()));
			return res;
		}
		/* 3: as vertex, 2: onseg, 1: interior, 0: exterior */
		int relation(const Point& p)const{
			int n=size();
			for(int i=0;i<n;i++)
				if(p==at(i))
					return 3;
			int cnt=0;
			for(int i=0;i<n;i++){
				Point s=at(i),e=at((i+1)%n);
				if(Line(s,e).onseg(p))	return 2;
				if(s.y-e.y>0)	s=at((i+1)%n),e=at(i);
				if(p.y>=e.y||p.y<s.y)	continue;
				if(Line(s,e).where(p)==-1)	cnt++;
			}
			return cnt&1;
		}
	};
	struct Convex:Polygon{
		/* P should contain at least two "different" points */
		Convex(vector<Point> P={},bool border=false){
			if(P.size()<=1)	clear();
			sort(P.begin(),P.end());
			emplace_back(P[0]),emplace_back(P[1]);
			for(int i=2;i<P.size();i++){
				if(border)
					while(size()>=2&&((back()-at(size()-2))^(P[i]-at(size()-2)))<0)
						pop_back();
				else
					while(size()>=2&&((back()-at(size()-2))^(P[i]-at(size()-2)))<=0)
						pop_back();
				emplace_back(P[i]);
			}
			for(int i=P.size()-2,t=size();i>=0;i--){
				if(border)
					while(size()>t&&((back()-at(size()-2))^(P[i]-at(size()-2)))<0)
						pop_back();
				else
					while(size()>t&&((back()-at(size()-2))^(P[i]-at(size()-2)))<=0)
						pop_back();
				emplace_back(P[i]);
			}
			pop_back();
			if(size()<=1||(size()==2&&at(0)==at(1)))	clear();
		}
	};
}
