  double a, b;
  is >> a >> b;
  p = Point(a, b);
  return is;
}
ostream &operator<<(ostream &os, Point &p) {
  os << fixed << setprecision(10) << p.real() << " " << p.imag();
}

namespace std {
bool operator<(const Point &a, const Point &b) {
  return a.real() != b.real() ? a.real() < b.real() : a.imag() < b.imag();
}
} // namespace std

double cross(const Point &a, const Point &b) {
  return a.real() * b.imag() - a.imag() * b.real();
}

double dot(const Point &a, const Point &b) {
  return a.real() * b.real() + a.imag() * b.imag();
}

double RadianToDegree(double r) {
  return (r * 180.0 / acos(-1));
}

double DegreeToRadian(double d) {
  return (d * acos(-1) / 180.0);
}

double GetAngle(const Point &a, const Point &b, const Point &c) {
  const Point v(b - a), w(c - b);
  double alpha = atan2(v.imag(), v.real()), beta = atan2(w.imag(), w.real());
  if (alpha > beta) swap(alpha, beta);
  double theta = (beta - alpha);
  return min(theta, 2 * acos(-1) - theta);
}

struct Line {
  Point a, b;

  Line(){};
  Line(Point a, Point b) : a(a), b(b){};

  // Ax + By = C
  Line(double A, double B, double C) {
    if (eq(A, 0)) {
      a = Point(0, C / B);
      b = Point(1, C / B);
    } else if (eq(B, 0)) {
      a = Point(C / A, 0);
      b = Point(C / A, 1);
    } else {
      a = Point(0, C / B);
      b = Point(C / A, 0);
    }
  }

  friend ostream &operator<<(ostream &os, Line &p) {
    return os << p.a << " to " << p.b;
  }

  friend istream &operator>>(istream &is, Line &a) {
    return is >> a.a >> a.b;
  }
};

struct Segment {
  Point a, b;

  Segment(){};
  Segment(Point a, Point b) : a(a), b(b){};

  friend ostream &operator<<(ostream &os, Segment &p) {
    return os << p.a << " to " << p.b;
  }

  friend istream &operator>>(istream &is, Segment &a) {
    return is >> a.a >> a.b;
  }
};

