struct line{
	double A;
	double B;
	double C;
	void pull(){
		if(ABS(A)<eps){
			A/=B;
			C/=B;
			B/=B;
		}
		else{
			B/=A;
			C/=A;
			A/=A;
		}
		return ;
	}
	line(){}
	line(double a,double b,double c){A=a;B=b;C=c;pull();}
	line(point a,point b){
		A=a.y-b.y;
		B=b.x-a.x;
		C=A*a.x+B*a.y;
		pull();
	}
	line(double a,double b,point p){
		A=a;
		B=b;
		C=A*p.x+B*p.y;
		pull();
	}
	line(segment s){
		A=s.a.y-s.b.y;
		B=s.b.x-s.a.x;
		C=A*s.a.x+B*s.a.y;
		pull();
	}
	void out(){
		printf("line:: A=%.3lf B=%.3lf C=%.3lf\n",A,B,C);
		return ;
	}
};
