#include <bits/stdc++.h>
using namespace std;
const double EPS = 1e-9;

struct point{
	double x, y;
	point(){
		x = y = 0.0;
	}
	point(double _x, double _y){
		x = _x;
		y = _y;
	}
};
struct vec{
	double x, y;
	vec(double _x, double _y){
		x = _x;
		y = _y;
	}
};
vec toVec(point p, point q){
	return vec(q.x-p.x, q.y-p.y);
}
double dist(point p, point q){
	return hypot(p.x-q.x, p.y-q.y);
}
double cross(vec p, vec q){
	return (p.x*q.y)-(p.y*q.x);
}
bool ccw(point p, point q, point r){
	return (cross(toVec(p, q), toVec(p, r)) > 0);
}
bool collinear(point p, point q, point r){
	return (fabs(cross(toVec(p, q), toVec(p, r))) < EPS);
}
point pivot;
bool cmp(point p, point q){
	if(collinear(pivot, p, q))
		return dist(pivot, p) < dist(pivot, q);
	double dpx = p.x-pivot.x, dpy = p.y-pivot.y;
	double dqx = q.x-pivot.x, dqy = q.y-pivot.y;
	return (atan2(dpy, dpx)-atan2(dqy, dqx) < 0);
}
vector<point> convexHull(vector<point> P){
	int idx = 0;
	for(int i = 1; i < (int)P.size(); i++)
		if((P[i].y < P[idx].y) || (fabs(P[i].y-P[idx].y) < EPS && P[i].x > P[idx].x))
			idx = i;
	swap(P[0], P[idx]);
	pivot = P[0];
	sort(P.begin()+1, P.end(), cmp);
	vector<point> S;
	S.push_back(P[(int)P.size()-1]);
	S.push_back(P[0]);
	S.push_back(P[1]);
	int i = 2;
	while(i < (int)P.size()){
		int j = (int)S.size()-1;
		if(ccw(S[j-1], S[j], P[i])) S.push_back(P[i++]);
		else S.pop_back();
	}
	return S;
}
