};

int sgn(double a) {return (a>EPS)-(a<-EPS);}
int sgn(double a,double b) {return sgn(a-b);}

double dot(const Point &a,const Point &b) {return (a.x*b.x+a.y*b.y);}
double cross(const Point &a,const Point &b) {return (a.x*b.y-a.y*b.x);}
double norm(const Point &p) {return dot(p,p);}
double abs(const Point &p) {return sqrt(norm(p));}

//1:Counter_Clockwise -1:Clockwise
//2:a-b-c -2:c-a-b 0:a-c-b
int ccw(const Point &p,const Point &q){
    int s=sgn(cross(p,q));
    if(s!=0) return s;
    if(dot(p,q)<0) return -2;
    if(norm(p)<norm(q)) return 2;
    return 0;
}
int ccw(const Point &a,const Point &b,const Point &c){return ccw(b-a,c-a);}

bool isConvex(vector<Point> &g){
    int n=g.size();
    for(int i=0;i<n;i++){
        if(ccw(g[i],g[(i+1)%n],g[(i+2)%n])==-1) return false;
    }
    return true;
}

vector<Point> ConvexHull(vector<Point> &ps,bool linear){
    sort(ps.begin(),ps.end(),[](Point &a,Point &b){
        return (a.x!=b.x?a.x<b.x:a.y<b.y);
    });
    int n=ps.size();
    vector<Point> res(2*n);
    int lim=linear?0:1;

    int k=0;
    for(int i=0;i<n;i++){
        while(k>=2&&sgn(cross(res[k-1]-res[k-2],ps[i]-res[k-2]))<lim) --k;
        res[k++]=ps[i];
    }
    int t=k+1;
    for(int i=n-2;i>=0;i--){
        while(k>=t&&sgn(cross(res[k-1]-res[k-2],ps[i]-res[k-2]))<lim) --k;
        res[k++]=ps[i];
    }

    res.resize(k-1);
    return res;
}

int main(){
    int N;
