/*凸包*/
/*２次元平面における点の集合Pに対する凸包（convex hull）を求めて下さい。凸包とは点集合Pの全ての点を含む最小の凸多角形です。*/
/*集合の要素数 n*/
/*集合 p_xy[1000000][2]*/
/*解答の要素数 q*/
/*解答 ans[1000000][2]　最も下の最も左から反時計回り*/
void convex_hull(int n, double p_xy[1000000][2], int *q, double ans[1000000][2]){

    int lower_left=0;
    for(int i=1; i<n; i++){
        if(p_xy[lower_left][1]>p_xy[i][1]){
            lower_left=i;
        }else if(p_xy[lower_left][1]==p_xy[i][1]&&p_xy[lower_left][0]>p_xy[i][0]){
            lower_left=i;
        }
    }

    ans[0][0]=p_xy[lower_left][0];
    ans[0][1]=p_xy[lower_left][1];
    *q=1;

    n--;
    p_xy[lower_left][0]=p_xy[n][0];
    p_xy[lower_left][1]=p_xy[n][1];


    while(1){
        double angle = 999999.9;
        int next = -1;
        for(int i=0; i<n; i++){

            double temp_angle = angle_line_0_359(ans[*q-1][0], ans[*q-1][1], p_xy[i][0], p_xy[i][1]);
            if(0<=temp_angle&&temp_angle<=M_PI&& temp_angle<angle){
                angle=temp_angle;
                next=i;
            }

            if(temp_angle==angle){
                if(distance_between_the_two_pointss(ans[*q-1][0], ans[*q-1][1], p_xy[i][0], p_xy[i][1])<distance_between_the_two_pointss(ans[*q-1][0], ans[*q-1][1], p_xy[next][0], p_xy[next][1])){
                    next=i;
                }
            }



        }

        //double angle2 = angle_line_0_359(p_xy[next][0], p_xy[next][1],ans[0][0], ans[0][1]);
        //if(angle>angle2)break;
        if(next==-1)break;
        else{
            ans[*q][0]=p_xy[next][0];
            ans[*q][1]=p_xy[next][1];

            *q=*q+1;

            n--;
            p_xy[next][0]=p_xy[n][0];
            p_xy[next][1]=p_xy[n][1];
        }
    }

    while(1){
        double angle = 999999.9;
        int next = -1;
        for(int i=0; i<n; i++){

            double temp_angle = angle_line_0_359(ans[*q-1][0], ans[*q-1][1], p_xy[i][0], p_xy[i][1]);
            if(M_PI<=temp_angle&&temp_angle<2*M_PI&& temp_angle<angle){
                angle=temp_angle;
                next=i;
            }

            if(temp_angle==angle){
                if(distance_between_the_two_pointss(ans[*q-1][0], ans[*q-1][1], p_xy[i][0], p_xy[i][1])<distance_between_the_two_pointss(ans[*q-1][0], ans[*q-1][1], p_xy[next][0], p_xy[next][1])){
                    next=i;
                }
            }



        }

        double angle2 = angle_line_0_359(p_xy[next][0], p_xy[next][1],ans[0][0], ans[0][1]);
        if(angle>angle2)break;
        //if(next==-1)break;
        else{
            ans[*q][0]=p_xy[next][0];
            ans[*q][1]=p_xy[next][1];

            *q=*q+1;

            n--;
            p_xy[next][0]=p_xy[n][0];
            p_xy[next][1]=p_xy[n][1];
        }
    }


}
