	int n = len(g);
	bool x = false;
	Point a, b;
	rep(i, 0, n) {
		a = g[i] - p;
		b = g[(i + 1) % n] - p;
		if(abs(cross(a, b)) < EPS && dot(a, b) < EPS) return 1;
