vector<Point> ConvexHull (vector<Point>& points, bool sortByAngle = false, bool includeMiddlePoint = false) {
  int n = (int) points.size();
  sort(points.begin(), points.end());
  if (sortByAngle) {
    auto compByAngle = [&] (const Point& p, const Point& q) {
      Point a = p - points[0];
      Point b = q - points[0];
      double e = a.y * b.x - a.x * b.y;
      return abs(e) < EPS ? norm(a) < norm(b) : e < 0;
    };
    sort(points.begin() + 1, points.end(), compByAngle);
  }
  int itr = 0;
  vector<Point> res(n * 2);
  for (int i = 0; i < n; ++i) {
    if (itr >= 2) {
      while (cross(res[itr- 1] - res[itr - 2], points[i] - res[itr - 2]) < (includeMiddlePoint ? -EPS : EPS)) {
        --itr;
        if (itr < 2) break;
      }
    }
    res[itr++] = points[i];
  }
  int bound = itr + 1;
  for (int i = n - 2; i >= 0; i--) {
    if (itr >= bound) {
      while (cross(res[itr- 1] - res[itr - 2], points[i] - res[itr - 2]) < (includeMiddlePoint ? -EPS : EPS)) {
        --itr;
        if (itr < bound) break;
      }
    }
    res[itr++] = points[i];
  }
  res.resize(itr - 1);
  return res;
}

