}

int contains(Polygon g, Point p){
  int n = g.size();
  bool x = false;
  for(int i = 0; i < n; i++){
    Point a = g[i] - p, b = g[(i + 1) % n] - p;
    if(abs(cross(a, b)) < EPS && dot(a, b) < EPS) return 1;
    if(a.y > b.y) swap(a, b);
    if(a.y < EPS && EPS < b.y && cross(a, b) > EPS) x = !x;
  }
  return (x ? 2 : 0);
}

void solve(){
  int n; cin >> n;
  vector<Point> p(n);
  for(int i = 0; i < n; i++){
    int x, y; cin >> x >> y;
    p[i] = Point(x, y);
  }
  sort(p.begin(), p.end());
  stack<Point> s, s2;
  s.push(p[0]);
  s.push(p[1]);
  for(int i = 2; i < n; i++){
    Point p1 = p[i];
    Point p0 = s.top(); s.pop();
    Point p2 = s.top();
    while(ccw(p0, p1, p2) == "COUNTER_CLOCKWISE"){
      p0 = p2;
      s.pop();
      if(s.size() == 0) break;
      p2 = s.top();
    }
    s.push(p0);
    s.push(p1);
  }
  s2.push(p[n - 1]);
  s2.push(p[n - 2]);
  for(int i = n - 3; i >= 0; i--){
    Point p1 = p[i];
    Point p0 = s2.top(); s2.pop();
    Point p2 = s2.top();
    while(ccw(p0, p1, p2) == "COUNTER_CLOCKWISE"){
      p0 = p2;
      s2.pop();
      if(s2.size() == 0) break;
      p2 = s2.top();
    }
    s2.push(p0);
    s2.push(p1);
  }
  vector<Point> ans;
  while(s2.size() > 0){
    ans.push_back(s2.top());
    //cout << s2.top().x << " " << s2.top().y << endl;
    s2.pop();
  }
  s.pop();
  while(s.size() > 1){
    ans.push_back(s.top());
    //cout << s.top().x << " " << s.top().y << endl;
    s.pop();
  }
  int m = ans.size();
  int mini = 0;
  for(int i = 1; i < m; i++){
    if(ans[i].y < ans[mini].y){
      mini = i;
    }
  }
  cout << m << endl;
  for(int i = 0; i < m; i++){
    Point p = ans[(i + mini) % m];
    cout << p.x << " " << p.y << endl;
  }
  return;
}

int main(){
  solve();
  return 0;
}

