typedef complex<double> P;

namespace std {
  bool operator < (const P& a, const P& b) {
    return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
  }
}

double cross(const P &a, const P &b){
    return imag(conj(a)*b);
}

double dot(const P &a, const P &b){
    return real(conj(a)*b);
}

int ccw(P a, P b, P c){
    b -= a;
    c -= a;
    if(cross(b,c) > 0) return +1;
    if(cross(b,c) < 0) return -1;
    if(dot(b,c) < 0) return +2;
    if(norm(b) < norm(c)) return -2;
    return 0;
}

void convexHull(vector<P> &G, vector<P> &ch){
    sort(G.begin(), G.end());
    int k=0;
    int n = G.size();
    for(int i=0;i<n;i++){
        while(k > 1 && cross((ch[k-1]-ch[k-2]), G[i] - ch[k-1])<0){
            k--;
        }
        ch[k] = G[i];
        k++;
    }
    int t = k;
    for(int i=n-2;i>=0;i--){
        while(k>t && cross((ch[k-1]-ch[k-2]), G[i] - ch[k-1])<0){
            k--;
        }
        ch[k] = G[i];
        k++;
    }

    ch.resize(k-1);
    cout <<k-1<< endl;
    for(int i=0;i<k-1;i++){
        cout << real(ch[i]) << " " << imag(ch[i]) << endl;
    }
}

int main(){
    int n;
    cin >> n;

    vector<P> G;
    P p;
    for (int i=0;i<n;i++){
        cin >> p.real() >> p.imag();
        G.push_back(p);
    }

    vector<P> ch(2*n);
    convexHull(G, ch);

    return 0;
}

