Polygon AndrewScan(Polygon &s)
{
	if (s.size() <= 2) return s;
	sort(s.begin(), s.end(), comp);
	Polygon g;
	for (int i = 0; i < s.size(); i++)
	{
		//CCW?????¨?????????==1???????????¨???????????????
		for (int n = g.size(); n >= 2 && CCW(g[n - 2], g[n - 1], s[i]) == COUNTER_CLOCKWISE; n--)
		{
			g.pop_back();
		}
		g.push_back(s[i]);
	}
	int upper_n = g.size();
	for (int i = s.size() - 2; i >= 0; i--)
	{
		for (int n = g.size(); n > upper_n && CCW(g[n - 2], g[n - 1], s[i]) == COUNTER_CLOCKWISE; n--)
		{
			g.pop_back();
		}
		g.push_back(s[i]);
	}
	reverse(g.begin(), g.end());
	g.pop_back();
	return g;
}

