typedef complex<double> Pt;
struct less_c{
    bool operator() (const Pt& a, const Pt& b){
        return a.imag()!=b.imag() ? a.imag()<b.imag() : a.real()<b.real();
    }
};
double cross(Pt a, Pt b){ //外積
    return a.real()*b.imag()-a.imag()*b.real();
}

int main(){
	int n;  cin >> n;
    vector<Pt> p(n);
    for(int i=0; i<n; i++){
        double x, y;   cin >> x >> y;
        p[i]={x,y};
    }
    sort(p.begin(),p.end(),less_c());

    vector<Pt> ch(2);  //convex hull
    for(int i=0; i<2; i++) ch[i]=p[i];
    for(int i=2; i<n; i++){
        for(int j=ch.size()-1; j>0; j--){
            if(cross(p[i]-ch[j],ch[j-1]-ch[j])<0){
                ch.erase(ch.begin()+j);
            }else{
                break;
            }
        }
        ch.push_back(p[i]);
    }

    int half=ch.size()-1;
    ch.push_back(p[n-2]);
    for(int i=n-3; i>=0; i--){
        for(int j=ch.size()-1; j>half; j--){
            if(cross(p[i]-ch[j],ch[j-1]-ch[j])<0){
                ch.erase(ch.begin()+j);
            }else{
                break;
            }
        }
        ch.push_back(p[i]);
    }
    ch.pop_back();

	cout << ch.size() << endl;
    for(Pt i : ch) cout << i.real() << " " << i.imag() << endl;
}

