int ccw(pt &p1, pt &p2){
    lf ans = (cross(p1 , p2) );
    if (-EPS <= ans && ans <= EPS)
        return 0;
    else if(ans <= -EPS)
        return -1;
    else
        return 1;
}

int ccw(pt& p1, pt& p2, pt& p3) {
  lf ans = (cross(p1 - p3, p2 - p3));
  if(-EPS <= ans && ans <= EPS)
    return 0;
  else if(ans <= -EPS)
    return -1;
  else
    return 1;
}

lf dist ( pt A, pt B ) { return abs(A-B); }


vector<pt> convex_hull(vector<pt> P){
	int n = P.size(); int k = 0;
	vector<pt> H(2*n);

	sort(P.begin(), P.end(), cmp);

	for (int i = 0; i < n; i++) {
		while (k >= 2 && ccw(H[k-2], H[k-1], P[i]) < 0) k--;
		H[k++] = P[i];
	}

	for (int i = n-2, t = k+1; i >= 0; i--) {
		while (k >= t && ccw(H[k-2], H[k-1], P[i]) < 0) k--;
		H[k++] = P[i];
	}

	if(n>1)
    k--;
	H.resize(k);
	return H;
}


