std::string clockwise(Point &p0, Point &p1, Point &p2)
{

    Vector a, b;
    a = p1 - p0;
    b = p2 - p0;

    auto cross_z = a.cross(b);

    if (cross_z > 0.0)
        return "COUNTER_CLOCKWISE";
    else if (cross_z < 0.0)
        return "CLOCKWISE";
    else
    {
        auto dot_prod = a.dot(b);
        if (dot_prod < 0.0)
            return "ONLINE_BACK";
        else if (b.abs() > a.abs())
            return "ONLINE_FRONT";
        else
        {
            return "ON_SEGMENT";
        }
    }
}

void convexHullHalf(Polygon &points, Polygon &convex_hull)
{
    for (auto p : points)
    {
        if (convex_hull.size() <= 1)
        {
            convex_hull.push_back(p);
            continue;
        }

        std::string loc = "COUNTER_CLOCKWISE";
        while (loc == "COUNTER_CLOCKWISE" && convex_hull.size() >= 2)
        {
            Point p1 = *(convex_hull.end() - 1);
            Point p0 = *(convex_hull.end() - 2);

            loc = clockwise(p0, p1, p);
            if (loc == "COUNTER_CLOCKWISE")
                convex_hull.pop_back();
        }

        convex_hull.push_back(p);
    }
}

Polygon convexHull(Polygon &points)
{
    Polygon convex_upper, convex_lower;

    std::sort(points.begin(), points.end(), [](Point a, Point b) { return a < b; });
    convexHullHalf(points, convex_upper);
    std::reverse(points.begin(), points.end());
    convexHullHalf(points, convex_lower);

    std::reverse(convex_lower.begin(), convex_lower.end());
    for (size_t i = convex_upper.size() - 2; i >= 1; --i)
    {
        convex_lower.push_back(convex_upper.at(i));
    }
    return convex_lower;
}

