    int n = p.size();
    sort(p.begin(), p.end());   
    vector<Point> ch(n + 1);

    int m = 0;
    for (int i = 0; i < n; i++) {
        while (m > 1 && dcmp(ccw(ch[m - 2], ch[m - 1], p[i])) < 0) {
            m--;
        }
        ch[m++] = p[i];
    }
    int k = m;
    for (int i = n - 2; i >= 0; i--) {
        while (m > k && dcmp(ccw(ch[m - 2], ch[m - 1], p[i])) < 0) {
            m--;
        }
        ch[m++] = p[i];
    }

    if (n > 1) {
        m--;
    }
    ch.resize(m);

    return ch;
}

