	scanf("%d",&n);
	for(int i=0;i<n;i++)scanf("%lf%lf",&p[i].x,&p[i].y);
	build();
	printf("%d\n",tot);
	for(int i=0;i<tot;i++){
		printf("%d %d\n",(int)P[i].x,(int)P[i].y);
	}
	return 0;
}

