const double EPS = 1e-8;
const double INF = 1e12;
const double PI = acos(-1);

using Point = complex<double>;
using Polygon = vector<Point>;

inline int sgn(const double &a) { return (a < -EPS ? -1 : (a > EPS ? 1 : 0)); }

inline bool eq(const Point &a, const Point &b) { return abs(a - b) < EPS; }

namespace std{
    inline bool operator<(const Point &a, const Point &b) {
        if (sgn(a.real() - b.real()))
            return sgn(a.real() - b.real()) < 0;
        return sgn(a.imag() - b.imag()) < 0;
    }
}

double dot(const Point &a, const Point &b) { return real(conj(a) * b); }

double det(const Point &a, const Point &b) { return imag(conj(a) * b); }

struct Line {
    Point p1, p2;

    Line(Point p1 = Point(), Point p2 = Point()) : p1(p1), p2(p2) {}

    bool operator<(const Line &rhs) const {
        if (eq(p2, rhs.p2))
            return p1 < rhs.p1;
        return p2 < rhs.p2;
    }
    bool operator==(const Line &rhs) const {
        return (eq(p1, rhs.p1) && eq(p2, rhs.p2)) ||
               (eq(p1, rhs.p2) && eq(p2, rhs.p1));
    }
};

enum CCW {
    ONLINE_FRONT = -2,
    CLOCKWISE,
    ON_SEGMENT,
    COUNTER_CLOCKWISE,
    ONLINE_BACK
};

int ccw(Point p0, Point p1, Point p2) {
    Point a = p1 - p0;
    Point b = p2 - p0;
    if (sgn(det(a, b)) == 1)
        return COUNTER_CLOCKWISE;
    if (sgn(det(a, b)) == -1)
        return CLOCKWISE;
    if (sgn(dot(a, b)) == -1)
        return ONLINE_BACK;
    if (sgn(norm(b) - norm(a)) == 1)
        return ONLINE_FRONT;
    return ON_SEGMENT;
}

Polygon convex_hull(Polygon s){
    int n = s.size(), k = 0;
    if(n < 3) return s;
    sort(s.begin(), s.end());

    Polygon ch(2*n);

    // 下側凸包
    for(int i=0;i<n;i++){
        while(k>=2 && ccw(ch[k-2], ch[k-1], s[i]) == CLOCKWISE)k--;
        ch[k++] = s[i];
    }

    // 上側凸包
    for(int i=n-2,t=k+1;i>=0;i--){
        while(k>=t && ccw(ch[k-2], ch[k-1], s[i]) == CLOCKWISE)k--;
        ch[k++] = s[i];
    }

    ch.resize(k-1);
    return ch;
}

