		rep(i,0,n-1) if (ccw(P[(i+n-1)%n],P[i],P[(i+1)%n])==-1) return 0;
		return 1;
	}
	inline ll contain(polygon P,const vec p){
		const ll n=P.size();
		bool x=false;
		rep(i,0,n-1){
			point a=P[i]-p,b=P[(i+1)%n]-p;
			if(abs(Cross(a,b))<=eps&&Dot(a,b)<=eps) return 1;
			if(a.y>b.y) swap(a,b);
			if(a.y<=eps&&eps<=b.y&&Cross(a,b)>=eps) x=!x;
		}
		return (x?2:0);
	}
	inline polygon convex_hull(polygon P){
		ll n=P.size(),k=0;
		if (n<3) return P;
		sort(P.begin(),P.end());
		polygon p(n<<1);
		for (ll i=0;i<n;p[k++]=P[i++])
			while (k>=2&&Cross(p[k-1]-p[k-2],P[i]-p[k-1])<0) --k;
		for (ll i=n-2,t=k+1;i>=0;p[k++]=P[i--])
			while (k>=t&&Cross(p[k-1]-p[k-2],P[i]-p[k-1])<0) --k;
		p.resize(k-1);
		return p;
	}
}
