	auto list1 = func(vector, [](const Vec &a, const Vec &b)->bool {return (a.cross(b) <= 0); });
	auto list2 = func(vector, [](const Vec &a, const Vec &b)->bool {return (a.cross(b) >= 0); });
	list1.pop_back(); list2.pop_front();
	std::printf("%d\n", list1.size() + list2.size());
	for (auto p1 = list1.begin(); p1 != list1.end();++p1) {
		p1->show();
	}
	for (auto p2 = list2.end(); p2 != list2.begin();) {
		(--p2)->show();
	}

	return 0;
}

