pair<Point, double> circumcircle(Point a, Point b, Point c){
    Point p;
    double r;
    int flag=ccw(a, b, c);
    if(flag==CCW_ONLINE_BACK){
        p=(b+c)/2;
        r=abs(b-p);
    }
    if(flag==CCW_ONLINE_FRONT){
        p=(a+c)/2;
        r=abs(a-p);
    }
    if(flag==CCW_ON_SEGMENT){
        p=(a+b)/2;
        r=abs(a-p);
    }
    else{
        Point M=(a+b)/2, N=(a+c)/2;
        Vec v={-(b-a).y, (b-a).x}, w={-(c-a).y, (c-a).x};
        p=getCrossPointLL(M, v, N, w);
        r=abs(a-p);
    }
    return {p, r};
}

