using namespace std;

struct Point{
	int x;
	int y;
	void display(){
		cout << x << " " << y << endl;
	}
};

int cross_product(Point O, Point A, Point B){
	return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
}

vector<Point> find_convex_hull(vector<Point> points){
	int n = points.size();
	if(n <= 2) return points;

	vector<Point> convex_hull(2 * n);
	sort(points.begin(), points.end(), [](Point p, Point q){ return p.y < q.y || (p.y == q.y && p.x < q.x);} );

	int hull_idx = 0;
	// build the lower hull
	for(auto i = 0; i < n; ++i){
		// suppose we have built a lower hull with >= 3 points
		while(hull_idx >= 2 && cross_product(convex_hull[hull_idx - 2], convex_hull[hull_idx - 1], points[i]) < 0){
			// if the candidate point violate the hull, reduce the hull
			--hull_idx;
		}
		convex_hull[hull_idx++] = points[i];
	}

	// save the last point of the lower hull
	int last_point = hull_idx - 1;
	// build the upper hull
	// start from the point before the last point
	for(auto i = n - 2; i >= 0; --i){
		// same, suppose we have built an upper hull with >= 3 points
		while(hull_idx >= last_point + 2 && cross_product(convex_hull[hull_idx - 2], convex_hull[hull_idx - 1], points[i]) < 0){
			--hull_idx;
		}
		convex_hull[hull_idx++] = points[i];
	}
	convex_hull.resize(hull_idx - 1);
	return convex_hull;
}

int main(){
	int n;
	cin >> n;
	vector<Point> points;
	for(auto i = 0; i < n; ++i){
		int x, y;
		cin >> x >> y;
		points.push_back({x, y});
	}

	vector<Point> convex_hull = find_convex_hull(points);

	cout << convex_hull.size() << endl;
	for(auto p: convex_hull){
		p.display();
	}
}

