        register int j = i;
        while (j >= 2 && point < P[j - 2]) {
            P[j - 1] = P[j - 2];
            j--;
        }
        P[j - 1] = point;
    }
    int k = 2;
    vector<Point> H(2 * n);
    H[0] = P[0];
    H[1] = P[1];
