namespace Polys{
    typedef vector<P> Poly,ConvexPoly;

    //O(n logn)
    ConvexPoly convex_hull(Poly ps) {
        int n = ps.size(), k = 0;
        sort(ALL(ps));
        Poly ch(2*n);
        REP(i,n){ // lower-hull
            while (k > 1 && cross(ch[k-1]-ch[k-2],ps[i]-ch[k-1]) < 0) --k;
            ch[k++]=ps[i];
        }
        for(int i=n-2,t=k;i>=0;i--){// upper-hull
            while (k > t && cross(ch[k-1]-ch[k-2],ps[i]-ch[k-1]) < 0) --k;
            ch[k++]=ps[i];
        }
        ch.resize(k-1);
        return ch;
    }
    void ccw_sort(ConvexPoly &ps,int i){
        sort(ps.begin()+1,ps.end(),[&ps,i](const P& l,const P& r) -> bool{
            int cw=ccw(ps[i],l,r);if(cw==0){
                cerr << ps[i]<<" "<< l << " " << r <<endl;
                assert(false);
            }
            return cw>0;
        });
    }
}
