    cin.tie(0);
    ios::sync_with_stdio(0);
    int n;
    cin >> n;
    vector<Point> pt(n);
    for (int i = 0; i < n; i++) {
        cin >> pt[i];
    }
    ConvexHull ch(pt);
    ch.build();
    cout << ch.size() << '\n';
    for (int i = 0; i < ch.size(); i++) {
        cout << ch[i] << '\n';
    }
}

