using namespace std;

struct Point {
	double x, y;
	bool operator < (const Point& p)const {
		if (y == y)return x < p.x;
		return y < p.y;
	}
};

Point sub(Point p1, Point p2) {
	Point p;
	p.x = p1.x - p2.x;
	p.y = p1.y - p2.y;
	return p;
}

double cross(Point v1, Point v2) {
	return v1.x * v2.y - v1.y * v2.x;
}

int main() {
	int n;
	vector<Point> P;
	vector<Point> U;
	vector<Point> L;

	cin >> n;
	for (int i = 0; i < n; i++) {
		Point p;
		cin >> p.x >> p.y;
		P.push_back(p);
	}

	sort(P.begin(), P.end());

	U.push_back(P[0]);
	U.push_back(P[1]);

	for (int i = 2; i < P.size(); i++) {
		while (U.size() > 1) {
			int s = U.size();
			Point v1 = sub(U[s - 1], U[s - 2]);
			Point v2 = sub(P[i], U[s - 2]);
			if (cross(v1, v2) >= 0)break;
			U.pop_back();
		}
		U.push_back(P[i]);
	}

	L.push_back(P[P.size() - 1]);
	L.push_back(P[P.size() - 2]);

	for (int i = P.size() - 3; i >= 0; i--) {
		while (L.size() > 1) {
			int s = L.size();
			Point v1 = sub(L[s - 1], L[s - 2]);
			Point v2 = sub(P[i], L[s - 2]);
			if (cross(v1, v2) >= 0)break;
			L.pop_back();
		}
		L.push_back(P[i]);
	}

	cout << U.size() + L.size() - 2 << endl;
	for (int i = 0; i < U.size(); i++) {
		cout << U[i].x << " " << U[i].y << endl;
	}
	for (int i = 1; i < L.size() - 1; i++) {
		cout << L[i].x << " " << L[i].y << endl;
	}

	return 0;

}

