int dcmp(double d) {
    if (fabs(d) < EPS) {
        return 0;
    }
    else {
        return d < 0? -1 : 1;
    }
}

struct Vector {
    double x, y;
    Vector(double x = 0, double  y = 0):x(x), y(y) {
    }

    bool operator< (const Vector& other) const {
        return dcmp(y - other.y) != 0? y < other.y : dcmp(x - other.x) < 0;
    }
};

typedef Vector Point;

struct PointCmp {
    bool operator()(const Point& a, const Point& b) {
        return (dcmp(a.y - b.y) < 0 || 
                (dcmp(a.y - b.y) == 0 && dcmp(a.x - b.x) < 0));
    }
};

