namespace geo {

/*      
 * Point c is
 *
 *         +1
 * ------------------
 *   +2  a    b  -2
 * ------------------
 *         -1
 */

int ccw(Point a, Point b, Point c) {
    b -= a; c -= a;
    if (cross(b, c) > 0)             return +1;
    if (cross(b, c) < 0)             return -1;
    if (dot(b, c) < 0)               return +2;
    if (std::norm(b) < std::norm(c)) return -2;
    return 0;
}

void ccw_sort(vec<Point> &v, Point o) {
    int lis[] = { -2, 1, 2, -1, };
    auto get_ccw_idx = [&](int c) {
        for (int i = 0; i < 4; i++) if (c == lis[i]) return i;
        return 4;
    };

    auto p = v[0];
    std::sort(v.begin() + 1, v.end(), 
              [&](Point a, Point b) {
                  if (a == b) return false;
                  int ca = ccw(o, p, a);
                  int cb = ccw(o, p, b);
                  if (ca != cb) return get_ccw_idx(ca) < get_ccw_idx(cb);
                  auto res = ccw(o, a, b);
                  if (std::abs(res) == 1) return res == 1;
                  return comp_like_pair(a, b);
              });
}

}

namespace geo {

vec<Point> build_convex_hull_incremental(vec<Point> pv) {
    std::sort(ALL(pv), comp_like_pair);
    auto minx = std::real(pv.front()),
         maxx = std::real(pv.back());

    {
        vec<Point> tmp;
        for (size_type i = 0; i < pv.size(); i++) {
            bool use = true;
            do {
                if (i == 0) break;
                if (i + 1 == pv.size()) break;
                auto pr = std::real(pv[i]);
                if (pr == minx) break;
                if (pr == maxx) break;
                if (pr != std::real(pv[i - 1])) break;
                if (pr != std::real(pv[i + 1])) break;
                use = false;
            } while (false);
            if (use) tmp.push_back(pv[i]);
        }
        size_type i = 0;
        while (i < tmp.size() && std::real(tmp[i]) == minx) i++;
        std::reverse(tmp.begin(), tmp.begin() + i);
        pv = std::move(tmp);
    }

    std::stack<Point, vec<Point>> ustk, lstk;
    size_type idx = 0;
    while (true) {
        auto p = pv[idx];
        bool f = (!ustk.empty() && std::real(p) != std::real(ustk.top()));
        ustk.push(pv[idx]);
        lstk.push(pv[idx]);
        idx++;
        if (f) break;
    }

    for (size_type i = idx; i < pv.size(); i++) {
        auto p = pv[i];
        while (2 <= ustk.size()) {
            auto p1 = ustk.top(); 
            ustk.pop();
            auto p2 = ustk.top();
            auto c = ccw(p, p1, p2);
            if (c == -1) continue;
            ustk.push(p1);
            break;
        }
        while (2 <= lstk.size()) {
            auto p1 = lstk.top();
            lstk.pop();
            auto p2 = lstk.top();
            auto c = ccw(p, p1, p2);
            if (c == 1) continue;
            lstk.push(p1);
            break;
        }
        ustk.push(p);
        lstk.push(p);
    }

    pv.clear();
    while (lstk.size()) {
        pv.push_back(lstk.top());
        lstk.pop();
    }
    std::reverse(ALL(pv));
    while (ustk.size()) {
        auto p = ustk.top();
        ustk.pop();
        if (std::real(p) == minx) continue;
        if (std::real(p) == maxx) continue;
        pv.push_back(p);
    }
    return pv;
}

}

int main() {
    ll n;
    std::cin >> n;
    vec<geo::Point> pv(n);
    for (auto &&e : pv) {
        ll x, y;
        std::cin >> x >> y;
        e = geo::Point(x, y);
    }

    auto res = geo::build_convex_hull_incremental(pv);
    auto to_swapped_pair = [&](const geo::Point &p) {
        geo::value_type x, y;
        geo::get_xy(x, y) = p;
        return std::make_pair(y, x);
    };
    ll idx = std::distance(res.begin(),
                           std::min_element(ALL(res), [&](const auto &p1, const auto &p2) {
                               return to_swapped_pair(p1) < to_swapped_pair(p2);
                           }));
    std::cout << res.size() << "\n";
    for (ll i = 0; i < res.size(); i++, idx++) {
        idx %= res.size();
        auto e = res[idx];
        ll x = std::real(res[idx]), y = std::imag(e);
        std::cout << x << ' ' << y << "\n";
    }
    return 0;
}

