	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%d%d", &x, &y); v.push_back(Point(x, y));
	vector<Point> ret = convex_hull(v);
	int p = 0;
	for (int i = 1; i < ret.size(); i++) {
		if (ret[p].py > ret[i].py || (ret[p].py == ret[i].py && ret[p].px > ret[i].px)) {
			p = i;
		}
	}
	cout << ret.size() << endl;
	for (int i = p; i < p + ret.size(); i++) cout << ret[i % ret.size()].px << ' ' << ret[i % ret.size()].py << endl;
	return 0;
}

