using namespace std;

class Point {
public:
    int x, y;
    Point(int a, int b) { 
        x = a;
        y = b; 
    }
    bool operator <(const Point &p) const {
        return y < p.y || (y == p.y && x < p.x);
    }
};

vector<Point> convex_hull(vector<Point>& P)
{
    int k = 1;
    int n = P.size();
    vector<Point> H;
    H.push_back(P[0]);
    H.push_back(P[1]);
    int i;
    for (i = 0; i < n - 2; i++) {
        while (k >= 1 && (H[k].x - H[k - 1].x) * (P[i + 2].y - H[k - 1].y) - (H[k].y - H[k - 1].y) * (P[i + 2].x - H[k - 1].x) < 0) {
            H.pop_back();
            k--;
        }
        H.push_back(P[i + 2]);
        k++;
    }
    H.push_back(P[n - 2]);
    for (i = n; i > 2; i--) {
        while ((H[k + 1].x - H[k].x) * (P[i - 3].y - H[k].y) - (H[k + 1].y - H[k].y) * (P[i - 3].x - H[k].x) < 0) {
            H.pop_back();
            k--;
        }
        H.push_back(P[i - 3]);
        k++;
    }
    H.pop_back();
    return H;
}

int main() {
    int n;
    scanf("%d", &n);
    vector<Point> P;
    int i;
    for (i = 0; i < n; i++) {
        int a, b;
        scanf("%d %d",&a, &b);
        Point point(a, b);
        P.push_back(point);
        int j = i + 1;
        while (j >= 2 && point < P[j - 2]) {
            P[j - 1] = P[j - 2];
            j--;
        }
        P[j - 1] = point;
    }
    vector<Point> H;
    H = convex_hull(P);
    printf("%d\n", H.size());
    for (i = 0; i < (int)H.size(); i++) {
        printf("%d %d\n", H[i].x, H[i].y);
    }
    return 0;
}

