int sgn(ld a, ld b = 0) {
	if (a > b + EPS) return 1;
	if (a < b - EPS) return -1;
	return 0;
}

ld dot(P a, P b) { return real(conj(a)*b); }
ld cross(P a, P b) { return imag(conj(a)*b); }

int ccw(P a, P b, P c) {
	b -= a;
	c -= a;
	if (sgn(cross(b, c))) return sgn(cross(b, c)); // clockwise(-1) or counter clockwise(1)
	if (sgn(dot(b, c)) == -1) return 2;            // c--a--b
	if (sgn(norm(b), norm(c)) == -1) return -2;    // a--b--c
	return 0;                                      // a--c--b
}

namespace std {
	bool operator < (P a, P b) {
		return sgn(real(a), real(b)) ? real(a) < real(b) : imag(a) < imag(b);
	}
}
G convex_hull(G g){
    int n = g.size();
	assert(n >= 3);

	sort(ALL(g));
    G c(n*2);
	int k = 0;
	REP(i, n) {
        while(k>=2 && ccw(c[k-2], c[k-1], g[i]) == -1) k--;
        c[k++] = g[i];
    }
	int t = k + 1;
	for (int i = n - 2; i >= 0; --i) {
		while (k >= t && ccw(c[k - 2], c[k - 1], g[i]) == -1) k--;
		c[k++] = g[i];
	}
    c.resize(k-1);
    return c;
}

