	REP(i, g2.size()) if (g2[i].imag() == under) if (d == -1 || g2[d].real() > g2[i].real()) d = i;

	cout << g2.size() << endl;
	REP(i, g2.size()) cout << (int)g2[(i+d)%g2.size()].real() << " " << (int)g2[(i+d)%g2.size()].imag() << endl;
	return 0;
}

