        if (res[i].y < minv) { minv = res[i].y; id = i; }
    }
    for(int i=id; i<id+res.size(); ++i) ans.push_back(res[i%res.size()]);
    cout << ans.size() << endl;
    for(auto p: ans) p.print();

    return 0;
}

