                    * (nCood.first - StartPoint.nnGetCood().first) 
                  + (nCood.second - StartPoint.nnGetCood().second)
                    *(nCood.second - StartPoint.nnGetCood().second);
        return;
    }
    std::pair<int,int>nnGetBCDCood()const{
    return nGCDCood;
    }
	double dGetArg(){
	return dArg;
	}
    double dGetLength_2()const{
	return dLength_2;
    }
};

