using namespace std;

#define EPS 1e-10
#define equals(a, b) (fabs((a) - (b)) < EPS)

class Point {
public:
  double x, y;
  Point() {};
  Point(double x, double y): x(x), y(y) {}

  Point operator + (const Point &p) { return Point(x + p.x, y + p.y); }
  Point operator - (const Point &p) { return Point(x - p.x, y - p.y); }
  Point operator * (double d) { return Point(d * x, d * y); }
  Point operator / (double d) { return Point(x / d, y / d); }

  bool operator < (const Point &p) const {
    return (x != p.x ? x < p.x : y < p.y);
  }

  bool operator == (const Point &p) const {
    return fabs(x - p.x) < EPS && fabs(y - p.y) < EPS;
  }

  friend ostream& operator << (ostream &os, Point &p) {
    return os << "Point(" << p.x << ", " << p.y << ")";
  }
};

double cross (Point p1, Point p2) {
  return p1.x * p2.y - p1.y * p2.x;
}

class Segment {
public:
  Point p1, p2;
  Segment(Point p1, Point p2): p1(p1), p2(p2) {}
};

bool cw(Segment s, Point p2) {
  if (cross(s.p2 - s.p1, p2 - s.p1) < EPS) return true;
  return false;
}

vector<Point> S;
vector<Point> U; // upper part
vector<Point> L; // lower part

void debug() {
  cout << "------- U" << endl;
  for (vector<Point>::iterator it = U.begin(); it != U.end(); it++)
    cout << (*it).x << ' ' << (*it).y << endl;

  cout << "------- L" << endl;
  for (vector<Point>::iterator it = L.begin(); it != L.end(); it++)
    cout << (*it).x << ' ' << (*it).y << endl;
}

bool search_start_p(Point a, Point b) {
  return (a.y == b.y ? a.x < b.x : a.y < b.y);
}

void andrew() {
  sort(S.begin(), S.end());

  for (int i = 0; i < 2; i++) {
    U.push_back(S[i]);
    L.push_back(S[S.size()-i-1]);
  }

  for (int i = 2; i < S.size(); i++) {
    for (int n = U.size(); n >= 2 && !cw(Segment(U[n-2], U[n-1]), S[i]); n--)
      U.pop_back();
    U.push_back(S[i]);
  }

  for (int i = S.size() - 3; i >= 0; i--) {
    for (int n = L.size(); n >= 2 && !cw(Segment(L[n-2], L[n-1]), S[i]); n--)
      L.pop_back();
    L.push_back(S[i]);
  }

  reverse(L.begin(), L.end());

  for (int i = U.size() - 2; i >= 1; i--) L.push_back(U[i]);

  Point ccw_begin_p = *min_element(L.begin(), L.end(), search_start_p);
  int idx = distance(L.begin(), find(L.begin(), L.end(), ccw_begin_p));

  cout << L.size() << endl;
  for (int i = 0; i < L.size(); i++) {
    cout << L[idx].x << ' ' << L[idx].y << endl;
    idx = (idx+1) % L.size();
  }
}

int main() {
  int n; cin >> n;

  for (int i = 0; i < n; i++) {
    double x, y; cin >> x >> y;
    S.push_back(Point(x, y));
  }

  andrew();
}

