/**
 * Problem statement:
 * Find the convex hull of a set of points.
 *
 * Tested with http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=CGL_4_A
 */

#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

struct Point {
    int x, y;

    Point(): x(0), y(0) {}
    Point(const Point &other): x(other.x), y(other.y) {}
    Point(int xx, int yy): x(xx), y(yy) {}

    void operator=(const Point &other) {
        x = other.x;
        y = other.y;
    }

    bool operator==(const Point &other) const {
        return x == other.x and y == other.y;
    }

    bool operator!=(const Point &other) const {
        return not ((*this) == other);
    }

    int operator*(const Point &other) const {
        return x * other.x + y * other.y;
    }

    Point operator-(const Point &other) const {
        return Point(x - other.x, y - other.y);
    }

    double norm() {
        return sqrt(x * x + y * y);
    }
};

double cosOfAngle(Point p, Point q) {
    return (p * q) / (p.norm() * q.norm());
}

vector<Point> convexHull(vector<Point> &points) {
    if (points.size() == 1) {
        return points;
    }

    Point lowest = points[0];
    for (Point &p : points) {
        if (p.y < lowest.y or (p.y == lowest.y and p.x < lowest.x)) {
            lowest = p;
        }
    }

    vector<Point> hull;
    hull.push_back(lowest);
    Point previous = lowest - Point(1, 0);
    Point current = lowest;
    while (true) {
        Point minAnglePoint = (points[0] != current) ? points[0] : points[1];
        double maxCos = cosOfAngle(minAnglePoint - current, current - previous);
        for (Point &p : points) {
            double cos = cosOfAngle(p - current, current - previous);
            if (p != current and
                (cos > maxCos or (cos == maxCos and (p - current).norm() < (minAnglePoint - current).norm()))) {
                minAnglePoint = p;
                maxCos = cos;
            }
        }

        if (minAnglePoint == lowest) {
            break;
        }

        hull.push_back(minAnglePoint);
        previous = current;
        current = minAnglePoint;
    }

    return hull;
}

int main() {
    int n; cin >> n;
    vector<Point> points(n);
    for (int i = 0; i < n; ++i) {
        cin >> points[i].x;
        cin >> points[i].y;
    }
    vector<Point> ch = convexHull(points);
    cout << ch.size() << endl;
    for (Point &p : ch) {
        cout << p.x << " " << p.y << endl;
    }

    return 0;
}

