yxp subt_pair(yxp a, yxp b) {
	return make_pair(a.first - b.first, a.second - b.second);
}

int cross_product(yxp a, yxp b) {
	return a.second*b.first - b.second*a.first;
}

int main() {
	yxp *p, *aa1, *aa2, vec1, vec2;
	int n, x, y, k, l;
	cin >> n;
	p = new yxp[n + 6];
	aa1 = new yxp[n + 6];
	aa2 = new yxp[n + 6];
	for (int i = 0; i < n; i++) {
		cin >> x >> y;
		p[i] = make_pair(y, x);
	}
	sort(p, p + n);
	aa1[0] = p[0];
	k = 0;
	for (int i = 1; i < n; i++) {
		if (p[i].first == p[i - 1].first) {
			continue;
		}
		if (k == 0) {
			aa1[++k] = p[i];
			continue;
		}
		for (; k > 0; k--) {
			vec1 = subt_pair(aa1[k], aa1[k - 1]);
			vec2 = subt_pair(p[i], aa1[k]);
			if (cross_product(vec1, vec2) <= 0) break;
		}
		aa1[++k] = p[i];
	}
	aa2[0] = p[0];
	l = 0;
	for (int i = 1; i < n; i++) {
		if (i != n - 1 && p[i].first == p[i + 1].first) {
			continue;
		}
		if (l == 0) {
			aa2[++l] = p[i];
			continue;
		}
		for (; l > 0; l--) {
			vec1 = subt_pair(aa2[l], aa2[l - 1]);
			vec2 = subt_pair(p[i], aa2[l]);
			if (cross_product(vec1, vec2) >= 0) break;
		}
		aa2[++l] = p[i];
	}

