#define f(i,n) for(int i=0;i<int(n);i++)
#define N (100010)
struct V{
	int x, y, z;
};
int n;
vector<V>a;
vector<V>con;
bool z;
bool compare(const V& v1, const V& v2){
	if (v1.y != v2.y)return v1.y < v2.y;
	else return v1.x < v2.x;
}

void convex_make(void){
	sort(a.begin(), a.end(), compare);
	int k = 0;
	V co[N];
	f(i, n){
		z = true;
		while (k > 1 && z){
			if ((co[k - 1].x - co[k - 2].x)*(a[i].y - co[k - 1].y) > (co[k - 1].y - co[k - 2].y)*(a[i].x - co[k - 1].x))k--;
			else z = false;
		}
		co[k] = a[i];
		k++;
	}
	int t = k;
	for (int i = n - 2; i >= 0; i--){
		z = true;
		while (k > t&&z){
			if ((co[k - 1].x - co[k - 2].x)*(a[i].y - co[k - 1].y) > (co[k - 1].y - co[k - 2].y)*(a[i].x - co[k - 1].x))k--;
			else z = false;
		}
		co[k] = a[i];
		k++;
	}
	con.clear();
	f(i, k - 1)con.push_back(co[i]);
	return;
}

