        t0 = left[m - 2];
        t1 = left[m - 1];
        t2 = data[i];

        if(cross(t1-t0, t2-t1) <= 0){
            left.push_back(t2);
        }
        else{
            while(cross(t1-t0, t2-t1) > 0){
                left.pop_back();
                m = left.size();
                if(m == 1) break;
                t0 = left[m-2];
                t1 = left[m-1];
            }
            left.push_back(t2);
        }
    }

    //右半分
    right.push_back(data[0]);
    right.push_back(data[1]);

    for(int i = 2; i < n; i++){
        int m = right.size();
        t0 = right[m - 2];
        t1 = right[m - 1];
        t2 = data[i];

        if(cross(t1-t0, t2-t1) >= 0){
            right.push_back(t2);
        }
        else{
            while(cross(t1-t0, t2-t1) < 0){
                right.pop_back();
                m = right.size();
                if(m == 1) break;
                t0 = right[m-2];
                t1 = right[m-1];
            }
            right.push_back(t2);
        }
    }

    cout << left.size() + right.size() - 2 << endl;
    for(int i=0; i<right.size(); i++){
        cout << right[i].x <<" "<<right[i].y<<endl;
    }
    for(int i=left.size()-2; i>0; i--){
        cout << left[i].x <<" "<<left[i].y<<endl;
    }

    return 0;
}

