D cross(P a, P b) { return a.x*b.y - a.y*b.x; }
D dot(P a, P b) { return a.x*b.x + a.y*b.y; }
// cross(a, b) is too small?
int sgncrs(P a, P b) {
    D cr = cross(a, b);
    if (abs(cr) <= (a.rabs() + b.rabs()) * EPS) return 0;
    return (cr < 0) ? -1 : 1;
}

// -2, -1, 0, 1, 2 : front, clock, on, cclock, back
int ccw(P b, P c) {
    int s = sgncrs(b, c);
    if (s) return s;
    if (!sgn(c.rabs()) || !sgn((c-b).rabs())) return 0;
    if (dot(b, c) < 0) return 2;
    if (dot(-b, c-b) < 0) return -2;
    return 0;
}
int ccw(P a, P b, P c) { return ccw(b-a, c-a); }
int ccw(L l, P p) { return ccw(l.s, l.t, p); }

using Pol = V<P>;

D area2(const Pol &pol) {
    D u = 0;
    P a = pol.back();
    for (auto b: pol) u += cross(a, b), a = b;
    return u;
}

// 0: outside, 1: on line, 2: inside
int contains(const Pol &pol, P p) {
    int in = -1;
    P _a, _b = pol.back();
    for (int i = 0; i < int(pol.size()); i++) {
        _a = _b; _b = pol[i];
        P a = _a, b = _b;
        if (ccw(a, b, p) == 0) return 1;
        if (a.y > b.y) swap(a, b);
        if (!(a.y <= p.y && p.y < b.y)) continue;
        if (sgn(a.y, p.y) ? (cross(a-p, b-p) > 0) : (a.x > p.x)) in *= -1;
    }
    return in + 1;
}

// p must be sorted and uniqued!
Pol convex_down(const Pol &ps) {
    assert(ps.size() >= 2);
    Pol dw;
    for (P d: ps) {
        size_t n;
        while ((n = dw.size()) > 1) {
            if (ccw(dw[n-2], dw[n-1], d) != -1) break; // line上も取る
//            if (ccw(dw[n-2], dw[n-1], d) == 1) break;
            dw.pop_back();
        }
        dw.push_back(d);
    }
    return dw;
}

Pol convex(Pol ps) {
    sort(begin(ps), end(ps));
    ps.erase(unique(begin(ps), end(ps)), end(ps));
    if (ps.size() <= 1) return ps;
    Pol dw = convex_down(ps);
    reverse(begin(ps), end(ps));
    Pol up = convex_down(ps);
    dw.insert(begin(dw), begin(up) + 1, end(up) - 1);
    return dw;
}

