//直線と直線の交点
Point getCrossPointLP(const Line &l1, const Line &l2) {
    assert(intersectLP(l1,l2)==1);
    return l1.p1 + (l1.p2-l1.p1)*cross(l2.p1-l1.p1,l2.p2-l2.p1)/cross(l1.p2-l1.p1,l2.p2-l2.p1);
}

//線分と線分の交点
Point getCrossPointSP(const Segment &s1, const Segment &s2) {
    assert(intersectSP(s1,s2));
    return getCrossPointLP(s1,s2);
}

//射影
Point project(const Segment &s, const Point &p) {
    Vector base = s.p2 - s.p1;
    DD r = dot(p - s.p1, base) / norm(base);
    return s.p1 + base * r;
}

//線対称
Point reflect(const Segment &s, const Point &p) {return p + (project(s,p) - p) * 2;}

//点と直線の距離
DD getDistanceLP(const Line &l, const Point &p) { return abs(cross(l.p2 - l.p1,p - l.p1) / abs(l.p2 - l.p1));}

//点と線分の距離
DD getDistanceSP(const Segment &s, const Point &p) {
    if (sgn(dot(s.p2 - s.p1,p - s.p1)) < 0) return abs(p - s.p1);
    if (sgn(dot(s.p1 - s.p2,p - s.p2)) < 0) return abs(p - s.p2);
    return getDistanceLP(s, p);
}

//直線と直線の距離
DD getDistanceLP(const Line &l1, const Line &l2) {
    if (intersectLP(l1,l2)) return 0;
    return getDistanceLP(l1,l2.p1);
}

//直線と線分の距離
DD getDistanceLSP(const Line &l, const Segment &s) {
    if (intersectLSP(l,s)) return 0;
    return min(getDistanceLP(l,s.p1),getDistanceLP(l,s.p2));
}

//線分と線分の距離
DD getDistanceSP(const Segment &s1, const Segment &s2) {
    if (intersectSP(s1, s2)) return 0;
    return min({getDistanceSP(s1, s2.p1), getDistanceSP(s1, s2.p2), getDistanceSP(s2, s1.p1), getDistanceSP(s2, s1.p2)});
}

//円と直線の交差判定
bool intersectLP(const Circle &c, const Line &l) { return sgn(getDistanceLP(l, c.c) - c.r) <= 0;}
//円と線分の交差判定
bool intersectSP(const Circle &c, const Segment &s) {
    return sgn(getDistanceSP(s,c.c) - c.r) <= 0 && sgn(max(abs(s.p1 - c.c),abs(s.p2 - c.c)) - c.r) >= 0;
}
//円と円の交差判定
int intersect(const Circle &c1, const Circle &c2) {
    if (sgn(abs(c1.c - c2.c) - (c1.r + c2.r)) > 0) return 4;     //2つの円が離れている場合
    if (!sgn(abs(c1.c - c2.c) - (c1.r + c2.r))) return 3;        //2つの円が外接する場合
    if (sgn(fabs(c1.r - c2.r) - abs(c1.c - c2.c)) > 0) return 0; //一方がもう一方を内包する場合
    if (!sgn(fabs(c1.r - c2.r) - abs(c1.c - c2.c))) return 1;    //2つの円が内接する場合
    return 2;                                                    //2つの円が交わる場合
}

//円と直線の交点
pair<Point, Point> getCrossPoints(const Circle &c, const Line &l) {
    assert(intersectLP(c,l));
    Vector pr = project(l, c.c);
    Vector e = (l.p2 - l.p1) / abs(l.p2 - l.p1);
    DD base = sqrt(c.r * c.r - norm(pr - c.c));
    return make_pair(pr + e * base, pr - e * base);
}

//円と円の交点
pair<Point, Point> getCrossPoints(const Circle &c1, const Circle &c2) {
    assert(intersect(c1, c2));
    DD d = abs(c1.c - c2.c);
    DD a = acos((c1.r * c1.r + d * d - c2.r * c2.r) / (c1.r * d * 2));
    DD t = arg(c2.c - c1.c);
    return make_pair(c1.c + polar(c1.r, t + a), c1.c + polar(c1.r, t - a));
}

//点pを通る円の接線
pair<Line, Line> tangent(const Circle &c, const Point &p) {
    assert(sgn(abs(c.c - p) - c.r) >= 0);
    if (!sgn(abs(c.c - p) - c.r)) {
        Point q = rot90(c.c - p);
        return pair<Line, Line>(Line(p,p+q), Line(p,p+q));
    } 
    Circle c2=Circle(p,sqrt(norm(c.c-p)-c.r*c.r));
    auto q = getCrossPoints(c,c2);
    return pair<Line, Line>(Line(p,q.first), Line(p,q.second));
}

//多角形の面積
DD area(const Polygon &g) {
    const int N = g.size();
    DD ret = 0;
    for (int i = 0; i < N; ++i) {
        ret += cross(g[i],g[(i+1)%N]);
    }
    return fabs(ret)/2;
}

//凸性判定
bool isConvex(const Polygon &g) {
    const int N = g.size();
    for (int i = 0; i < N; ++i) {
        if (ccw(g[i],g[(i+1)%N],g[(i+2)%N]) == -1) return 0;
    }
    return 1;
}

// 多角形-点の包含判定
int containment(const Polygon &g, const Point &p) {
    const int N = g.size();
    DD ang = 0;
    for (int i = 0; i < N; i++) {
        if (!ccw(g[i],g[(i+1)%N],p)) return 1; // pがgの辺上に存在する
        ang += atan2(cross(g[(i+1)%N] - p, g[i] - p), dot(g[(i+1)%N] - p, g[i] - p));
    }
    if (sgn(ang)) return 2; // pがgに含まれる
    return 0; // pがgに含まれない
}

//凸包
Polygon andrewScan(Polygon s) {
    Polygon u,l;
    const int N = s.size();
    if (N < 3) return s;
    sort(s.begin(), s.end(), ysort);
    u.emplace_back(s[0]);
    u.emplace_back(s[1]);
    l.emplace_back(s[N-1]);
    l.emplace_back(s[N-2]);

    for (int i = 2; i < s.size(); ++i) {
        // 凸包上の点も含めるなら ccw() == 1 含めないなら ccw() != -1
        for (int n = u.size(); n >= 2 && ccw(u[n-2],u[n-1],s[i]) == 1; --n) {
            u.pop_back();
        }
        u.emplace_back(s[i]);
    }

    for (int i = N - 3; i >= 0; --i) {
        // 凸包上の点も含めるなら ccw() == 1 含めないなら ccw() != -1
        for (int n = l.size(); n >= 2 && ccw(l[n-2], l[n-1], s[i]) == 1; --n) {
            l.pop_back();
        }
        l.emplace_back(s[i]);
    }

    reverse(l.begin(), l.end());
    for (int i = u.size() - 2; i >= 1; --i) l.emplace_back(u[i]);

    return l;
}

//最遠点対
DD farthestpointpair(const Polygon &g) {
    const int N = g.size();
    if (N == 2) return abs(g[1] - g[0]);
    int i = 0, j = 0;
    for (int k = 0; k < N; ++k) {
        if (g[k].y > g[i].y) i = k;
        if (g[k].y < g[j].y) j = k;
    }

    DD ret = 0;
    int si = i, sj = j;
    while (i != sj || j != si) {
        ret = max(ret, abs(g[i]-g[j]));
        if (cross(g[(i+1)%N] - g[i], g[(j+1)%N] - g[j]) < -EPS) {
            i = (i+1)%N;
        } else {
            j = (j+1)%N;
        }
    }

    return ret;
}

