    Polygon p(n);
    rep(i,n){
        Real x,y;
        cin >> x >> y;
        p[i] = Point(x,y);
    }
    Polygon q = andrewScan(p);
    printf("%d\n", (int)q.size());
    int d = min_element(all(q), comp_y) - q.begin();
    rep(i,q.size()){
        int x = q[(i+d)%q.size()].x;
        int y = q[(i+d)%q.size()].y;
        printf("%d %d\n", x,y);
    }
};

