inline void convex_hull(const vector<Point>& P)
{
    int k = 2;
    int n = P.size();
    vector<Point> H(2 * n);
    H[0] = P[0];
    H[1] = P[1];
    int i;
    for (i = 0; i < n - 2; ++i) {
        while (k >= 2 && (H[k - 1].x - H[k - 2].x) * (P[i + 2].y - H[k - 2].y) - (H[k - 1].y - H[k - 2].y) * (P[i + 2].x - H[k - 2].x) < 0) k--;
        H[k++] = P[i + 2];
    }
    H[k++] = P[n - 2];
    for (i = n; i > 2; i--) {
        while (k >= 2 && (H[k - 1].x - H[k - 2].x) * (P[i - 3].y - H[k - 2].y) - (H[k - 1].y - H[k - 2].y) * (P[i - 3].x - H[k - 2].x) < 0) k--;
        H[k++] = P[i - 3];
    }
    H.resize(k - 1);
    printf("%d\n", k - 1);
    for (i = 0; i < k - 1; ++i) {
        printf("%d %d\n", H[i].x, H[i].y);
    }
}

int main() {
