//内積
double dot(P a, P b) {
  return (a * conj(b)).real();
}

//外積
double cross(P a, P b) {
  return (conj(a) * b).imag();
}

//反時計回り
int ccw(P a, P b, P c){
  if(cross(b-a,c-a) > 0) return 1; //COUNTER_CLOCKWISE
  if(cross(b-a,c-a) < 0) return -1; //CLOCKWISE
  if(dot(b-a,c-a) < 0) return -2; //ONLINE_BACK
  if(dot(a-b,c-b) < 0) return 2; //ONLINE_FRONT
  return 0; //ON_SEGMENT
}

/* ConvexHull(凸包) */

vector<P> ConvexHull(vector<P> s){
  vector<P> g;
  int m, n = (int)s.size();

  if(n<3) return s;

  sort(s.begin(),s.end());

  for(int i=0;i<n;i++){
    while((m = g.size()) >= 2 && ccw(g[m-2],g[m-1],s[i]) <= 0) g.pop_back();     
    g.push_back(s[i]);
  }

  int t = (int)g.size();

  for(int i=n-2;i>=0;i--){
    while((m = g.size()) > t && ccw(g[m-2],g[m-1],s[i]) <= 0) g.pop_back();     
    g.push_back(s[i]);
  }

  g.pop_back();

  return g; //反時計回り
}


