bool ptcomp(pt a,pt b){return make_pair(a.x,a.y)<make_pair(b.x,b.y);}
pt p[M];
vector<pt>hull;
int n;
void makeUB()
{
	hull.push_back(p[0]);
	for(int i=1;i<n;i++)
	{
		while(hull.size()>1 && cross(hull[hull.size()-2],hull.back(),p[i])>0)
			hull.pop_back();
		hull.push_back(p[i]);
	}
}
void makeLB()
{
	int hs=hull.size();
	for(int i=n-2;i>=0;i--)
	{
		while(hull.size()>hs && cross(hull[hull.size()-2],hull.back(),p[i])>0)
			hull.pop_back();
		hull.push_back(p[i]);
	}
}
