            y1=max(A.y,D.y);
            y2=min(B.y,C.y);
        }
    }
    int id=0;
    f(i,0,np){
        if (np<4 || !inside(x1,y1,x2,y2,tp[i].x,tp[i].y)){
            p[id++]=tp[i];
        }
    }
    np=id;

    conh(np,m);
	pfl(m);
	f(i,0,m) pf("%lld %lld\n",c[i].x,c[i].y);
}

