		for(int v=u.size(); v>=2 && ck(u[v-2],u[v-1],s[i])!=1;v--) {u.pop_back();}
		u.push_back(s[i]);
	}
	for(int i=s.size()-3;i>=0;i--){
		for(int v=l.size(); v>=2 && ck(l[v-2],l[v-1],s[i])!=1;v--) {l.pop_back();}
		l.push_back(s[i]);
	}
