//	printf("l\n");for(int i=0;i<l.size();i++) printf("%d %d\n",(int)l[i].x,(int)l[i].y);printf("\n");
	reverse(l.begin(),l.end());
	for(int i=u.size()-2;i>=1;i--) l.push_back(u[i]);
