using namespace std;

const double eps = 1e-10;

class Vector
{
public:
  double x;
  double y;

  Vector(){}
  Vector( double x, double y ) : x(x), y(y) {}

  Vector operator + ( const Vector v ) { return Vector( x + v.x, y + v.y ); }
  Vector operator - ( const Vector v ) { return Vector( x - v.x, y - v.y ); }
  Vector operator * ( const double k ) { return Vector( x * k, y * k ); }
  Vector operator / ( const double k ) { return Vector( x / k, y / k ); }
  bool operator < ( const Vector &v ) const { if ( x == v.x ) return y < v.y; else return x < v.x; }
  bool operator == ( const Vector &v ) const { return x == v.x && y == v.y; }
  bool operator != ( const Vector &v ) const { return x != v.x || y != v.y; }
  double abs() { return sqrt( norm() ); }
  double norm() { return x * x + y * y; }

  static double dot( Vector v1, Vector v2 ) { return v1.x * v2.x + v1.y * v2.y; }
  static double cross( Vector v1, Vector v2 ) { return v1.x * v2.y - v1.y * v2.x; }
};

class ConvexHull
{
public:
  int n;
  vector<Vector> v;
  ConvexHull(){}
  ConvexHull( int n ) : n(n), v(n) {}
  int solve();
};

int ConvexHull::solve()
{
  sort( v.begin(), v.end() );

  list<Vector> ret;

  ret.push_back( v[0] );
  ret.push_back( v[1] );

  for ( auto i = 2; i < n; ++i )
    {
      auto it = ret.rbegin();
      Vector p2 = *it;
      ++it;
      Vector p1 = *it;

      while ( ret.size() >= 2 && Vector::cross( p2 - p1, v[i] - p2 ) > eps )
        {
          ret.pop_back();
          it = ret.rbegin();
          p2 = *it;
          ++it;
          p1 = *it;
        }

      ret.push_back( v[i] );
    }

  ret.push_back( v[n-2] );

  for ( auto i = n - 3; i >= 0; --i )
    {
      auto it = ret.rbegin();
      Vector p2 = *it;
      ++it;
      Vector p1 = *it;

      while ( ret.size() >= 2 && Vector::cross( p2 - p1, v[i] - p2 ) > eps )
        {
          ret.pop_back();
          it = ret.rbegin();
          p2 = *it;
          ++it;
          p1 = *it;
        }

      ret.push_back( v[i] );
    }

  ret.pop_back();

  auto it = ret.begin();
  Vector pm = *it;

  while ( it != ret.end() )
    {
      if ( pm.y > (*it).y )
        pm = *it;
      ++it;
    }

  while ( ret.back() != pm )
    {
      ret.push_front(ret.back());
      ret.pop_back();
    }

  cout << ret.size() << endl;

  for ( auto it = ret.rbegin(); it != ret.rend(); ++it )
    cout << (*it).x << " " << (*it).y << endl;
  return 0;
}

int main()
{
  int n;
  cin >> n;

  ConvexHull ch(n);

  for ( auto i = 0; i < n; ++i )
    {
      double x, y;
      cin >> x >> y;
      ch.v[i] = Vector( x, y );
    }

  ch.solve();

  return 0;
}

