using namespace std;

constexpr double EPS = 1e-10;
using Point = complex<double>;
using Line  = pair<Point, Point>;

double dot(Point p, Point q) { return (conj(p) * q).real(); }
double cross(Point p, Point q) { return (conj(p) * q).imag(); }

vector<Point> convex_hull(vector<Point> &ps) {
    sort(ps.begin(), ps.end(), [&](Point a, Point b){ 
                if(a.imag() != b.imag()) return a.imag() < b.imag();
                return a.real() < b.real();
            });
    int n = (int)ps.size(), k = 0;
    vector<Point> res(n * 2);
    // lower side of convex hull
    for(int i = 0; i < n; res[k++] = ps[i++]) 
        while(k >= 2 && cross(res[k-1] - res[k-2], ps[i] - res[k-1]) < -EPS) --k; 
    // use "< -EPS", include corner or boundary, "< EPS", not include

    // upper side
    for(int i = n - 2, t = k+1; i >= 0; res[k++] = ps[i--])
        while(k >= t && cross(res[k-1] - res[k-2], ps[i] - res[k-1]) < -EPS) --k;

    res.resize(k - 1);
    return res;
}

int main() {
    cin.tie(0); ios_base::sync_with_stdio(false);
    int n; cin >> n; 
    vector<Point> ps;
    for(int i=0; i < n; ++i) {
        double x,y; cin >> x >> y;
        ps.emplace_back(x,y);
    }
    auto qs = convex_hull(ps);
    cout << qs.size() << '\n';
    for(int i=0; i < (int)qs.size(); ++i) {
        cout << qs[i].real() << " " << qs[i].imag() << '\n';
    }
    return 0;
}

