int inPolygon(const G& pol, const P& p) {
  bool in = false;
  for (int i = 0; i < pol.size(); ++i) {
  	P a = pol[i] - p, b = pol[(i+1)%pol.size()] - p;
    if (imag(a) > imag(b)) swap(a, b);
    cout << i << " " << det(a, b) << endl;
    if (imag(a) <= 0 && 0 < imag(b) && sgn(det(a, b)) < 0) {
      cout << "rev" << endl;
      in = !in;
    }
    if (sgn(det(a, b)) == 0 && sgn(dot(a, b)) <= 0) return 1;
  }
  return in ? 2 : 0;
}

// 凸包 3点が一直線上に並ぶときに注意
G convex_hull(G ps) {
  int n = ps.size(), k = 0;
  sort(ps.begin(), ps.end());
  G r(2*n);
  for(int i=0; i<n; i++){
    while(k>1 && ccw(r[k-2],r[k-1],ps[i])==RIGHT) k--;
    r[k++] = ps[i];
  }
  for(int i=n-2,t=k; i>=0; i--){
    while(k>t && ccw(r[k-2],r[k-1],ps[i])==RIGHT) k--;
    r[k++] = ps[i];
  }
  r.resize(k-1);
  return r;
}

