    Polygon polygon;
    for (int i = 0; i < n; ++i) {
        Point p;
        cin >> p;
        polygon.emplace_back(p);
    }

    Polygon ans = ConvexHull(polygon);

    // 最もしたにあるやつ
    Real bottom = 1000000.0;
