Polygon convex_hull(Polygon P) {
    sort(P.begin(), P.end());  //??????
    P.erase(unique(P.begin(), P.end()), P.end());  //???????????????
    int n = P.size(), k = 0;
    Polygon Q(n*2);
    for (int i=0; i<n; ++i) {
        while (k > 1 && cross(Q[k-1]-Q[k-2], P[i]-Q[k-2]) < 0) k--;
        Q[k++] = P[i];
    }
    for (int t=k, i=n-2; i>=0; --i) {
        while (k > t && cross(Q[k-1]-Q[k-2], P[i]-Q[k-2]) < 0) k--;
        Q[k++] = P[i];
    }
    Q.resize(k-1);
    return Q;
}

