struct POINT {
    int x;
    int y;
    int Norm;
};

bool operator<(const POINT& a, const POINT & b) {
    if (a.x * b.y - a.y * b.x != 0) {
        return a.x * b.y - a.y * b.x > 0;    //偏角の大小で順序を定める
    }
    else {
        return a.Norm < b.Norm;    //偏角が等しい場合基準点との距離で見る
    }
};

int main() {
    int n;
    scanf("%d", &n);
    int iStart = 0;    //探索を始める点  y座標最小となる点(x[iStart],y[iStart])をとる
    int x[n], y[n];

    for (int i = 0; i < n; i++) {
        scanf("%d %d", &x[i], &y[i]);
        if (y[i] < y[iStart]) {
            iStart = i;
        }
        if (y[i] == y[iStart] && x[i] < x[iStart]) {
            iStart = i;
        }

    }


    vector<POINT> vzPoint;
    for (int i = 0; i < n; i++) {
        POINT zPoint;
        zPoint.x = x[i] - x[iStart];
        zPoint.y = y[i] - y[iStart];
        zPoint.Norm = (x[i] - x[iStart]) * (x[i] - x[iStart]) + (y[i] - y[iStart]) * (y[i] - y[iStart]);
        vzPoint.push_back(zPoint);
    }
    sort(vzPoint.begin(), vzPoint.end());

    vector<int> viPoint;
    viPoint.push_back(0);
    viPoint.push_back(1);
    for (int i = 2; i < n; i++) {
        while (viPoint.size() >= 2) {
            int j1 = viPoint.back();
            viPoint.pop_back();
            int j0 = viPoint.back();
            int x1, x2, y1, y2;
            x1 = vzPoint[j1].x - vzPoint[j0].x;
            y1 = vzPoint[j1].y - vzPoint[j0].y;
            x2 = vzPoint[i].x - vzPoint[j1].x;
            y2 = vzPoint[i].y - vzPoint[j1].y;
            if (x1 * y2 - x2 * y1 >= 0) {
                viPoint.push_back(j1);
                break;
            }
        }
        viPoint.push_back(i);
    }

    while (viPoint.size() >= 2) {     //ここ実はいらない  ∵最後に加えた点は偏角最大なので
        int j1 = viPoint.back();
        viPoint.pop_back();
        int j0 = viPoint.back();
        int x1, x2, y1, y2;
        x1 = vzPoint[j1].x - vzPoint[j0].x;
        y1 = vzPoint[j1].y - vzPoint[j0].y;
        x2 = vzPoint[0].x - vzPoint[j1].x;
        y2 = vzPoint[0].y - vzPoint[j1].y;
        if (x1 * y2 - x2 * y1 >= 0) {
            viPoint.push_back(j1);
            break;
        }
    }

    //最後に得られた辺上の点が除かれてしまっているので遠くから順に与える
    int iEnd = viPoint.back();
    for(int i = vzPoint.size() - 1; i > 0; i--){    //vzPointは偏角が同じものはノルムが小さい順にソートされているので逆順にみる
        if(i == iEnd){    //最後に加えた頂点は無視
            continue;
        }
        int x1,x2,y1,y2;
        x1 = vzPoint[i].x - vzPoint[0].x;
        y1 = vzPoint[i].y - vzPoint[0].y;
        x2 = vzPoint[iEnd].x - vzPoint[0].x;
        y2 = vzPoint[iEnd].y - vzPoint[0].y;
        if(x1 * y2 - x2 * y1 != 0){    //偏角が異なる点が出てきたら終わる
            break;
        }
        viPoint.push_back(i);
    }


    printf("%d\n", viPoint.size());
    for (int i = 0; i < viPoint.size(); i++) {
        printf("%d %d\n", vzPoint[viPoint[i]].x + x[iStart], vzPoint[viPoint[i]].y + y[iStart]);
    }
    return 0;
}

