typedef struct { double x,y; }Point;

Point p0 = {1000000,1000000};

double abs(const Point p){ return sqrt(p.x*p.x + p.y*p.y); }


//counter-clockwise (p1 -> p2 -> p3)
int ccw(Point p1, Point p2, Point p3){
  //calc z of vec(p1p2) x vec(p2p3)
  double z = (p2.x-p1.x)*(p3.y-p2.y) - (p2.y-p1.y)*(p3.x-p2.x);
  return z; //pos:clockwise  ,  neg:ccw  ,  0:straight
}


//sort by polar angle.
bool compare(const Point& p1, const Point& p2){
  double base = atan2(p0.x, p0.y);   if(base<0)base+=2*M_PI;
  double angle1 = atan2(p1.x, p1.y); if(angle1<0)angle1+=2*M_PI;
  double angle2 = atan2(p2.x, p2.y); if(angle2<0)angle2+=2*M_PI;
  angle1 += 2*M_PI - base;
  angle2 += 2*M_PI - base;

  if(angle1 != angle2)
    return angle1 < angle2;

  return abs(p1) < abs(p2);
}

int main(){

  int N;
  vector<Point> points;
  stack<Point> stk;

  double ymin = 1000000;

  cin >> N;
  for(int i=0; i<N; i++){
    double x,y;
    cin >> x >> y;
    points.push_back((Point){x,y});

    if( y < ymin || (y==ymin && x<p0.x)){ ymin = y; p0.x=x, p0.y=y; }
  }


  //sort by polar angle
  sort(points.begin() , points.end() , compare);


  //remove points which has same polar angle
  for(auto i=points.begin(); (i+1)!=points.end(); i++){
    Point p1 = *i;
    Point p2 = *(i+1);
    double angle1 = atan2(p1.x , p1.y);
    double angle2 = atan2(p2.x , p2.y);

    if(angle1 == angle2){
      if( abs(p1) > abs(p2) )points.erase(i+1);//remove p2
      else points.erase(i);		  
      i--;
    }
  }


  //test
  /*
  cout << "P0 = ("<<p0.x<<","<<p0.y<<") "<< atan2(p0.x,p0.y)*180/M_PI << endl;
  for(Point p : points){
    cout << "("<<p.x<<","<<p.y<<") "<< atan2(p.x,p.y)*180/M_PI << endl;
  }
  cout << "============================"<<endl;
  */

  //solve with Graham Scan
  for(int i=0; i<points.size(); i++){
    if(stk.size() >= 2){
      Point top = stk.top(); stk.pop();
      Point next_top = stk.top(); stk.push(top);

      while(stk.size()>2 && ccw(next_top , top, points[i]) > 0 ){
	stk.pop();
	top = next_top; stk.pop();
	next_top = stk.top(); stk.push(top);
      }
    }
    stk.push(points[i]);

  }


  //output
  cout << stk.size() << endl;
  while( ! stk.empty() ){
    Point p = stk.top(); stk.pop();
    cout << (int)p.x << " " << (int)p.y << endl ;
  }

  return 0;
}

