    P = new Point[n];
    for (i = 1; i <= n; ++i) {
        scanf_s("%d%d",&P[i - 1].x, &P[i - 1].y);
        Point point = P[i - 1];
        int j;
        for (j = i; j >= 2 && point < P[j - 2]; j--) {
            P[j - 1] = P[j - 2];
        }
        P[j - 1] = point;
    }
    H = new Point[2*n];
    H[0] = P[0];
    H[1] = P[1];
    for (i = 0; i < n - 2; ++i) {
        while (k >= 2 && direct(H[k - 2],H[k - 1],P[i + 2])) k--;
        H[k++] = P[i + 2];
    }
    H[k++] = P[n - 2];
    for (i = n; i > 2; i--) {
        while (k >= 2 && direct(H[k - 2],H[k - 1],P[i - 3])) k--;
        H[k++] = P[i - 3];
    }
    printf("%d\n", k - 1);
    for (i = 0; i < k - 1; ++i) {
        printf("%d %d\n", H[i].x, H[i].y);
    }
    return 0;
}

#include <iostream>
