using namespace std;

class Point {
public:
    int x, y;
    Point(int a, int b) { 
        x = a;
        y = b; 
    }
    Point() : x(0), y(0) 
    {
    }
    bool operator <(const Point &p) const {
        return x < p.x || (x == p.x && y < p.y);
    }
};

double outer_product(const Point &O, const Point &A, const Point &B)
{
    return (A.x - O.x) * (B.y - O.y) - (A.y - O.y) * (B.x - O.x);
}

vector<Point> convex_hull(vector<Point> P)
{
    int n = P.size(), k = 0;
    if (n == 1) return P;
    vector<Point> H(2*n);

    sort(P.begin(), P.end());

    for (int i = 0; i < n; ++i) {
        while (k >= 2 && outer_product(H[k-2], H[k-1], P[i]) <= 0) k--;
        H[k++] = P[i];
    }

    for (int i = n-2, t = k+1; i >= 0; i--) {
        while (k >= t && outer_product(H[k-2], H[k-1], P[i]) <= 0) k--;
        H[k++] = P[i];
    }

    H.resize(k-1);
    return H;
}

int main()
{
    int n;
    cin >> n;
    vector<Point> P(n);
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        Point point(a, b);
        P.push_back(point);
    }
    vector<Point> H = convex_hull(P);
    for (int i = 0; i < n; i++) {
        cout << H.at(i).x << H.at(i).y << endl;
    }
    return 0;
}

