double cross(Vector2 p0, Vector2 p1, Vector2 p2) {
  return (p2 - p1).cross(p0 - p1);
}

void format(Vector2 &p) {
  cout << p.x << ' ' << p.y;
}

vector<Vector2> convex_hull(vector<Vector2> &points, Int N) {
  int n = N, k = 0;
  sort(points.begin(), points.end());
  vector<Vector2> ch(2*n);
  for (int i = 0; i < n; ch[k++] = points[i++])
    while (k >= 2 && cross(ch[k-2], ch[k-1], points[i]) < 0) --k;
  for (int i = n-2, t = k+1; i >= 0; ch[k++] = points[i--])
    while (k >= t && cross(ch[k-2], ch[k-1], points[i]) < 0) --k;
  ch.resize(k-1);
  return ch;
}

Int bottomleft_index(vector<Vector2> &points) {
  Int index = 0;
  Vector2 min_ = points[0];
  loop(n,1,points.size()) {
    if (points[n].y < min_.y) min_ = points[n],index = n;
    else if (points[n].y == min_.y && points[n].x < min_.x) min_ = points[n],index = n;
  }
  return index;
}

void solve() {
  vector<Vector2> result = convex_hull(points, N);
  cout << result.size() << endl;
  Int index = bottomleft_index(result);
  loop(n,index,result.size()) format(result[n]),cout << endl;
  loop(n,0,index) format(result[n]),cout << endl;
}

void input() {
  cin >> N;
  loop(n,0,N) cin >> points[n];
  points.resize(N);
}

int main() {
  cout.precision(15);
  input();
  solve();
}

