}


vector <point> Convex_Hull(vector <point> a){
  vector<point> b,c;
  if(a.size()<3) return a;
  sort(a.begin(),a.end());  

  b.push_back(a[0]);
  b.push_back(a[1]);
  for(int i=2;i<a.size();i++){
    //CLOCKWISE or ON_SEGMENT
    for(int j=b.size();j>=2&&ccw(b[j-2],b[j-1],a[i])!=-1&&ccw(b[j-2],b[j-1],a[i])!=-2;j--)b.pop_back();
    b.push_back(a[i]);
  }

  c.push_back(a.back());
  c.push_back(a[a.size()-2]);
  for(int i=a.size()-3;i>=0;i--){
    //CLOCKWISE or ON_SEGMENT
    for(int j=c.size();j>=2&&ccw(c[j-2],c[j-1],a[i])!=-1&&ccw(c[j-2],c[j-1],a[i])!=-2;j--) c.pop_back();
    c.push_back(a[i]);
  }
    reverse(c.begin(),c.end());
  for(int i=b.size()-2;i>=1;i--) c.push_back(b[i]);
  return c;
}

