    {
    };
    Point()
    {
        int x = 0;
        int y = 0;
    }
    bool operator <(const Point &p) const {
        return y < p.y || (y == p.y && x < p.x);
    }
};

inline void convex_hull(const std::vector<Point>& P)
{
    int k = 2;
    int n = P.size();
    std::vector<Point> H;
    H.resize(2 * n);
    H[0] = P[0];
    H[1] = P[1];
    int i;
    for (i = 0; i < n - 2; i++) {
        while (k >= 2 && (H[k - 1].x - H[k - 2].x) * (P[i + 2].y - H[k - 2].y) - (H[k - 1].y - H[k - 2].y) * (P[i + 2].x - H[k - 2].x) < 0) k--;
        H[k++] = P[i + 2];
    }
    H[k++] = P[n - 2];
    for (i = n; i > 2; i--) {
        while (k >= 2 && (H[k - 1].x - H[k - 2].x) * (P[i - 3].y - H[k - 2].y) - (H[k - 1].y - H[k - 2].y) * (P[i - 3].x - H[k - 2].x) < 0) k--;
        H[k++] = P[i - 3];
    }
    H.resize(k - 1);
    printf("%d\n", H.size());
    for (i = 0; i < H.size(); i++) {
        printf("%d %d\n", H[i].x, H[i].y);
    }
}

int main() {
    int n;
    scanf("%d", &n);
    std::vector<Point> P(n);
    int i;
    for (i = 0; i < n; i++) {
        Point point;
        scanf("%d %d",&point.x, &point.y);
        P[i] = point;
        int j = i + 1;
        while (j >= 2 && point < P[j - 2]) {
            P[j - 1] = P[j - 2];
            j--;
        }
        P[j - 1] = point;
    }
    convex_hull(P);
    return 0;
}

