// 凸包
VP convexHull(VP ps) {
  int n = ps.size(), k = 0;
  sort(ps.begin(), ps.end());
  VP ch(2*n);
  for (int i = 0; i < n; ch[k++] = ps[i++])
    while (k >= 2 && ccw(ch[k-2],ch[k-1],ps[i]) == -1) --k;  // 余計な点も含むなら == -1 とする
  for (int i = n-2, t = k+1; i >= 0; ch[k++] = ps[i--])
    while (k >= t && ccw(ch[k-2],ch[k-1],ps[i]) == -1) --k;  // 余計な点も含むなら == -1 とする
  ch.resize(k-1);
  return ch;
}

