bool ok(Point p3){
  if(s.size()<=1)return true;
  Point p1=*(s.rbegin()+1);
  Point p2=*s.rbegin();
  return !Vector(p1,p2).clockwise(Vector(p2,p3));
}

void consider(Point p){
  while(!ok(p))s.pop_back();
  s.push_back(p);
}

void convex_hull() {
  sort(v.begin(),v.end(),sortpoint);
  for(int i=0;i<v.size();++i)consider(v[i]);
  for(int i=v.size()-2;i>=0;--i)consider(v[i]);
  s.pop_back();
}

