void msort(int s, int e){
    if(s >= e) return;
    int m = s + (e - s) /2;
    msort(s, m);
    msort(m + 1 , e);
    int i = s, j = m + 1, k = s;
    while (i <= m || j <= e){
        if (j > e || (i <= m && P[i] < P[j]))
            T[k++] = P[i++];
        else
            T[k++] = P[j++];
    }
    for(i = s; i <= e; i++) P[i] = T[i];
}
