const Polygon Polygon::convex_hull() const {
  std::vector<Point> point(vertex());
  std::vector<Point> result;
  std::sort(std::begin(point), std::end(point));
  point.insert(std::end(point), point.rbegin() + 1, point.rend());
  for(const auto& p: point) {
    while(result.size() >= 2 && ccw(result[result.size() - 2], result.back(), p) == CLOCKWISE) result.pop_back();
    result.push_back(p);
  }
  Polygon convex_hull;
  result.pop_back();
  for(const auto& p: result) convex_hull.add(p);
  return convex_hull;
}
