float cal_angle(float dx, float dy)
{
	float angle;
	float dis = sqrt(dx * dx + dy * dy);
	angle = acos(dx / dis);
	return angle;
}

float cal_dis(float dx, float dy)
{
	return sqrt(dx * dx + dy * dy);
}

bool on_left(int x1, int y1, int x2, int y2)
{
	if ((x1 * y2 - y1 * x2) >= 0)
	{
		return true;
	}
	else
		return false;
}

bool operator < (const vec& a, const vec& b)
{
	if ((a.dx * b.dy - a.dy * b.dx) > 0)  //a is under b
		return false;
	if ((a.dx * b.dy - a.dy * b.dx) < 0) // a is upon b
		return true;
	if ((a.dx * b.dy - a.dy * b.dx) == 0)
	{
		if (a.dx == b.dx && a.dx == 0)
		{
			return a.dy < b.dy;
		}
		else
			return a.dx > b.dx;
	}

}


