using namespace std;

class Point {
public:
    int x, y;
    Point(int a, int b) { 
        x = a;
        y = b; 
    }
    bool operator <(const Point &p) const {
        return y < p.y || (y == p.y && x < p.x);
    }
};

vector<Point> convex_hull(vector<Point>& P, int n)
{
    int k = 1;
    vector<Point> H;
    H.push_back(P[0]);
    H.push_back(P[1]);
    for (int i = 0; i < n - 2; i++) {
        while (k >= 1 && (H[k].x - H[k - 1].x) * (P[i + 2].y - H[k - 1].y) - (H[k].y - H[k - 1].y) * (P[i + 2].x - H[k - 1].x) < 0) {
            H.pop_back();
            k--;
        }
        H.push_back(P[i + 2]);
        k++;
    }
    H.push_back(P[n - 2]);
    for (int i = n; i > 2; i--) {
        while ((H[k + 1].x - H[k].x) * (P[i - 3].y - H[k].y) - (H[k + 1].y - H[k].y) * (P[i - 3].x - H[k].x) < 0) {
            H.pop_back();
            k--;
        }
        H.push_back(P[i - 3]);
        k++;
    }
    H.pop_back();
    return H;
}

int main() {
    int n;
    cin >> n;
    vector<Point> P;
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        Point point(a, b);
        P.push_back(point);
        int j = i + 1;
        while (j >= 2 && point < P[j - 2]) {
            P[j - 1] = P[j - 2];
            j--;
        }
        P[j - 1] = point;
    }
    vector<Point> H;
    H = convex_hull(P, n);
    cout << H.size() << endl;
    for (int i = 0; i < H.size(); i++) {
        cout << H[i].x << " " <<  H[i].y << endl;
    }
    return 0;
}

