    if (left < right){


        int nMiddleIndex = partition(points, left, right);

        if (nMiddleIndex < left || nMiddleIndex > right){return;}
            quick_sort_part ( points, left, nMiddleIndex );
            quick_sort_part ( points, nMiddleIndex+1 , right);


