    return fabs(x - p.x) < EPS && fabs(y - p.y) < EPS;
  }

  friend ostream& operator << (ostream &os, Point &p) {
    return os << "Point(" << p.x << ", " << p.y << ")";
  }
};

double cross (Point p1, Point p2) {
  return p1.x * p2.y - p1.y * p2.x;
}

class Segment {
public:
  Point p1, p2;
  Segment(Point p1, Point p2): p1(p1), p2(p2) {}
};

bool cw(Segment s, Point p2) {
  if (cross(s.p2 - s.p1, p2 - s.p1) < EPS) return true;
  return false;
}

vector<Point> PS;
vector<Point> U; // upper part
vector<Point> L; // lower part

void andrew() {
  sort(PS.begin(), PS.end());

  for (int i = 0; i < 2; i++) {
    U.push_back(PS[i]);
    L.push_back(PS[PS.size()-i-1]);
  }

  for (int i = 2; i < PS.size(); i++) {
    for (int n = U.size(); n >= 2; n--) {
      if (cw(Segment(U[n-2], U[n-1]), PS[i])) break;
      else U.pop_back();
    }
    U.push_back(PS[i]);
  }

  for (int i = PS.size() - 3; i >= 0; i--) {
    for (int n = L.size(); n >= 2 ; n--) {
      if (cw(Segment(L[n-2], L[n-1]), PS[i])) break;
      else L.pop_back();
    }
    L.push_back(PS[i]);
  }

  reverse(L.begin(), L.end());
  for (int i = U.size() - 2; i >= 1; i--) L.push_back(U[i]);
}

