}
int Vec::dot(const Vec &other) const {
	return x() * other.x() + y() * other.y();
}
int Vec::cross(const Vec &other) const {
	return x() * other.y() - y() * other.x();
}
void sort(std::vector<Point> &vec, const int &left, const int &right) {
	if (left < right) {
		Point pivot = vec.at(left + (right - left) / 2);
		int l = left, r = right;
		while (l <= r) {
			while (pivot > vec.at(l)) { ++l; }
			while (pivot < vec.at(r)) { --r; }
			if (l <= r) {
				auto temp{ vec.at(l) };
				vec.at(l) = vec.at(r); vec.at(r) = temp;
				++l; --r;
			}
		}
		sort(vec, left, r); sort(vec, l, right);
	}
}
auto prev(std::list<Point>::iterator i) {
	return --i;
}
std::list<Point> func(const std::vector<Point> &vector, const std::function<bool(const Vec&, const Vec&)> &lambda) {
	std::list<Point> stack;
	stack.push_back(vector.at(0)); stack.push_back(vector.at(0));
	for (auto p : vector) {
		auto e = stack.end();
		--e;
		while (!(lambda(Vec(p, *e), Vec(*e, *prev(e))))) {
			--e;
			stack.pop_back();
		}
		stack.push_back(p);
	}
	stack.pop_front(); stack.pop_front();
	return stack;
}
int main() {
	int n;
	std::cin >> n;
	std::vector<Point> vector;
	for (auto i = 0; i < n; ++i) {
		int x, y;
		std::cin >> x >> y;
		vector.push_back(Point(x, y));
	}
	sort(vector, 0, vector.size() - 1);
	auto list1 = func(vector, [](const Vec &a, const Vec &b)->bool {return (a.cross(b) <= 0); });
	auto list2 = func(vector, [](const Vec &a, const Vec &b)->bool {return (a.cross(b) >= 0); });
	list1.pop_back(); list2.pop_front();
	std::printf("%d\n", list1.size() + list2.size());
	for (auto p1 = list1.begin(); p1 != list1.end();++p1) {
		p1->show();
	}
	for (auto p2 = list2.end(); p2 != list2.begin();) {
		(--p2)->show();
	}

	return 0;
}

