int ccw(Point a, Point b, Point c){
    b -= a; c -= a;
    if(cross(b, c) > eps) return  1;
    if(cross(b, c) < -eps)return -1;
    if(dot(b, c) < 0)     return  2;
    if(norm(b) < norm(c)) return  2;
    return 0;
}

typedef vector<Point> Polygon;

Polygon convexhull(Polygon g){
    if((int)g.size() < 3)return g;
    Polygon res(g.size() << 1);
    auto comp = [](const Point& a, const Point& b){
        return make_pair(real(a), imag(a)) < make_pair(real(b), imag(b));
    };
    sort(g.begin(), g.end(), comp);
    int k = 0;
    for(int i=0; i<(int)g.size(); res[k++]=g[i++]){
        while(2 <= k && ccw(res[k-2], res[k-1], g[i]) <= 0)k--;
    }
    for(int i=(int)g.size()-2, t=k+1; i>=0; res[k++]=g[i--]){
        while(t <= k && ccw(res[k-2], res[k-1], g[i]) <= 0)k--;
    }
    res.resize(k - 1);
    return res;
}

