	int n = ps.size();
	sort(ps.begin(),ps.end());

	int k = 0;
	vector<Point> convex(n*2);

	rep(i, n) {
		while (k > 1 && cross((convex[k-1] - convex[k-2]), (ps[i] - convex[k-1])) <= 0 ) {
			k--;
		}
		convex[ k++ ] = ps[i];
