namespace Sort{

  template<class T, class D>
  void dfs(D &A, int l, int r){
    if(l + 1 == r) return;
    int m = (l + r) / 2;
    dfs<T>(A, l, m);
    dfs<T>(A, m, r);

    int idx = 0;
    int i = l;
    int j = m;
    T *tmp = new T[r - l];

    while(i < m || j < r){
      if(i >= m) tmp[idx] = A[j++];
      else if(j >= r) tmp[idx] = A[i++];
      else if(A[i] < A[j]) tmp[idx] = A[i++];
      else tmp[idx] = A[j++];
      idx++;
    }
    for(int i=0;i<r-l;i++) A[l + i] = tmp[i];
    delete[] tmp;
  }

  template<class T, class D>
  void sort(D &A, int n){
    dfs<T>(A, 0, n);
  };

}

template <typename T, typename D>
class Pair{
public:
  T first;
  D second;
  Pair(){first = second = 0;}
  Pair(const T first, const D second):first(first), second(second){}

  bool operator < (const Pair t)const{
    return first != t.first? (first < t.first):(second < t.second);
  }
  bool operator > (const Pair t)const{
    return first != t.first? (first > t.first):(second > t.second);
  }
};



