template<class T>
class Complex{
  T a, b;
public:
  Complex(){}
  Complex(T a,T b):a(a), b(b){}

  T real(){return a;}
  T imag(){return b;}
  T real(Complex t){return t.real();}
  T imag(Complex t){return t.imag();}

  Complex operator + (Complex t){return Complex(a + t.real(), b + t.imag());}
  Complex operator - (Complex t){return Complex(a - t.real(), b - t.imag());}
  Complex operator * (Complex t){return Complex(a * t.real() - b * t.imag(), a * t.imag() + b * t.real());}
  Complex operator * (double k){return Complex(k * a, k * b);};
  Complex& operator += (Complex t){return *this = *this + t;}
  Complex& operator -= (Complex t){return *this = *this - t;}
  Complex& operator *= (Complex t){return *this = *this * t;}
  Complex& operator *= (double k){return *this = *this * k;}
  bool operator == (T t)const{return a == t.real() && b == t.imag();}
  bool operator != (T t)const{return a != t.real() || b != t.imag();}
  bool operator < (const Complex t){
    return fabs(real()-real(t)) < EPS ? imag() < imag(t) : real() < real(t);
  }

  double norm(){return (a * a + b * b);}
  double abs(){return sqrt(norm());}
  Complex conj(){return Complex(a, -b);}
};


template <class T> T real(Complex<T> a){return a.real();}
template <class T> T imag(Complex<T> a){return a.imag();}
template <class T> T norm(Complex<T> a){return a.norm();}
template <class T> Complex<T> conj(Complex<T> a){return Complex<T>(a.real(), -a.imag());}


typedef Complex<double> P; //Point
typedef Pair<P,P> L; //Line, Segment

double dot(P a, P b){ return real(conj(a)*b); }
double cross(P a, P b){ return imag(conj(a)*b); }
int ccw(P a, P b, P c){
  b -= a;
  c -= a;
  if(cross(b,c) > EPS) return 1;   // ベクトル(b-a)の左側にベクトル(c-a)が存在する。
  if(cross(b,c) < -EPS) return -1; // ベクトル(b-a)の右側にベクトル(c-a)が存在する。
  if(dot(b,c) < -EPS) return 2;
  if(norm(b) < norm(c)) return -2;
  return 0;
}

vector<P> convex_hull(vector<P> G) {
  int n = G.size();
  Sort::sort<P>(G, n);
  vector<P> res;

  auto erase = [&](int i) {
    if(res.size() < 2) return 0;
    P av = res[res.size()-2];
    P bv = res[res.size()-1];
    P cv = G[i];
    if(ccw(av, bv, cv) == -1) {res.pop_back(); return 1;}
    return 0;
  };

  for(int i=0;i<n;i++){
    while(erase(i));
    res.push_back(G[i]);
  }

  for(int i=n-2;i>=0;i--){
    while(erase(i));
    res.push_back(G[i]);
  }
  res.pop_back();
  return res;
}

signed main(){

  int n;
  std::cin>>n;
  vector<P> G(n);
  for(int i=0;i<n;i++){
    int x, y;
    std::cin>>x>>y;
    G[i] = P(x, y);
  }

  auto ans = convex_hull(G);
  std::cout <<ans.size()<<std::endl;

  int idx = 0;
  for(int i=0;i<ans.size();i++){
    auto a = ans[idx], b = ans[i];
    if(a.imag() != b.imag() && a.imag() > b.imag()) idx = i;
    if(a.imag() == b.imag() && a.real() > b.real()) idx = i;
  }

  int m = ans.size();
  for(int i=0;i<ans.size();i++)
    std::cout<<ans[(idx + i)%m].real() <<" "<<ans[(idx + i)%m].imag()<<std::endl;


  return 0;
}

