  int n; cin >> n;

  for (int i = 0; i < n; i++) {
    int x, y; cin >> x >> y;
    S.push_back(Point(x, y));
  }

  andrew();

  cout << L.size() << endl;
  for (vector<Point>::iterator it = L.begin(); it != L.end(); it++)
    cout << (*it).x << ' ' << (*it).y << endl;
}

