void convex_hull(point_t* points, size_t npoints, point_ptr_t** out_hull, size_t* out_hullsize)
{
    point_ptr_t* hull;
    int i, t;
    int k = 0;

    hull = *out_hull;

/* right hull */
    for (i = 0; i < npoints; ++i) {
        while (k >= 2 && ccw(hull[k-2], hull[k-1], &points[i]) < 0) --k;
        hull[k++] = &points[i];
    }

/* left hull */
    for (i = npoints - 2, t = k + 1; i >= 0; --i) {
        while (k >= t && ccw(hull[k-2], hull[k-1], &points[i]) < 0) --k;
        hull[k++] = &points[i];
    }

    *out_hull = hull;
    *out_hullsize = k - 1;

}

