struct Point { long double px, py; }; struct Polygon { vector<Point>p; };
Point Minus(Point a, Point b) { Point G; G.px = a.px - b.px; G.py = a.py - b.py; return G; }
long double dot(const Point& a, const Point& b) { return a.px * b.px + a.py * b.py; }
long double crs(const Point& a, const Point& b) { return a.px * b.py - a.py * b.px; }
bool operator<(const Point& a, const Point& b) { return a.px < b.px; }
long double norm(Point a) { return a.px*a.px + a.py*a.py; }
int ccw(Point p0, Point p1, Point p2) {
	Point a = Minus(p1, p0), b = Minus(p2, p0);
	if (crs(a, b) > 1e-10) return 1;
	if (crs(a, b) < -1e-10) return -1;
	if (dot(a, b) < -1e-10) return 2;
	if (norm(a) < norm(b)) return -2;
	return 0;
}
vector<Point> solve(Polygon X) {
	vector<Point>P = X.p, u, l;
	int M = P.size();
	if (M < 3) { return P; }
	sort(P.begin(), P.end());
	l.push_back(P[0]); l.push_back(P[1]);
	u.push_back(P[P.size() - 2]); u.push_back(P[P.size() - 1]);
	for (int i = 2; i < P.size(); i++) {
		for (int j = u.size(); j >= 2; j--) {
			if (ccw(u[j - 2], u[j - 1], P[i]) == CLOCKWISE) { break; }
			u.pop_back();
		}
		u.push_back(P[i]);
	}
	for (int i = P.size() - 3; i >= 0; i--) {
		for (int j = l.size(); j >= 2; j--) {
			if (ccw(l[j - 2], l[j - 1], P[i]) == CLOCKWISE) { break; }
			u.pop_back();
		}
		l.push_back(P[i]);
	}
	reverse(l.begin(), l.end());
	for (int i = u.size() - 2; i >= 1; i--) { l.push_back(u[i]); }
	return l;
}
