bool isConvex(Polygon s) {
  int n = s.size();
  int a;
  for (int i = 0; i < n; i++) {
    a = ccw(s[i], s[(i+1)%n], s[(i+2)%n]);
    if (abs(a) == 1) break;
  }
  for (int i = 0; i < n; i++) {
    int b = ccw(s[i], s[(i+1)%n], s[(i+2)%n]);
    if (a*b < 0 && abs(b) == 1) {
      return false;
    }
  }
  return true;
}

// ????§???¢g??¨????????¢??????2:?????´???1:?????????0:?????´???????????§?????????????????????
int contains(Polygon g, Point p) {
  int n = g.size();
  bool x = false;
  for (int i = 0; i < n; i++) {
    Point a = g[i]-p, b = g[(i+1)%n]-p;
    if (abs(cross(a, b)) < EPS && dot(a, b) < EPS) return 1;
    if (a.y > b.y) swap(a, b);
    if (a.y < EPS && EPS < b.y && cross(a, b) > EPS) x = !x;
  }
  return (x ? 2 : 0);
}

