namespace Polys{
    typedef vector<P> Poly,ConvexPoly;

    //O(n logn)
    ConvexPoly convex_hull(Poly ps) {
        int n = ps.size(), k = 0;
        sort(ALL(ps));
        Poly ch(2*n);
        REP(i,n){ // lower-hull
            while (k > 1 && cross(ch[k-1]-ch[k-2],ps[i]-ch[k-1]) < 0) --k;
            ch[k++]=ps[i];
        }
        for(int i=n-2,t=k;i>=0;i--){// upper-hull
            while (k > t && cross(ch[k-1]-ch[k-2],ps[i]-ch[k-1]) < 0) --k;
            ch[k++]=ps[i];
        }
        ch.resize(k-1);
        return ch;
    }
    void ccw_sort(ConvexPoly &ps){
        sort(ALL(ps));
        sort(ps.begin()+1,ps.end(),[&ps](const P& l,const P& r) -> bool{
            int cr=cross(l-ps[0],r-ps[0]);
            if(cr!=0)return cr;
            return abs(l-ps[0])<abs(r-ps[0]);
        });
        P prev=ps[0];
        int l=1,r=2;
        for(int i=1;i+1<ps.size();i++){
            if(cross(ps[i]-ps[0],ps[i+1]-ps[0])==0)r=i+1;
            else{
                sort(ps.begin()+l,ps.begin()+r,[&prev](const P& l,const P& r) -> bool{
                    return abs(l-prev)<abs(r-prev);
                });
                prev=ps[i];l=i;r=i+1;
            }
        }
    }
}
