{
	int N; cin>>N;
	vector<P> ps;
	rep(i, N) {
		P p; cin>>p.X>>p.Y;
		ps.push_back(p);
	}

	G g = convex_hull(ps);
	cout << g.size() << endl;
	rep(i, g.size()) {
		cout << g[i].X << " " << g[i].Y << endl;
	}
}

