bool bCrossProduct (std::pair<int,int > &point, std::vector<std::pair<int,int> >& StackPoints,int i){


    double dValueCrossPro;

        dValueCrossPro = 
            (StackPoints[i].first - StackPoints[i-1].first) 
                * (point.second - StackPoints[i].second)
            -(StackPoints[i].second - StackPoints[i-1].second) 
                * (point.first - StackPoints[i].first) ;
        return dValueCrossPro >= 0;

}

