bool isParallel(Line a, Line b) {
	return isParallel(a.p2 - a.p1, b.p2 - b.p1);
}
bool IntersectSS(Point a1, Point a2, Point b1, Point b2) {
	return ccw(a1, a2, b1) * ccw(a1, a2, b2) <= 0 && ccw(b1, b2, a1) * ccw(b1, b2, a2) <= 0;
}
bool IntersectSS(Segment a, Segment b) {
	return IntersectSS(a.p1, a.p2, b.p1, b.p2);
}
Point getCrossPointSS(Segment a, Segment b) {
	Vector Base = b.p2 - b.p1;
	db S1 = fabs(Base ^ (a.p1 - b.p1));
	db S2 = fabs(Base ^ (a.p2 - b.p1));
	return a.p1 + (a.p2 - a.p1) * (S1 / (S1 + S2));
}
Point getCrossPointLL(Line a, Line b) {
	db S1 = (b.p2 - b.p1) ^ (a.p2 - a.p1);
	db S2 = (b.p2 - b.p1) ^ (b.p2 - a.p1);
	if(dcmp(S1) == 0 && dcmp(S2) == 0) return a.p1;
	return a.p1 + (a.p2 - a.p1) * (S2 / S1); 
}
db disLP(Line a, Point p) {
	return fabs(((a.p2 - a.p1) ^ (p - a.p1)) / dis(a.p1, a.p2));
}
db disSP(Segment a, Point p) {
	if(dcmp((a.p2 - a.p1) * (p - a.p1)) == -1) return dis(a.p1, p);
	if(dcmp((a.p1 - a.p2) * (p - a.p2)) == -1) return dis(a.p2, p);
	return disLP(a, p);
}
db disSS(Segment a, Segment b) {
	if(IntersectSS(a, b)) return 0.0;
	return min({disSP(b, a.p1), disSP(b, a.p2), disSP(a, b.p1), disSP(a, b.p2)});
}
db Area(Polygon p) {
	db S = p.back() ^ p[0];
	rop(i, 0, (int) p.size() - 1) S += p[i] ^ p[i + 1];
	return fabs(S) / 2;
}
bool isConvex(Polygon p) {
	int n = p.size();
	rop(i, 0, n) if(ccw(p[(i + n - 1) % n], p[i], p[(i + 1) % n]) == CCW_CLOCKWISE) return 0;
	return 1;
}
int Contain(Polygon g, Point p) {
	int n = g.size();
	int cnt = 0;
	rop(i, 0, n) {
		Point a = g[i] - p, b = g[(i + 1) % n] - p;
		if(ccw(a, b, Point(0, 0)) == CCW_ON_SEGMENT) return 1;
		if(dcmp(a.y - b.y) == 0) continue;
		if(dcmp(a.y) == 0 && dcmp(a.x) >= 0) { 
			if(dcmp(b.y) == -1) ++ cnt;
			continue;
		}
		if(dcmp(b.y) == 0 && dcmp(b.x) >= 0) {
			if(dcmp(a.y) == -1) ++ cnt;
			continue;
		}
		if(a.y > b.y) swap(a, b);
		if(dcmp(a.y) <= 0 && dcmp(b.y) >= 0 && dcmp(a ^ b) == 1) ++ cnt;
	}
	return (cnt & 1) ? 2 : 0;
	// 2 : IN
	// 1 : ON
	// 0 : OUT
}
Polygon ConvexHull(Polygon p) {
	int n = p.size();
	Polygon g(n * 2);
	sort(p.begin(), p.end(), cmp_y);
	int c = 0;
	rop(i, 0, n) {
		while(c > 1 && dcmp((g[c - 1] - g[c - 2]) ^ (p[i] - g[c - 2])) < 0) -- c;
		g[c ++] = p[i];
