	per(i, n - 2, 0) {
		while(c > k && dcmp((g[c - 1] - g[c - 2]) ^ (p[i] - g[c - 1])) < 0) -- c;
		g[c ++] = p[i];
	}
	g.resize(c - 1);
	return g;
}


