int orientation(pii p , pii q, pii r)
{
    int val = (q.Y - p.Y) * (r.X - q.X) -
              (q.X - p.X) * (r.Y - q.Y);

    if (val == 0) return 0;
    return (val > 0)? 1: 2;
}

