struct polygon{
    int n;
    vector<Point> p;
    // Line l[maxp];
    void input(int _n){
        n = _n;
        Point tt;
        for(int i = 0;i < n;++i ){
            tt.input();
            p.push_back(tt);
        }
    }
    struct cmp{    //排序规则：
        Point p;
        cmp(const Point &p0){
            p = p0;
        }
        bool operator ()(const Point &aa,const Point &bb){
            Point a = aa,b = bb;
            int d = sgn((a-p)^(b-p));
            if(d == 0){
                return sgn(a.distance(p)-b.distance(p))<0;
            }
            return d>0;
        }
    };
    void norm(){
        Point mi = p[0];
        for(int i = 1;i < n;++i ){
            mi = min(mi,p[i]);
        }
        sort(p.begin(),p.end(),cmp(mi));
    }
    // 安德鲁算法
     void getconvex(polygon &convex){
        sort(p.begin(),p.end());
        convex.n = n;
        for(int i = 0;i < min(n,2);++i ){
            convex.p.push_back(p[i]);
        }
        if(convex.n == 2&&(convex.p[0] == convex.p[1])){
            convex.n--;   //特判
        }
        if(n<=2){
            return;
        }
        for(int i = 2;i < n;++i ){
            while(convex.p.size()>1 && sgn((convex.p[convex.p.size()-1]-p[i])^(convex.p[convex.p.size()-2]-p[i]))<0){
                convex.p.pop_back();
            }
            convex.p.push_back(p[i]);
        }
        int temp = convex.p.size()-1;
        convex.p.push_back(p[n-2]);
        for(int i = n-3;i >= 0;i--){
            while(convex.p.size()-1 != temp && sgn((convex.p[convex.p.size()-1]-p[i])^(convex.p[convex.p.size()-2]-p[i]))<0){
                convex.p.pop_back();
            }
            convex.p.push_back(p[i]);
        }
        convex.n = convex.p.size();
        if(convex.n == 2 && (convex.p[0] == convex.p[1])){
            convex.n--;
        }
       reverse(convex.p.begin(),convex.p.end());
       convex.p.pop_back();
    }
};

