struct vec2d {
	int x, y;
	vec2d() {}
	vec2d(int x, int y) :x(x), y(y) {}
	double norm()const {
		return hypot(x, y);
	}
	vec2d operator+(const vec2d&v)const {
		return vec2d(x + v.x, y + v.y);
	}
	vec2d operator-(const vec2d&v)const {
		return vec2d(x - v.x, y - v.y);
	}
	bool operator==(const vec2d&v)const {
		return x == v.x && y == v.y;
	}
	bool operator!=(const vec2d&v)const {
		return !operator==(v);
	}
	static double cos_arg(const vec2d&v0, const vec2d&v1) {
		return (v0.x * v1.x + v0.y * v1.y) / v0.norm() / v1.norm();
	}
	static double cross_product(const vec2d&v0, const vec2d&v1) {
		return v0.x * v1.y - v0.y * v1.x;
	}
};
vector<vec2d>get_convex_hull(vector<vec2d>input) {
	sort(ALL(input), [](vec2d v0, vec2d v1) {return v0.y < v1.y || (v0.y == v1.y) && v0.x < v1.x; });
	vector<vec2d>output;
	output.push_back(input[0]);
	output.push_back(input[1]);
	for (int i = 2; i < input.size(); ++i) {
		output.push_back(input[i]);
		while (output.end() - 2 != output.begin() && vec2d::cross_product(*(output.end() - 3) - *(output.end() - 2), *(output.end() - 1) - *(output.end() - 2)) > 0) {
			output.erase(output.end() - 2);
		}
	}
	output.push_back(input[input.size() - 2]);
	for (int i = input.size() - 3; i >= 0; --i) {
		output.push_back(input[i]);
		while (output.end() - 2 != output.begin() && vec2d::cross_product(*(output.end() - 3) - *(output.end() - 2), *(output.end() - 1) - *(output.end() - 2)) > 0) {
			output.erase(output.end() - 2);
		}
	}
	output.pop_back();
	return output;
}
signed main() {
