	REP(i, n) {
		int x = in(), y = in();
		point[i] = (vec2d(x, y));
	}
	vector<vec2d>res = get_convex_hull(point);
	cout << res.size() << endl;
	REPC(i, res) {
		cout << i.x << ' ' << i.y << endl;
	}
}

