	vector<complex<T>> r;
	for (int i = 0, n = ps.size(); i < n; i++) {
		for (int rs = r.size(); 2 <= rs && det(r[rs - 1] - r[rs - 2], ps[i] - r[rs - 1]) < 0; r.pop_back(), rs--);
		r.emplace_back(ps[i]);
	}
	for (int i = int(ps.size()) - 2, j = r.size(); 0 <= i; i--) {
		for (int rs = r.size(); j + 2 <= rs && det(r[rs - 1] - r[rs - 2], ps[i] - r[rs - 1]) < 0; r.pop_back(), rs--);
		r.emplace_back(ps[i]);
	}
	r.pop_back();
	return r;
}

