typedef Point P;
vector<P> convex_hull(P *ps,int n)
{
    auto cmp_x=[](P p1,P p2){
        if(p1.y!=p2.y)  return p1.y<p2.y;
        return p1.x<p2.x;
//        return p1.y<p2.y;
    };
    sort(ps,ps+n,cmp_x);
    int k=0;
    vector<P> qs(n*2);
    //构造凸包的下侧
    for(int i=0;i<n;++i)
    {
        while(k>1 && (qs[k-1] - qs[k-2]).det(ps[i]-qs[k-2]) < 0) k--;
        qs[k++]=ps[i];
    }
    //构造凸包的上侧
    for(int i=n-2,t=k;i>=0;--i)
    {
        while(k > t && (qs[k-1] - qs[k-2]).det(ps[i] - qs[k-2]) < 0) k--;
        qs[k++]=ps[i];
    }
    qs.resize(k-1);
    return qs;
}
