template <typename T>
int orientation(Point<T> a, Point<T> b, Point<T> c){
  T ba_x = b.x - a.x;
  T ba_y = b.y - a.y;
  T ca_x = c.x - a.x;
  T ca_y = c.y - a.y;
  double o = ba_x * ca_y - ba_y * ca_x;
  if(abs(o) < EPS) return ON_SEGMENT;
  return o > 0 ? CCW : CW;
}

