template<typename T>
class Stack {
  private:
    Vector<T> A;
  public:
    Stack(){}
    void push(T v){
      A.push_back(v);
    }
    unsigned int size(){
      return A.size();
    }
    T top(){
      return A[A.size()-1];
    }
    T pop(){
      T res = top();
      A.pop_back();
      return res;
    }
    T &operator[](const unsigned int idx)const{
      return A[idx];
    }
};

template <typename T>
class Heap {
  public:
  Vector<T> A;

  public:
  Heap(){
    A = Vector<T>(1);
  }

  void push(T v){
    unsigned int idx = A.size();
    A.push_back(v);

    while(1){
      if(idx == 1) break;
      unsigned int  par = idx / 2;
      if(A[par] < A[idx]) break;
      swap(A[idx], A[par]);
      idx = par;
    }
  };

  T top(){
    assert(A.size() > 1);
    return A[1];
  }
  T pop(){
    assert(A.size() > 1);
    T res = top();
    remove();
    return res;
  }
  bool empty(){
    return A.size() <= 1;
  }
  void remove(){
    T v = A[A.size() - 1];
    unsigned int idx = 1;
    A.pop_back();
    A[idx] = v;
    while(1){
      unsigned int  least = idx;
      unsigned int l = 2*idx, r = 2*idx+1;
      // if(l < A.size() && A[l] <= A[least]){
      if(l < A.size() && !(A[least] < A[l])){
        least = l;
      }
      // if(r < A.size() && A[r] <= A[least]){
      if(r < A.size() && !(A[least] < A[r])){
        least = r;
      }

      if(least == idx) break;
      swap(A[idx], A[least]);
      idx = least;
    }
  }
#ifdef EBUG
  void print(){
    for(int i = 1; i < A.size(); i++){cout << A[i] << " ";}
    cout << endl;
  }
#endif
};



