template <typename T>
class ArgAndDistAndPoint {
  public:
    double arg;
    double dist;
    Point<T> pts;
    ArgAndDistAndPoint(){}
    ArgAndDistAndPoint(double arg, double dist, Point<T> pts): arg(arg), dist(dist), pts(pts){}
    ArgAndDistAndPoint(const ArgAndDistAndPoint& other): arg(other.arg), dist(other.dist), pts(other.pts){ }

    // bool operator<=(const ArgAndDistAndPoint& other)const{
    //   if(eq(arg, other.arg)){
    //     return dist - other.dist <= EPS;
    //   }
    //   return arg - other.arg <= EPS;
    // }
    bool operator<(const ArgAndDistAndPoint& other)const{
      if(eq(arg, other.arg)){
        return dist < other.dist;
      }else{
        return arg < other.arg;
      }
    }
    ArgAndDistAndPoint &operator=(const ArgAndDistAndPoint& other){
      if(this != &other){
        arg = other.arg;
        dist = other.dist;
        pts = other.pts;
      }
      return *this;
    }
};

Vector<Point<int>> arg_sort(const Vector<Point<int>> &pts){
  Vector<ArgAndDistAndPoint<int>> ap;
  for(int i = 1; i < (int)pts.size(); i++){
    int dy = pts[i].y - pts[0].y;
    int dx = pts[i].x - pts[0].x;
    double arg = atan2(dy, dx);
    double dist = sqrt(dx*dx + dy*dy);
    Point<int> p = pts[i];
