    }
//    printf("%d\n",ccw(g[4],g[0],g[1]));
    Polygon ans=andrewscanf(g);
    printf("%d\n",ans.size());
    int num=0,len=ans.size();
    while(1){
        if(ans[num%len].y<=ans[(num+1)%len].y){
            for(int i=num%len;i<len;i++){
                printf("%.0f %.0f\n",ans[i].x,ans[i].y);
            }
            for(int i=0;i<num%len;i++){
                printf("%.0f %.0f\n",ans[i].x,ans[i].y);
            }
            break;
        }
        num++;
    }
    return 0;
}

