struct Point {
    int x;
    int y;
};

template <class P>
vector<P> convex_hull(vector<P> points) {
    int N = points.size();
    assert(N >= 2);
    sort(begin(points), end(points), [](const P& l, const P& r) { return (l.y == r.y) ? (l.x < r.x) : (l.y < r.y); });
    stack<P> left, right;

    auto tmp = [&](bool construct_left) {
        auto& out = (construct_left ? left : right);
        stack<pair<int, int>> arg;

        out.push(points[0]);
        out.push(points[1]);
        arg.push({points[1].x - points[0].x, points[1].y - points[0].y});
        for (int i = 2; i < N; i++) {
            int dx, dy;
            while (1) {
                P last = out.top();
                dx = points[i].x - last.x, dy = points[i].y - last.y;
                if (arg.empty()) break;
                int numer = arg.top().first, denom = arg.top().second;
                if (construct_left && dx * denom < dy * numer) {
                    arg.pop(); out.pop();
                } else if (!construct_left && dx * denom > dy * numer) {
                    arg.pop(); out.pop();
                } else {
                    break;
                }
            }
            arg.push({dx, dy});
            out.push(points[i]);
        }
    };
    tmp(false);
    tmp(true);

    vector<P> ret;
    ret.reserve(left.size() + right.size());
    while (!right.empty()) {
        auto& p = right.top(); right.pop();
        ret.push_back(p);
    }
    reverse(begin(ret), end(ret));
    left.pop();
    while (left.size() > 1) {
        auto& p = left.top(); left.pop();
        ret.push_back(p);
    }
    return ret;
}

