short int side(int s, int m, int e){
	if (overline(s, m, e)) return 0;

	// cerr << "params:\nxs " << radian[s].xx << " ys " << radian[s].yy << "\nxm "<< radian[m].xx << " ym "<< radian[m].yy << "\nxe " << radian[e].xx << " ye " << radian[e].yy << endl;
	//Data Set Over Radian // R:1 // O:0 // L : -1
	if (radian[s].xx == radian[e].xx){
		if (radian[s].yy < radian[e].yy) {
			if (radian[s].xx < radian[m].xx) return 1;
			else return -1;
		} else {
			if (radian[s].xx < radian[m].xx) return -1;
			else return 1;
		}
	} // pi/2 Radian cut out!

	double th = atan2(radian[e].yy - radian[s].yy, radian[e].xx - radian[s].xx);
	double ml = (radian[e].yy - radian[s].yy) / (radian[e].xx - radian[s].xx);
	double c = radian[s].yy - (ml * radian[s].xx);

	// cerr << "th " << th << "->" << atan2(1,0) << " ml " << ml << " c " << c << endl;

	if (abs(th) < atan2(1,0) ) return (radian[m].yy > (ml * radian[m].xx) + c? -1:1);
	else return (radian[m].yy > (ml * radian[m].xx) + c? 1:-1);
}

