class Point{
public:
    int x, y;
    Point(int xx, int yy): x(xx), y(yy){}
};

int orientation(Point A, Point B, Point C){
    int o = (B.y-A.y)*(C.x-B.x)-(B.x-A.x)*(C.y-B.y);
    if(o == 0) return 0;
    if(o < 0) return -1;
    return 1;
}

int distSq(Point A, Point B){
    return (A.y-B.y)*(A.y-B.y)+(A.x-B.x)*(A.x-B.x);
}

bool compare(Point& O, Point& A, Point& B){
    int o = orientation(O, A, B);
    if(o == 0) return distSq(O, A) > distSq(O, B);
    return o < 0;
}

int partition(vector<Point>& points, const int& l, const int& r){
    int p =  l+rand()%(r-l);
    swap(points[r-1], points[p]);
    p = l;
    for(int i = l; i < r-1; i++){
        if(compare(points[0], points[i], points[r-1])){
            swap(points[i], points[p]);
            p++;
        }
    }
    swap(points[r-1], points[p]);
    return p;
}

void quickSort(vector<Point>& points, const int& l, const int& r){
    if(l >= r-1) return;
    int p = partition(points, l, r);
    quickSort(points, l, p);
    quickSort(points, p+1, r);
}

Point nextToTop(stack<Point>& S){
    Point t = S.top();
    S.pop();
    Point r = S.top();
    S.push(t);
    return r;
}

void convexHull(vector<Point>& points){
    int ymin = 0, m = points.size();
    for(int i = 1; i < m; i++){
        if(points[i].y < points[ymin].y) ymin = i;
        else if(points[i].y == points[ymin].y && points[i].x < points[ymin].x) ymin = i;
    }
    swap(points[0], points[ymin]);
    quickSort(points, 1, m);
    int offset = 2;
    while(orientation(points[0], points[1], points[offset]) == 0) offset++;
    stack<Point> S;
    S.push(points[0]);
    for(int i = offset-1; i >= 1; i--) S.push(points[i]);
    for(int i = offset; i < m; i++){
        while(orientation(nextToTop(S), S.top(), points[i]) > 0){
            S.pop();
        }
        S.push(points[i]);
    }
    stack<Point> ans;
    while(!S.empty()){
        ans.push(S.top());
        S.pop();
    }
    cout << ans.size() << endl;
    while(!ans.empty()){
        cout << ans.top().x << " " << ans.top().y << endl;
        ans.pop();
    }
}

