G convex_hull(G g){
    int n = g.size();
	assert(n >= 3);

	sort(ALL(g));
    G c(n*2);
	int k = 0;
	REP(i, n) {
        while(k>=2 && ccw(c[k-2], c[k-1], g[i]) == -1) k--;
        c[k++] = g[i];
    }
	int t = k + 1;
	for (int i = n - 2; i >= 0; --i) {
		while (k >= t && ccw(c[k - 2], c[k - 1], g[i]) == -1) k--;
		c[k++] = g[i];
	}
    c.resize(k-1);
    return c;
}

