struct Point{ int x, y; };

Point set_p(int a, int b)
{
    Point p;
    p.x = a; p.y = b;
    return p;
}

struct Vector{ int vx, vy; };

Vector set_v(const Point &p1, const Point &p2)
{
    Vector v;
    v.vx = p2.x - p1.x;
    v.vy = p2.y - p1.y;
    return v;
}

int cross(const Vector &v1, const Vector &v2)
{
    return (v1.vx * v2.vy) - (v1.vy * v2.vx);
}

bool outlow(const Point &p, const Point &q){
	if(p.y != q.y){ return p.y < q.y; }
	return p.x > q.x;
}

bool is_convex(const Point &P0, const Point &P1, const Point &P2)
{
	Vector V1 = set_v(P0, P1), V2 = set_v(P1, P2);
	if(cross(V1, V2) < 0) return false;
	return true;
}

int main()
{
    int i, n;
    int *X, *Y;
    scanf("%d", &n);
    assert(n >= 3);

    X = new int [n];
    Y = new int [n];
    for(i = 0; i < n; i++){
        scanf("%d %d", &X[i], &Y[i]);
    }
    Point *Plg;
    Plg = new Point [n];
    for(i = 0; i < n; i++){
        Plg[i] = set_p(X[i], Y[i]);
    }

    sort(Plg, Plg + n, outlow);

    int *cc;
    cc = new int [n + 1];
    cc[0] = 0; cc[1] = 1;
    int size = 2;

    for(i = 2; i < n; i++){
        while(size >= 2){
            assert(cc[size - 2] >= 0 && cc[size - 1] >= 0);
            if(is_convex(Plg[cc[size - 2]], Plg[cc[size - 1]], Plg[i])) break;
            size--;
        };
        cc[size] = i; size++;
    }

    cc[size] = n - 2; size++;

    for(i = n - 3; i >= 0; i--){
        while(size >= 2){
            assert(cc[size - 2] >= 0 && cc[size - 1] >= 0);
            if(is_convex(Plg[cc[size - 2]], Plg[cc[size - 1]], Plg[i])) break;
            size--;
        };
