    for (i = 0; i < n; i++) {
        Point point;
        scanf("%d %d",&point.x, &point.y);
        P[i] = point;
        int j = i + 1;
        while (j >= 2 && point < P[j - 2]) {
            P[j - 1] = P[j - 2];
            j--;
        }
        P[j - 1] = point;
    }
    convex_hull(P);
    return 0;
}

