ftype dot(point a, point b) {
	return (conj(a) * b).x();
}
ftype cross(point a, point b) {
	return (conj(a) * b).y();
}
bool lex(point a, point b) {
	return make_pair(a.y(), a.x()) < make_pair(b.y(), b.x());
}
bool ang(point a, point b) {
	if(eq(cross(a, b), 0.)) {
		return norm(a) < norm(b);
	} else {
		return cross(a, b) > 0;
	}
}

bool collin(point a, point b) {
	return eq(cross(a, b), 0.);
}

void polar_sort(vector<point> &r) {
	int n = r.size();
	sort(all(r), lex);
	sort(begin(r) + 1, end(r), [&](point a, point b) {
		return ang(a - r[0], b - r[0]);
	});
	int t = n - 1;
	while(t > 0 && collin(r.back() - r[0], r[t] - r[0])) {
		t--;
	}
	reverse(begin(r) + t + 1, end(r));
}

vector<point> convex_hull(vector<point> r) {
	int n = r.size();
	polar_sort(r);
	vector<point> st = {r[0]};
	for(int i = 1; i < n; i++) {
		while(st.size() >= 2 && cross(r[i] - st[st.size() - 1], r[i] - st[st.size() - 2]) > 0) {
			st.pop_back();
		}
		st.push_back(r[i]);
	}
	return st;
}

