#define db double
using namespace std;
const int N = 1e5 + 100;
const db eps = 1e-8;
const db inf = 1e20;
const db pi = acos (-1);
inline int sgn (db p) {
    if (fabs (p) < eps) return 0;
    if (p < 0) return -1;
    return 1;
}
struct point {
    db x, y;
    point () {}
    point (db _x, db _y) {x = _x, y = _y;}
    void input () {scanf ("%lf %lf", &x, &y);}
    bool operator == (point b) const {return sgn (x - b.x) == 0 && sgn (y - b.y) == 0;}
    bool operator < (point b) const {return y < b.y || (sgn (y - b.y) == 0 && x < b.x);}
    point operator - (const point &b) const {return point (x - b.x, y - b.y);}
    db operator * (const point &b) const {return x * b.x + y * b.y;}
    db operator ^ (const point &b) const {return x * b.y - y * b.x;}
    point operator + (const point &b) const {return point (x + b.x, y + b.y);}
    point operator * (const db &b) const {return point (x * b, y * b);}
    point operator / (const db &b) const {return point (x / b, y / b);}
    db distance (point p) {return hypot (x - p.x, y - p.y);}
    db len () {return hypot (x, y);}
    db len2 () {return x * x + y * y;}
    db cross (point a, point b) {return (a - *this) ^ (b - *this);}
    db dot (point a, point b) {return (a - *this) * (b - *this);}
    bool on_seg (point a, point b) {return sgn (cross (a, b)) == 0 && dot (a, b) <= 0;}///点是否在线段ab上
    point turn (db k) {return point (x * cos(k) - y * sin(k), x * sin(k) + y * cos(k));}
    point rotate(point p, db angle) {///绕着 p 点逆时针旋转 angle
        point v = (*this) - p;
        db c = cos(angle), s = sin(angle);
        return point(p.x + v.x*c - v.y*s, p.y + v.x*s + v.y*c);
    }
} p;
///两线段是否相交
bool seg (point a, point b, point c, point d) {
    if (a.on_seg (c, d) || b.on_seg (c, d) || c.on_seg (a, b) || d.on_seg (a, b)) return true;
    if (a.cross (b, d) * a.cross (b, c) < 0 && c.cross (d, b) * c.cross (d, a) < 0) return true;
    return false;
}
/// 点的投影是否在线段ab上
bool check (point p, point a, point b) {
    point x = b - a;
    db k = x.len ();
    db u = a.dot (p, b) / k;
    x = (x / k) * u + a;
    if (x.on_seg (a, b)) return true;
    return false;
}
struct polygon {
