using Point = complex<double>;
const double eps = 1e-6;
auto cross_product(Point p1, Point p2) {
    return p1.real() * p2.imag() - p2.real() * p1.imag();
}
vector<Point> GrahamScan(vector<Point> v, int contains = 0) {
    Point minPoint = *min_element(v.begin(), v.end(), [](Point p1, Point p2) {
        return abs(p1.imag() - p2.imag()) > eps ? p1.imag() < p2.imag() : p1.real() < p2.real();
    });
    sort(v.begin(), v.end(), [&minPoint](Point p1, Point p2) -> bool {
        auto res = cross_product(p1 - minPoint, p2 - minPoint);
        return abs(res) < eps ? abs(p1 - minPoint) < abs(p2 - minPoint) : res > 0;
    });
    {
        int p = static_cast<int>(v.size()) - 1;
        while (p > 0 && abs(cross_product(v[p] - minPoint, v[p - 1] - minPoint)) < eps) {
            p--;
        }
        reverse(v.begin() + p, v.end());
    }
    vector<Point> res;
    for (int p = 0; p < static_cast<int>(v.size());) {
        if (res.size() < 2) {
            res.push_back(v[p++]);
        } else {
            Point p1 = res[res.size() - 1] - res[res.size() - 2];
            Point p2 = v[p] - res[res.size() - 1];
            if (cross_product(p1, p2) < (1 - 2 * contains) * eps) {
                res.pop_back();
            } else {
                res.push_back(v[p++]);
            }
        }
    }
    return res;
}

