typedef complex <double> point;

namespace std {
  bool operator < (const point& a, const point& b){
    return fabs(real(a)-real(b)) < EPS ? imag(a) < imag(b) : real(a) < real(b); //x->y
  }
}
double dot(point a,point b){return a.x*b.x+a.y*b.y;}
double cross(point a,point b){return a.x*b.y-a.y*b.x;}

int ccw(point a,point b,point c){
  point d = b-a;
  point e = c-a;
  if(cross(d,e)>0) return 1;//"COUNTER_CLOCKWISE"
  if(cross(d,e)<0) return -1;//"CLOCKWISE"
  if(dot(d,e)<0) return 2;//"ONLINE_BACK"
  if(abs(d) < abs(e)) return -2;//"ONLINE_FRONT"
  return 0;//"ON_SEGMENT"
}


vector <point> Convex_Hull(vector <point> a){
  vector<point> b,c;
  sort(a.begin(),a.end());
  if(a.size()<=3) return a;

  b.push_back(a[0]);
  b.push_back(a[1]);
  for(int i=2;i<a.size();i++){
    //CLOCKWISE or ON_SEGMENT
    for(int j=b.size();j>=2&&ccw(b[j-2],b[j-1],a[i])!=-1&&ccw(b[j-2],b[j-1],a[i])!=0;j--)b.pop_back();
    b.push_back(a[i]);
  }

  c.push_back(a.back());
  c.push_back(a[a.size()-2]);
  for(int i=a.size()-3;i>=0;i--){
    //CLOCKWISE or ON_SEGMENT
    for(int j=c.size();j>=2&&ccw(c[j-2],c[j-1],a[i])!=-1&&ccw(b[j-2],b[j-1],a[i])!=0;j--) c.pop_back();
    c.push_back(a[i]);
  } 
  reverse(c.begin(),c.end());
  for(int i=b.size()-2;i>=1;i--) c.push_back(b[i]);
  return c;
}

