// Graham Scan
vector<Point> convexHull(vector<Point> points){
  int n = points.size();
  sort(all(points));
  int k=0;
  vector<Point> qs(2*n);
  rep(i,n){
    while(k>1 && (qs[k-1] - qs[k-2]).det(points[i] - qs[k-1]) <= 0) k--;
    qs[k++] = points[i];
  }
  for(int i=n-2,t=k; i>=0; i--){
    while(k>t && (qs[k-1] -qs[k-2]).det(points[i] - qs[k-1]) <= 0) k--;
    qs[k++] = points[i];
  }
  qs.resize(k-1);
  return qs;
}

