  static double dot( Vector v1, Vector v2 ) { return v1.x * v2.x + v1.y * v2.y; }
  static double cross( Vector v1, Vector v2 ) { return v1.x * v2.y - v1.y * v2.x; }
};

class ConvexHull
{
public:
  int n;
  vector<Vector> v;
  ConvexHull(){}
  ConvexHull( int n ) : n(n), v(n) {}
  int solve();
};

int ConvexHull::solve()
{
  sort( v.begin(), v.end() );

  list<Vector> ret;

  ret.push_back( v[0] );
  ret.push_back( v[1] );

  for ( auto i = 2; i < n; ++i )
    {
      auto it = ret.rbegin();
      Vector p2 = *it;
      ++it;
      Vector p1 = *it;

      while ( ret.size() >= 2 && Vector::cross( p2 - p1, v[i] - p2 ) < -eps )
        {
          ret.pop_back();
          it = ret.rbegin();
          p2 = *it;
          ++it;
          p1 = *it;
        }

      ret.push_back( v[i] );
    }

  ret.push_back( v[n-2] );

  for ( auto i = n - 3; i >= 0; --i )
    {
      auto it = ret.rbegin();
      Vector p2 = *it;
      ++it;
      Vector p1 = *it;

      while ( ret.size() >= 2 && Vector::cross( p2 - p1, v[i] - p2 ) < -eps )
        {
          ret.pop_back();
          it = ret.rbegin();
          p2 = *it;
          ++it;
          p1 = *it;
        }

      ret.push_back( v[i] );
    }

  ret.pop_back();

  cout << ret.size() << endl;

  for ( auto it = ret.begin(); it != ret.end(); ++it )
    cout << (*it).x << " " << (*it).y << endl;
  return 0;
}

