using namespace std;

static const double EPS=1e-12;
static const double INF=1e24;

using Point=complex<int>;
using Plane=vector<Point>;
using Polygon=vector<Point>;

bool operator<(const Point &a, const Point &b) {
    return real(a)!=real(b)? real(a)<real(b) : imag(a)<imag(b);
}

double cross_prod(const Point &a, const Point &b) {
    return imag(conj(a)*b);
}

double dot_prod(const Point &a, const Point &b) {
    return real(conj(a)*b);
}

enum {
    ONLINE_FRONT=-2,
    CLOCKWISE,
    ON_SEGMENT,
    COUNTER_CLOCKWISE,
    ONLINE_BACK,
};

int ccwise(Point a, Point b, Point c) {
    b -= a; c -= a;

    if (cross_prod(b, c) > 0) {
        return COUNTER_CLOCKWISE;
    } else if (cross_prod(b, c) < 0) {
        return CLOCKWISE;
    } else if (dot_prod(b, c) < 0) {
        return ONLINE_BACK;
    } else if (norm(b) < norm(c)) {
        return ONLINE_FRONT;
    } else {
        return ON_SEGMENT;
    }
}

Polygon convex_hull(Polygon g) {
    size_t V=g.size(), k=0;
    sort(g.begin(), g.end(), [](const Point &x, const Point &y) {
        return real(x)!=real(y)? real(x)<real(y) : imag(x)<imag(y);
    });

    Polygon chull(V<<1);
    for (size_t i=0; i<V; chull[k++]=g[i++])
        while (k >= 2) {
            int state=ccwise(chull[k-2], chull[k-1], g[i]);
            if (state > 0 || state < -1)
                break;

            --k;
        }

    for (size_t i=V-2, t=k+1; ~i; chull[k++]=g[i--])
        while (k >= t) {
            int state=ccwise(chull[k-2], chull[k-1], g[i]);
            if (state > 0 || state < -1)
                break;

            --k;
        }

    chull.resize(k-1);
    return chull;
}

int main() {
    size_t n;
    scanf("%zu", &n);

    Polygon g(n);
    for (size_t i=0; i<n; ++i) {
        int x, y;
        scanf("%d %d", &x, &y);
        g[i] = Point(x, y);
    }

    Polygon h=convex_hull(g);
    printf("%zu\n", h.size());
    for (size_t i=0; i<h.size(); ++i)
        printf("%d %d\n", real(h[i]), imag(h[i]));

    return 0;
}

