bool fge(double x, double y) { return x >= y - eps; }
double fsqrt(double x) { return feq(x, 0) ? 0 : sqrt(x); }

// polygon

struct pt_t {
	double x, y;
	pt_t operator+(const pt_t &p) const { return { x + p.x, y + p.y }; }
	pt_t operator-(const pt_t &p) const { return { x - p.x, y - p.y }; }
	pt_t operator*(const double &c) const { return { x * c, y * c }; }
	bool operator<(const pt_t &another) const {
		return (x != another.x ? x < another.x : y < another.y);
	}
};

// aX + bY + c = 0
struct line_t {
	double a, b, c;
};

// (X - x)^2 + (Y - y)^2 = r^2
struct circle_t {
	double x, y, r;
};

// normal vector = (a, b), passing p
line_t solve_line(double a, double b, pt_t p) {
	return { a, b, -a * p.x - b * p.y };
}

// passing p, q
line_t solve_line(pt_t p, pt_t q) {
	return solve_line(q.y - p.y, -q.x + p.x, p);
}

// t should be radius
pt_t rot(pt_t p, double r) {
	return {
		cos(r) * p.x - sin(r) * p.y,
		sin(r) * p.x + cos(r) * p.y
	};
}

double norm2(pt_t p) {
	return p.x * p.x + p.y * p.y;
}

double norm(pt_t p) {
	return sqrt(norm2(p));
}

// angle [0, 2PI) of vector p to vector q
double angle(pt_t p, pt_t q) {
	p = p * (1.0 / norm(p));
	q = q * (1.0 / norm(q));
	double r0 = acos(max(min(p.x * q.x + p.y * q.y, 1.0), -1.0));
	double r1 = asin(max(min(p.x * q.y - p.y * q.x, 1.0), -1.0));
	if (r1 >= 0) return r0;
	else return 2 * M_PI - r0;
}

double dist(line_t l, pt_t p) {
	return abs(l.a * p.x + l.b * p.y + l.c)
		/ sqrt(l.a * l.a + l.b * l.b);
}

bool on_same_line(pt_t s, pt_t t, pt_t p) {
	line_t l = solve_line(s, t);
	if (feq(dist(l, p), 0)) return true;
	else return false;
}

bool in_segment(pt_t s, pt_t t, pt_t p) {
	line_t l = solve_line(s, t);
	if (feq(dist(l, p), 0)
		&& fge(p.x, min(s.x, t.x))
		&& fge(max(s.x, t.x), p.x)
		&& fge(p.y, min(s.y, t.y))
		&& fge(max(s.y, t.y), p.y)) return true;
	else return false;
}

// (NAN, NAN) if lines coincide with each other
// (INF, INF) if lines are parallel but not coincide
pt_t cross_point(line_t l, line_t m) {
	double d = l.a * m.b - l.b * m.a;
	if (feq(d, 0)) {
		if (feq(l.a * m.c - l.c * m.a, 0)) return { INF, INF };
		else return { NAN, NAN };
	}
	else {
		double x = l.b * m.c - m.b * l.c;
		double y = l.a * m.c - m.a * l.c;
		return { x / d, y / -d };
	}
}

// if size is 0, then not crossed
vector<pt_t> cross_point(circle_t f, line_t l) {
	double d = dist(l, { f.x, f.y });
	if (!fge(f.r, d)) return {};
	line_t m = solve_line(l.b, -l.a, { f.x, f.y });
	pt_t p = cross_point(l, m);
	if (feq(d, f.r)) return { p };
	else {
		pt_t u = { l.b, -l.a };
		pt_t v = u * (sqrt(pow(f.r, 2) - pow(d, 2)) / norm(u));
		return { p + v, p - v };
	}
}

// if size is 0, then not crossed
vector<pt_t> cross_point(circle_t f, circle_t g) {
	line_t l = {
		-2 * f.x + 2 * g.x,
		-2 * f.y + 2 * g.y,
		(f.x * f.x + f.y * f.y - f.r * f.r) - (g.x * g.x + g.y * g.y - g.r * g.r)
	};
	return cross_point(f, l);
}

// tangent points of f through p
// if size is 0, then p is strictly contained in f
// if size is 1, then p is on f
// otherwise size is 2
vector<pt_t> tangent_point(circle_t f, pt_t p) {
	vector<pt_t> ret;
	double d2 = norm2(pt_t({ f.x, f.y }) - p);
	double r2 = d2 - f.r * f.r;
	if (fge(r2, 0)) {
		circle_t g = { p.x, p.y, fsqrt(r2) };
		ret = cross_point(f, g);
	}
	return ret;
}

// tangent lines of f through p
// if size is 0, then p is strictly contained in f
// if size is 1, then p is on f
// otherwise size is 2
vector<line_t> tangent_line(circle_t f, pt_t p) {
	vector<pt_t> qs = tangent_point(f, p);
	vector<line_t> ret(qs.size());
	Loop(i, ret.size()) {
		ret[i] = solve_line(qs[i].x - f.x, qs[i].y - f.y, qs[i]);
	}
	return ret;
}

// tangent points on f through which there is a line tangent to g
// if size is 0, then one is strictly contained in the other
// if size is 1, then they are touched inside
// if size is 2, then they are crossed
// if size is 3, then they are touched outside
// otherwise size is 4
vector<pt_t> tangent_point(circle_t f, circle_t g) {
	vector<pt_t> ret;
	double d2 = norm2({ g.x - f.x, g.y - f.y });
	vector<double> r2(2);
	r2[0] = d2 - f.r * f.r + 2 * f.r * g.r;
	r2[1] = d2 - f.r * f.r - 2 * f.r * g.r;
	Loop(k, 2) {
		if (fge(r2[k], 0)) {
			circle_t g2 = { g.x, g.y, fsqrt(r2[k]) };
			vector<pt_t> buf = cross_point(f, g2);
			Loop(i, buf.size()) ret.push_back(buf[i]);
		}
	}
	return ret;
}

// common tangent lines between two circles
// if size is 0, then one is strictly contained in the other
// if size is 1, then they are touched inside
// if size is 2, then they are crossed
// if size is 3, then they are touched outside
// otherwise size is 4
vector<line_t> tangent_line(circle_t f, circle_t g) {
	vector<pt_t> qs = tangent_point(f, g);
	vector<line_t> ret(qs.size());
	Loop(i, ret.size()) {
		ret[i] = tangent_line(f, qs[i]).front();
	}
	return ret;
}

// inner product
double dot(pt_t p, pt_t q) {
	return p.x * q.x + p.y * q.y;
}

// outer product
double cross(pt_t p, pt_t q) {
	return p.x * q.y - p.y * q.x;
}

// suppose a is counterclockwise, a.size() >= 3
double polygon_area(vector<pt_t> a) {
	double ret = 0;
	Loop(i, a.size()) {
		int j = (i + 1 < a.size() ? i + 1 : 0);
		ret += cross(a[i], a[j]);
	}
	ret = abs(ret) / 2;
	return ret;
}

class Triangulate {
private:
	vvi tri_ids;
	vector<vector<pt_t>> tri_pts;
	vector<pt_t> a;
	bool enable(pt_t p, pt_t q, pt_t r) {
		line_t l = solve_line(q, r);
		if (feq(dist(l, p), 0)) return false;
		if (fge(cross(q - p, r - p), 0)) return true;
		else return false;
	}
	void contraction(vi &ids) {
		int n = ids.size();
		if (n < 3) return;
		Loop(i, n) {
			int id_p = (i - 1 + n) % n;
			int id_q = i;
			int id_r = (i + 1) % n;
			pt_t p = a[ids[id_p]];
			pt_t q = a[ids[id_q]];
			pt_t r = a[ids[id_r]];
			line_t l = solve_line(p, r);
			if (feq(dist(l, q), 0)) {
				ids.erase(ids.begin() + i);
				contraction(ids);
				return;
			}
		}
	}
	void divide(vi &ids) {
		contraction(ids);
		int n = ids.size();
		if (n < 3) return;
		Loop(i, n) {
			int id_p = (i - 1 + n) % n;
			int id_q = i;
			int id_r = (i + 1) % n;
			pt_t p = a[ids[id_p]];
			pt_t q = a[ids[id_q]];
			pt_t r = a[ids[id_r]];
			if (enable(p, q, r)) {
				line_t l = solve_line(p, r);
				bool judge = true;
				Loop(j, n) {
					if (j == id_p || j == id_q || j == id_r) continue;
					pt_t xp = a[ids[j]];
					if (in_triangle({ p,q,r }, xp)) judge = false;
				}
				if (judge) {
					tri_ids.push_back({ id_p, id_q, id_r });
					tri_pts.push_back({ p, q, r });
					ids.erase(ids.begin() + i);
					divide(ids);
					return;
				}
			}
		}
	}
	int in_triangle(const vector<pt_t> &a, pt_t p) {
		int ret = 2;
		Loop(i, 3) {
			int j = (i + 1) % 3;
			line_t l = solve_line(a[i], a[j]);
			double d = dist(l, p);
			if (feq(d, 0)) ret = 1;
			else if (fge(M_PI, angle(a[j] - a[i], p - a[i])));
			else return 0;
		}
		return ret;
	}
public:
	// each triangle will be represented counterclockwisely
	Triangulate(const vector<pt_t> &a) {
		this->a = a;
		vi ids(a.size());
		Loop(i, ids.size()) ids[i] = i;
		divide(ids);
	}
	vvi get_ids() {
		return tri_ids;
	}
	vector<vector<pt_t>> get_pts() {
		return tri_pts;
	}
	// suppose a is counterclockwise, a.size() >= 3
	// return 0 if not, return 1 if on line, return 2 if strictly included
	int in_polygon(pt_t p) {
		int ret = 0;
		Loop(i, tri_pts.size()) {
			if (in_triangle(tri_pts[i], p)) {
				ret = 2;
			}
		}
		if (ret != 0) {
			Loop(i, a.size()) {
				int j = (i + 1) % a.size();
				if (in_segment(a[i], a[j], p)) ret = 1;
			}
		}
		return ret;
	}
};

vector<pt_t> convex_hull(vector<pt_t> ps) {
	int n = ps.size();
	sort(ps.begin(), ps.end());
	Loop(i, n - 1) ps.push_back(ps[n - 2 - i]);
	vector<pt_t> ret;
	int m = 2;
	Loop(i, n * 2 - 1) {
		if (i == n) m = ret.size() + 1;
		while (ret.size() >= m) {
			int k = ret.size();
			if (in_segment(ret[k - 2], ps[i], ret[k - 1])) break;
			else if (fge(cross(ret[k - 1] - ret[k - 2], ps[i] - ret[k - 2]), 0)) ret.pop_back();
			else break;
		}
		ret.push_back(ps[i]);
	}
	ret.pop_back();
	reverse(ret.begin(), ret.end());
	return ret;
}


int main() {
	int n; cin >> n;
	vector<pt_t> ps(n);
	Loop(i, n) {
		cin >> ps[i].x >> ps[i].y;
	}
	vector<pt_t> a = convex_hull(ps);
	int min_id = -1;
	pt_t min_pt = { INF, INF };
	Loop(i, a.size()) {
		if ((a[i].y < min_pt.y)
			|| (a[i].y == min_pt.y && a[i].x < min_pt.x)) {
			min_id = i;
			min_pt = a[i];
		}
	}
	cout << a.size() << endl;
	Loop(i, a.size()) {
		int k = (min_id + i) % a.size();
		cout << a[k].x << " " << a[k].y << endl;
	}
}

#include <bits/stdc++.h>
using namespace std;
#pragma region Geometry
const double EPS=1e-8,PI=acos(-1);
inline bool EQ(double a,double b){return fabs(b-a)<EPS;}

static const int COUNTER_CLOCKWISE=1;
static const int CLOCKWISE=-1;
static const int ONLINE_BACK=2;
static const int ONLINE_FRONT=-2;
static const int ON_SEGMENT=0;

struct Point{
    double x,y;
    Point(){}
    Point(double x,double y):x(x),y(y){}
    Point operator+(Point p) const {return Point{x+p.x,y+p.y};}
    Point operator-(Point p) const {return Point{x-p.x,y-p.y};}
    Point operator*(double t) const {return Point{x*t,y*t};}
    Point operator*(Point p) const {return Point{x*p.x-y*p.y,x*p.y+y*p.x};}
    Point operator/(double t) const {return Point{x/t,y/t};}
    bool operator<(const Point &p) const {
        return x!=p.x?x<p.x:y<p.y;
    }
    bool operator==(const Point &p) const {
        return fabs(x-p.x)<EPS&&fabs(y-p.y)<EPS;
    }
    friend istream &operator>>(istream &is,Point &p){
        is >> p.x >> p.y;
        return is;
    }
    friend ostream &operator<<(ostream &os,Point p){
        os << fixed << setprecision(10) << p.x << ' ' << p.y;
        return os;
    }
};

struct Line{
    Point a,b;
    Line(){}
    Line(Point a,Point b):a(a),b(b){}
    friend istream &operator>>(istream &is,Line &l){
        is >> l.a >> l.b;
        return is;
    }
    friend ostream &operator<<(ostream &os,Line l){
        os << l.a << " to " << l.b;
        return os;
    }
};

struct Segment:Line{
    Segment(){}
    Segment(Point a,Point b):Line(a,b){}
};

struct Circle{
    Point c;
    double r;
    Circle(){}
    Circle(Point c,double r):c(c),r(r){}
    friend istream &operator>> (istream &is,Circle &c){
        is >> c.c >> c.r;
        return is;
    }
    friend ostream &operator<<(ostream &os,Circle &c){
        os << c.c << ' ' << c.r;
        return os;
    }
};

typedef vector<Point> Polygon;
istream &operator>>(istream &is,Polygon &p){
    for (int i=0;i<p.size();++i) is >> p[i];
    return is;
}

double dot(const Point &a,const Point &b){
    return a.x*b.x+a.y*b.y;
}
double cross(const Point &a,const Point &b){
    return a.x*b.y-a.y*b.x;
}
double norm(const Point &a){
    return a.x*a.x+a.y*a.y;
}
double abs(const Point &a){
    return sqrt(norm(a));
}

// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/1/CGL_1_A
Point proj(const Line &l,const Point &p){
    double t=dot(p-l.a,l.b-l.a)/norm(l.b-l.a);
    return l.a+(l.b-l.a)*t;
}
// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/1/CGL_1_B
Point refl(const Line &l,const Point &p){
    return p+(proj(l,p)-p)*2.0;
}

Point rotate(const Point &p,double theta){
    return Point(cos(theta)*p.x-sin(theta)*p.y,sin(theta)*p.x+cos(theta)*p.y);
}
double arg(const Point &p){
    return atan2(p.y,p.x);
}
double get_angle(const Point &a,const Point &b,const Point &c){
    const Point v=b-a,w=c-b;
    double alpha=arg(v),beta=arg(w);
    if (alpha>beta) swap(alpha,beta);
    double theta=beta-alpha;
    return min(theta,2*PI-theta);
}

// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/1/CGL_1_C
int ccw(const Point &a,Point b,Point c){
    b=b-a,c=c-a;
    if (cross(b,c)>EPS) return COUNTER_CLOCKWISE;
    if (cross(b,c)<-EPS) return CLOCKWISE;
    if (dot(b,c)<-EPS) return ONLINE_BACK;
    if (norm(b)<norm(c)) return ONLINE_FRONT;
    return ON_SEGMENT;
}

// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/2/CGL_2_A
bool orthogonal(const Point &a,const Point &b){
    return EQ(dot(a,b),0.0);
}
bool orthogonal(const Point &a,const Point &b,const Point &c,const Point &d){
    return orthogonal(b-a,d-c);
}
bool orthogonal(const Line &l,const Line &m){
    return EQ(dot(l.b-l.a,m.b-m.a),0.0);
}
// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/2/CGL_2_A
bool parallel(const Point &a,const Point &b){
    return EQ(cross(a,b),0.0);
}
bool parallel(const Point &a,const Point &b,const Point &c,const Point &d){
    return parallel(b-a,d-c);
}
bool parallel(const Line &l,const Line &m){
    return EQ(cross(l.b-l.a,m.b-m.a),0.0);
}

bool intersect(const Line &l,const Point &p){
    return abs(ccw(l.a,l.b,p))!=1;
}
bool intersect(const Line &l,const Line &m){
    return abs(cross(l.b-l.a,m.b-m.a)>EPS||abs(cross(l.b-l.a,m.b-m.a))<EPS);
}
bool intersect(const Line &l,const Segment &s){
    return cross(l.b-l.a,s.a-l.a)*cross(l.b-l.a,s.b-l.a)<EPS;
}
bool intersect(const Segment &s,const Point &p){
    return ccw(s.a,s.b,p)==0;
}
// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/2/CGL_2_B
bool intersect(const Segment &s,const Segment &t){
    return ccw(s.a,s.b,t.a)*ccw(s.a,s.b,t.b)<=0&&ccw(t.a,t.b,s.a)*ccw(t.a,t.b,s.b)<=0;
}
bool intersect(const Circle &c,const Line &l){
    return (norm(proj(l,c.c)-c.c)-c.r*c.r)<=EPS;
}
int intersect(const Circle &c,const Segment &s){
    if (norm(proj(s,c.c)-c.c)-c.r*c.r>EPS) return 0;
    double d1=abs(c.c-s.a),d2=abs(c.c-s.b);
    if (d1<c.r+EPS&&d2<c.r+EPS) return 0;
    if (d1<c.r-EPS&&d2>c.r+EPS||d1>c.r+EPS&&d2<c.r-EPS) return 1;
    const Point h=proj(s,c.c);
    if (dot(s.a-h,s.b-h)<0) return 2;
    return 0;
}
// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/7/CGL_7_A
int intersect(Circle c,Circle d){
    if (c.r<d.r) swap(c,d);
    double dist=abs(c.c-d.c);
    if (c.r+d.r<dist) return 4;
    if (EQ(c.r+d.r,dist)) return 3;
    if (c.r-d.r<dist) return 2;
    if (EQ(c.r-d.r,dist)) return 1;
    return 0;
}

double distance(const Point &a,const Point &b){
    return abs(b-a);
}
double distance(const Line &l,const Point &p){
    return abs(p-proj(l,p));
}
double distance(const Line &l,const Line &m){
    return intersect(l,m)?0:distance(l,m.a);
}
double distance(const Segment &s,const Point &p){
    Point h=proj(s,p);
    return intersect(s,h)?abs(h-p):min(abs(s.a-p),abs(s.b-p));
}
// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/2/CGL_2_D
double distance(const Segment &s,const Segment &t){
    if (intersect(s,t)) return 0;
    return min({distance(s,t.a),distance(s,t.b),distance(t,s.a),distance(t,s.b)});
}
double distance(const Line &l,const Segment &s){
    return intersect(l,s)?0:min(distance(l,s.a),distance(l,s.b));
}

Point crosspoint(const Line &l,const Line &m){
    double d1=cross(l.b-l.a,m.b-m.a),d2=cross(l.b-l.a,l.b-m.a);
    if (EQ(abs(d1),0.0)&&EQ(abs(d2),0.0)) return m.a;
    return m.a+(m.b-m.a)*d2/d1;
}
// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/2/CGL_2_C
Point crosspoint(const Segment &s,const Segment &t){
    assert(intersect(s,t));
    return crosspoint(Line(s),Line(t));
}
// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/7/CGL_7_D
vector<Point> crosspoint(const Circle &c,const Line &l){
    Point pr=proj(l,c.c);
    Point e=(l.b-l.a)/abs(l.b-l.a);
    if (EQ(distance(l,c.c),c.r)) return {pr};
    double base=sqrt(c.r*c.r-norm(pr-c.c));
    return {pr-e*base,pr+e*base};
}
vector<Point> crosspoint(const Circle &c,const Segment &s){
    Line l=Line(s);
    assert(intersect(c,l));
    auto res=crosspoint(c,l);
    if (intersect(c,l)==2) return res;
    if (dot(l.a-res[0],l.b-res[0])<0) res.emplace_back(res[0]);
    else res.pop_back();
    return res;
}
// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/7/CGL_7_E
vector<Point> crosspoint(const Circle &c,const Circle &d){
    double dist=abs(c.c-d.c);
    double a=acos((c.r*c.r+dist*dist-d.r*d.r)/(2*c.r*dist));
    double t=arg(d.c-c.c);
    Point p1=c.c+Point(cos(t+a),sin(t+a))*c.r,p2=c.c+Point(cos(t-a),sin(t-a))*c.r;
    return {p1,p2};
}

// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/7/CGL_7_C
Circle circumcenter(Point a,Point b,const Point &c){
    a=(a-c)*0.5;
    b=(b-c)*0.5;
    Point center=c+crosspoint(Line(a,a*Point{1,1}),Line{b,b*Point{1,1}});
    return Circle{center,abs(c-center)};
}
vector<Point> center_given_radius(const Point &a,const Point &b,const double &r){
    Point m=(b-a)*0.5;
    double d1=abs(m);
    vector<Point> res;
    if (EQ(d1,0.0)||d1>r) return res;
    double d2=sqrt(r*r-d1*d1);
    Point n=m*Point{0.0,1.0}*d2/d1;
    res.emplace_back(a+m+n);
    if (d2>EPS) res.emplace_back(a+m-n);
    return res;
}

// https://onlinejudge.u-aizu.ac.jp/courses/library/4/CGL/3/CGL_3_B
bool convex(const Polygon &p){
    int n=p.size();
    for (int i=0;i<n;++i){
        if (ccw(p[(i+n-1)%n],p[i],p[(i+1)%n])==-1){
            return false;
        }
    }
    return true;
}
Polygon convex_hull(Polygon p){
    int n=p.size(),k=0;
    if (n<=2) return p;
    sort(p.begin(),p.end());
    Polygon ch(2*n);
    for (int i=0;i<n;ch[k++]=p[i++]){
        while(k>=2&&cross(ch[k-1]-ch[k-2],p[i]-ch[k-1])<0) --k;
    }
    for (int i=n-2,t=k+1;i>=0;ch[k++]=p[i--]){
        while(k>=t&&cross(ch[k-1]-ch[k-2],p[i]-ch[k-1])<0) --k;
    }
    ch.resize(k-1);
    return ch;
}

