vector<P> ConvexHull(vector<P> s){
    vector<P> upper,lower;
    int n = (int)s.size();

    if(n<3) return s;

    sort(s.begin(),s.end());

    upper.push_back(s[0]);
    upper.push_back(s[1]);
    lower.push_back(s[n-1]);
    lower.push_back(s[n-2]);

    for(int i=2;i<n;i++){
        for(int m = (int)upper.size();m>=2 && ccw(upper[m-2],upper[m-1],s[i]); m--){
            upper.pop_back();
        }
        upper.push_back(s[i]);
    }

    for(int i=n-3;i>=0;i--){
        for(int m = (int)lower.size();m>=2 && ccw(lower[m-2],lower[m-1],s[i]); m--){
            lower.pop_back();
        }
        lower.push_back(s[i]);
    }

    reverse(lower.begin(),lower.end());
    for(int i=(int)upper.size()-2;i>=1;i--) lower.push_back(upper[i]);

    return lower;
}

