    cout<<A[i].X<<" "<<A[i].Y<<endl;
}

bool ok(point A,point B,point C)
{
  if(A==Null || C==Null || cross(C-A,B-A)>=0)
    return true;
}

vector<point> find_hull(vector<point> allp, point left, point right)
{
  vector<point> p;
  for(int i=0;i<allp.size();i++)
    if(ok(left,allp[i],right))
      p.push_back(allp[i]);
  if(p.size()<2) return p;
  vector<point> vec;
  for(int i=1;i<p.size();i+=2)
    vec.push_back(shib(p[i],p[i-1]));
  sort(vec.begin(),vec.end(),cmp);
  point med = vec[vec.size()/2];
  point dir = point(-med.Y,med.X);
  int mx = 0;
  for(int i=1;i<p.size();i++)
    if(dot(dir,p[i])>dot(dir,p[mx]) || (dot(dir,p[i])==dot(dir,p[mx]) && p[i].Y>p[mx].Y))
      mx = i;
  vector<point> L,R;
  for(int i=0;i<p.size();i++)
    if(i!=mx)
      {
	if(p[i].X<p[mx].X || (p[i].X==p[mx].X && left==Null)){
	  if(p[i].X<=p[i^1].X || !cmp(shib(p[i],p[i^1]),med))
	     L.push_back(p[i]);
	}
	if(p[i].X>p[mx].X || (p[i].X==p[mx].X && left!=Null)){
	  if(p[i].X>=p[i^1].X || !cmp(med,shib(p[i],p[i^1])))
	    R.push_back(p[i]);
	}
      }
  vector<point> lret = find_hull(L,left,p[mx]);
  vector<point> rret = find_hull(R,p[mx],right);
  vector<point> ret;
  for(int i=0;i<lret.size();i++)
    if(ok(left,lret[i],right) && ok((i==0?Null:lret[i-1]),lret[i],right))
      ret.push_back(lret[i]);
  if(ok(left,p[mx],right) && ok(left,p[mx],(rret.size()?rret[0]:Null)) && ok((lret.size()?lret.back():Null),p[mx],right))
