// Actual Solver
inline void solve()
{
    cout << fixed << setprecision(0);
    int n;
    cin >> n;
    Polygon p, convex;
    p.read(n);
    p.getConvexJarvis(convex);

    int len = convex.size();

    cout << len << '\n';
    if (len != 1)
    {
        Point t = convex.ps[0];
        int pos = 0;
        FOR(i, 1, len)
        {
            if (t.y > convex.ps[i].y)
            {
                t = convex.ps[i];
                pos = i;
            }
        }

        FOR(i, 0, len)
        {
            int cur = (pos + i) % len;
            convex.ps[cur].write('\n');
        }
    }
    else
        convex.ps[0].write('\n');
}

