	stk1.push_back(pp[0]); 
	stk1.push_back(pp[1]); 
	stk2.push_back(pp[n-1]); 
	stk2.push_back(pp[n-2]); 
	for(int i=2;i<n;i++){
		for(int j=stk1.size();j>=2&&ccw(stk1[j-2],stk1[j-1],pp[i])!=CLOCKWISE;j--)
			stk1.pop_back();
