class Point {
public:
    int x, y;
    Point(int a = 0, int b = 0) { 
        x = a;
        y = b; 
    }
    bool operator <(const Point &p) const {
        return y < p.y || (y == p.y && x < p.x);
    }
};

void convex_hull(std::vector<Point>& P)
{
    int k = 1;
    int n = P.size();
    std::vector<Point> H;
    H.push_back(P[0]);
    H.push_back(P[1]);
    int i;
    for (i = 0; i < n - 2; i++) {
        while (k >= 1 && (H[k].x - H[k - 1].x) * (P[i + 2].y - H[k - 1].y) - (H[k].y - H[k - 1].y) * (P[i + 2].x - H[k - 1].x) < 0) {
            H.pop_back();
            k--;
        }
        H.push_back(P[i + 2]);
        k++;
    }
    H.push_back(P[n - 2]);
    for (i = n; i > 2; i--) {
        while ((H[k + 1].x - H[k].x) * (P[i - 3].y - H[k].y) - (H[k + 1].y - H[k].y) * (P[i - 3].x - H[k].x) < 0) {
            H.pop_back();
            k--;
        }
        H.push_back(P[i - 3]);
        k++;
    }
    H.pop_back();
    printf("%d\n", H.size());
    for (i = 0; i < (int)H.size(); i++) {
        printf("%d %d\n", H[i].x, H[i].y);
    }
}

