using namespace std;

#define pdd pair<double, double> 
typedef complex<double> xy_t;

int N;
vector<pdd> vec, ansU, ansL;
double X[100000+5], Y[100000+5];

double cross_product(xy_t a, xy_t b) {return (conj(a)*b).imag();}

bool convex(pdd p1, pdd p2, pdd p3){ //左向きに並んでいるか?
    xy_t a(p1.first, p1.second);
    xy_t b(p2.first, p2.second);
    xy_t c(p3.first, p3.second);

    xy_t e1 = b - a;
    xy_t e2 = c - b;

    // cout << "Area by a:" << a << " b:" << b << " c:" << c << " is " << cross_product(e1, e2) << endl;

    if (cross_product(e1, e2) >= 0)
        return true; //符号付面積が正または0なら左向き ※一直線になる場合もあることに注意
    else 
        return false; //右向き
}

bool check(vector<pdd> ans_buff, pdd p){
    if(ans_buff.size() < 2) return true;

    pdd p_buff1 = ans_buff.back(); ans_buff.pop_back(); //p1に相当
    pdd p_buff2 = ans_buff.back(); //p0に相当

    if(convex(p_buff2, p_buff1, p)) return true; //点の順番に注意する

    return false;
}

int main(){
    cin >> N;

    for(int i = 0; i < N; i++){
        cin >> X[i] >> Y[i];
        vec.push_back(make_pair(X[i], Y[i]));
    }

    //下側の計算
    sort(vec.begin(), vec.end());

    ansL.push_back(vec[0]);ansL.push_back(vec[1]); //最初の2点を格納

    for(int i = 2; i < N; i++){ //下側の点列を生成
        pdd p3 = vec[i];
        // cout << "Cuurent: (" << p3.first << ", " << p3.second << ")"<< endl;
        pdd p2 = ansL.back(); ansL.pop_back();
        pdd p1 = ansL.back();

        if(convex(p1, p2, p3)){ //p2をansに戻す
            ansL.push_back(p2);
        }
        else{
            while(!check(ansL, p3)) //p3を加えるに際しp2より前の点も取り除く必要がないか確認
                ansL.pop_back();
        }   
        ansL.push_back(p3); //p3を追加
    }
    ansL.pop_back(); //終点を削除

    //上側の計算
    reverse(vec.begin(), vec.end()); //x座標を昇順に並べる
    ansU.push_back(vec[0]); ansU.push_back(vec[1]); //最初の2点を格納

    for(int i = 2; i < N; i++){ //上側の点列を生成
        pdd p3 = vec[i];
        // cout << "Cuurent: (" << p3.first << ", " << p3.second << ")"<< endl;
        pdd p2 = ansU.back(); ansU.pop_back();
        pdd p1 = ansU.back();

        if(convex(p1, p2, p3)){ //p2をansに戻す
            ansU.push_back(p2);
        }
        else{
            while(!check(ansU, p3)) //p3を加えるに際しp2より前の点も取り除く必要がないか確認
                ansU.pop_back();
        }   
        ansU.push_back(p3); //p3を追加
    }
    ansU.pop_back(); //終点を削除

    //出力開始位置が最も下にあるものの中で最も左にある頂点になるよう調整
    while( ansL.size() >= 2 && ansL[0].second > ansL[1].second){
        ansU.push_back(ansL.front());
        ansL.erase(ansL.begin());
    }

    //出力
    cout << ansU.size() + ansL.size() << endl;

    for(auto itr=ansL.begin(); itr!=ansL.end(); itr++){
        cout << itr->first << " " << itr->second << endl;
    }

    for(auto itr=ansU.begin(); itr!=ansU.end(); itr++){
        cout << itr->first << " " << itr->second << endl;
    }
}

