//??????(O(n))
//?????????
//  x->y?????????§????????°???????????????????????????¨???????
Polygon AndrewScan(Polygon &s)
{
    if (s.size() <= 2) return s;
    sort(s.begin(), s.end(), comp);
    Polygon g;
    for (int i = 0; i < s.size(); i++)
    {
        //CCW??????¨?????????==COUNTER_CLOCKWISE????????????¨???????????????
        for (int n = g.size(); n >= 2 && CCW(g[n - 2], g[n - 1], s[i]) == COUNTER_CLOCKWISE; n--)
        {
            g.pop_back();
        }
        g.push_back(s[i]);
    }
    for (int i = s.size() - 2; i >= 0; i--)
    {
        for (int n = g.size(); CCW(g[n - 2], g[n - 1], s[i]) == COUNTER_CLOCKWISE; n--)
        {
            g.pop_back();
        }
        g.push_back(s[i]);
    }
    reverse(g.begin(), g.end());
    g.pop_back();
    return g;
}

//????????§????¢?????????(O(n))
Polygon ConvexCut(const Polygon &g, const Line &l)
{
    Polygon res;
    for (int i = 0; i < g.size(); i++)
    {
        Segment s = Segment(g[i], g[(i + 1) % g.size()]);
        if (CCW(l.a, l.b, s.a) != -1) res.push_back(s.a);
        if (CCW(l.a, l.b, s.a)*CCW(l.a, l.b, s.b) == -1) 
            res.push_back(GetIntersection(l, ToLine(s)));
    }
    return res;
}

