typedef complex<double> Point;

namespace std {
	bool operator<(Point &a, Point &b) {
		return a.real() != b.real() ? a.real() < b.real() : a.imag() < b.imag();
	}
}

double cross(Point a, Point b) {
	return a.real() * b.imag() - a.imag() * b.real();
}

Point toV(Point a, Point b) {
	return b - a;
}

vector<Point> convex(vector<Point> &ps) {
	static Point stkLow[100000]; int spL = 0;
	static Point stkUp[100000]; int spU = 0;

	sort(ps.begin(), ps.end());
	for (int i = 0; i < ps.size(); i++) {
		while (spL >= 2) {
			Point a = toV(stkLow[spL - 2], stkLow[spL - 1]);
			Point b = toV(stkLow[spL - 1], ps[i]);
			if (cross(a, b) < 0) spL--;
			else break;
		}
		stkLow[spL++] = ps[i];
	}

	for (int i = (int)ps.size() - 1; i >= 0; i--) {
		while (spU >= 2) {
			Point a = toV(stkUp[spU - 2], stkUp[spU - 1]);
			Point b = toV(stkUp[spU - 1], ps[i]);
			if (cross(a, b) < 0) spU--;
			else break;
		}
		stkUp[spU++] = ps[i];
	}

	vector<Point> ret;
	for (int i = 0; i < spL; i++) ret.push_back(stkLow[i]);
	for (int i = 1; i < spU - 1; i++) ret.push_back(stkUp[i]);
	return ret;
}

