  for (int i = 0; i < n; i++) {
    double x, y;
    cin >> x >> y;
    ps.emplace_back(x, y);
  }
  ConX c(ps);

  int j = 0;
  p2 st = c.ps[0];
  for (int i = 1; i < c.size(); i++) {
    if (st.imag() > c.ps[i].imag() ||
        (same(st.imag(), c.ps[i].imag()) && st.real() > c.ps[i].real())) {
      st = c.ps[i];
      j = i;
    }
  }

  cout << c.size() << endl;
  for (int i = 0; i < c.size(); i++) {
    int x = c.ps[(i + j) % c.size()].real();
    int y = c.ps[(i + j) % c.size()].imag();
