	int sum=0;
	for (int i=1;i<=n;i++)
	  if ((vis[i] || vis[i%n+1]) && CJ(Q-P,A[i]-P)*CJ(Q-P,A[i%n+1]-P)<=0) sum++;//修改过的点只需判断所在的边是否在射线两侧 
	  else if (CGL_2_B(A[i],A[i%n+1],P,Q)) sum++;//其余的边经过射线的个数
	for (int i=1;i<=n;i++)
	  if (vis[i]) A[i].y++;//移回来 
	return (sum&1)?2:0;//2-在多边形内 0-在多边形外 
}
void CGL_4_A(point *A,int &n){//Convex求凸包
	base=A[1];top=0;//base为起点 
	for (int i=1;i<=n;i++) A[i]=A[i]-base;//从起点开始的向量 
	sort(A+2,A+n+1,cmp);//按极角排序 
	sta[++top]=1;//单调栈维护凸包 
	for (int i=2;i<=n;sta[++top]=i,i++){
	  while (top>1 && CJ((A[i]-A[sta[top-1]]),(A[sta[top]]-A[sta[top-1]]))>0) top--;//简单单调栈操作(用叉积来判断) 
}
	for (int i=1;i<=top;i++) A[i]=A[sta[i]]+base;//回到之前的向量 
	n=top;A[n+1]=A[1];//形成环 
}

