  double Add(double a,double b){
    if(fabs(a+b)<EPS*(fabs(a)+fabs(b)))return 0.0;
    return a+b;
  }

  double Across(Vector a,Vector b){
    return Add(a.x*b.y,-a.y*b.x);
  }

  int Accw(Point p0,Point p1,Point p2){
    Vector a = p1 - p0;
    Vector b = p2 - p0;
    if(Across(a,b) > EPS)return 1;
    return -1;
  }

  Polygon andrewScan(Polygon s){
    Polygon u,l;
    if(s.size() < 3)return s;
    sort(s.begin(),s.end());
    u.push_back(s[0]);
    u.push_back(s[1]);
    l.push_back(s[s.size()-1]);
    l.push_back(s[s.size()-2]);
    for(int i = 2;i < s.size();i++){
      for(int n = u.size();n >= 2 && Accw(u[n-2],u[n-1],s[i]) != -1;n--){
        u.pop_back();
      }
      u.push_back(s[i]);
    }

    for(int i = s.size() - 3;i >= 0;i--){
      for(int n=l.size();n >= 2 && Accw(l[n-2],l[n-1],s[i]) != -1;n--){
        l.pop_back();
      }
