namespace beet{

  template<typename T>
  struct Vector{
    int sz,cap;
    T *data;
    Vector():sz(0),cap(1){
      data = new T[cap];
    }    
    Vector(int sz):sz(sz),cap(sz<<1){
      data = new T[cap];
    }
    Vector(int sz,T t):sz(sz),cap(sz<<1){
      data = new T[cap];
      for(int i=0;i<sz;i++) data[i]=t;
    }
    Vector(const Vector &v){    
      sz=v.sz;
      cap=v.cap;  
      data = new T[v.cap];
      for(int i=0;i<sz;i++) data[i]=v[i];
    }    
    ~Vector(){
      // printf("%p\n",data);
      delete[] data;
    }
    void resolve(){
      T *tmp = new T[cap];
      for(int i=0;i<sz;i++) tmp[i]=data[i];
      delete[] data;
      data=tmp;
    }
    void push_back(T x){
      if(sz>=cap){
        cap<<=1;
        assert(sz<cap);
        resolve();
      }      
      data[sz++]=x;
    }
    void pop_back(){
      sz--;
    }
    void shrink(int nx){assert(nx<=sz);sz=nx;}
    int size() const{
      return sz;
    }
    const T operator[](int x) const{
      return data[x];
    }
    T& operator[](int x){
      assert(0<=x&&x<sz);
      return data[x];
    }
  };

  template<typename T>
  void swap(T &a,T &b){
    T x=a;
    a=b;
    b=x;
  }

  template<typename T>
  void sort(Vector<T> &vs){
    int n=vs.size();
    Vector<T> tmp(n);

    auto dfs=
      [&](int l,int r,auto &func)->void{
        // printf("%d %d\n",l,r);
        if(l+1==r) return;
        int m=(l+r)>>1;
        func(l,m,func);
        func(m,r,func);        
        for(int k=l;k<r;k++) tmp[k]=vs[k];

        int i=l,j=m,k=l;
        while(i<m&&j<r){
          if(tmp[i]<tmp[j]){
            vs[k++]=tmp[i++];
          }else{
            vs[k++]=tmp[j++];
          }
        }
        while(i<m) vs[k++]=tmp[i++];
        while(j<r) vs[k++]=tmp[j++];
      };
    dfs(0,n,dfs);
  }
}
