#define EPS (1e-10)
#define equals(a,b) (fabs((a)-(b)) < EPS)

class Point{
public:
  double x,y;

  Point(double x=0,double y=0): x(x),y(y) {}

  Point operator + (Point p) { return Point(x+p.x,y+p.y); }
  Point operator - (Point p) { return Point(x-p.x,y-p.y); }
  Point operator * (double a) { return Point(a*x,a*y); }
  Point operator / (double a) { return Point(a/x,a/y); }

  double abs() { return sqrt(norm()); }
  double norm() { return x*x+y*y; }

  bool operator < (const Point &p) const {
    return y != p.y ? y < p.y : x < p.x;
  }

  bool operator == (const Point &p) const {
    return fabs(y-p.y) < EPS && fabs(x-p.x) < EPS;
  }

};

typedef Point Vector;

double dot(Vector a,Vector b){
  return a.x * b.x + a.y * b.y;
}

double cross(Vector a,Vector b){
  return a.x * b.y - a.y * b.x;
}

bool ccw(Point p0,Point p1,Point p2){
  Vector a = p1-p0;
  Vector b = p2-p0;
  if( cross(a,b) > EPS) return true;
  return false;

}

typedef vector<Point> Polygon;

Polygon totsu(Polygon s){

  Polygon u,l;
  if(s.size() < 3) return s;
  sort(s.begin(),s.end());

  u.push_back(s[0]);
  u.push_back(s[1]);
  for(int i=2;i<s.size();i++){
    for(int j=u.size();j>=2 && ccw(u[j-2],u[j-1],s[i]);j--){
      u.pop_back();
    }
    u.push_back(s[i]);
  }

  l.push_back(s[s.size()-1]);
  l.push_back(s[s.size()-2]);
  for(int i=s.size()-3;i>=0;i--){
    for(int j=l.size();j>=2 && ccw(l[j-2],l[j-1],s[i]);j--){
      l.pop_back();
    }
    l.push_back(s[i]);
  }

  reverse(l.begin(),l.end());
  for(int i=u.size()-2;i>=1;i--) l.push_back(u[i]);

  return l;
}

