int isleft(Point a, Point b, Point c) {
    int diff = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    if(diff > 0) {
        return 1;
    } else if(diff == 0) {
        return 0;
    } else {
        return -1;
    }
}

