int main()
{
    using namespace std;
    int n;
    cin >> n;

    polygon_t poly(n);
    for (int i = 0; i < n; i++) {
        coord_t x, y;
        cin >> x >> y;
        poly[i] = point(x, y);
    }

    polygon_t convex_hull = andrew_scan(poly, false);

    index_t m = convex_hull.size();
    cout << m << endl;

    index_t min_x, min_y, min_i;
    min_x = min_y = std::numeric_limits<index_t>::max();
    for (index_t i = 0; i < n; i++) {
        if (min_y > convex_hull[i].y || (min_y == convex_hull[i].y && min_x > convex_hull[i].x)) {
            min_x = convex_hull[i].x;
            min_y = convex_hull[i].y;
            min_i = i;
        }
    }

    for (index_t i = 0; i < m; i++) {
        cout << convex_hull[(min_i + i) % m].x << " " << convex_hull[(min_i + i) % m].y << endl;
    }

    return 0;
}

