bool eq(const T& a, const T& b) {return abs(a - b) < EPS;}

typedef  complex<double> point;
namespace std {
	bool operator==(const point &a, const point &b){
	  return eq(a, b);
	}
	bool operator<(const point& a, const point& b) {
		return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
	}
}

double cross(const point& a, const point& b) {
	return imag(conj(a)*b);
}
double dot(const point& a, const point& b) {
	return real(conj(a)*b);
}
int ccw(point a, point b, point c) {
	b -= a; c -= a;
	if (cross(b, c)+EPS > 0)   return +1;  // counter clockwise
	if (cross(b, c) < EPS)   return -1;  // clockwise
	if (dot(b, c) < EPS)     return +2;  // c--a--b on line
	if (norm(b) < norm(c)+EPS) return -2;  // a--b--c on line
	return 0;  // a--c--b on line or a----bc
}

typedef array<point, 2> line;

point projection(const line& l, const point& p) {
	double t = dot(p-l[0], l[0]-l[1]) / norm(l[0]-l[1]);
	return l[0] + t*(l[0]-l[1]);
}

point reflection(const line& l, const point& p) {
return p + 2. * (projection(l, p) - p);
