void sort(std::vector<Point> &vec, const int &left, const int &right) {
	if (left < right) {
		Point pivot = vec.at(left + (right - left) / 2);
		int l = left, r = right;
		while (l <= r) {
			while (pivot > vec.at(l)) { ++l; }
			while (pivot < vec.at(r)) { --r; }
			if (l <= r) {
				auto temp{ vec.at(l) };
				vec.at(l) = vec.at(r); vec.at(r) = temp;
				++l; --r;
			}
		}
		sort(vec, left, r); sort(vec, l, right);
	}
}
auto prev(std::list<Point>::iterator i) {
	return --i;
}
std::list<Point> func(const std::vector<Point> &vector, const std::function<bool(const Vec&, const Vec&)> &lambda) {
	std::list<Point> stack;
	stack.push_back(vector.at(0)); stack.push_back(vector.at(0));
	for (auto p : vector) {
		auto e = stack.end();
		--e;
		while (!(lambda(Vec(p, *e), Vec(*e, *prev(e))))) {
			--e;
			stack.pop_back();
		}
		stack.push_back(p);
	}
	stack.pop_front(); stack.pop_front();
	return stack;
}
