        scanf("%d%d",&P[i - 1].x, &P[i - 1].y);
        Point& point = P[i - 1];
        register int j = i;
        while (j >= 2 && point < P[j - 2]) {
            P[j - 1] = P[j - 2];
            j--;
        }
        P[j - 1] = point;
    }
    H[0] = P[0];
    H[1] = P[1];
    for (i = 0; i < n - 2; ++i) {
        while (k >= 2 && direct(H[k - 2],H[k - 1],P[i + 2])) k--;
        H[k++] = P[i + 2];
    }
    H[k++] = P[n - 2];
    for (i = n; i > 2; i--) {
