namespace asl
{
    template <typename numeric_type>
    using polygon = std::vector<point<numeric_type>>;

    template <typename numeric_type>
    polygon<numeric_type> convex_hull(std::vector<point<numeric_type>> cloud, bool allow_collinear = false, bool ccw = false)
    {
        int n = cloud.size(), k;
        std::vector<point<numeric_type>> ch(2 * n);

        sort(cloud.begin(), cloud.end());

        for (int i = k = 0; i < n; ch[k++] = cloud[i++])
            while (k > 1 && sign(cross(ch[k - 1] - ch[k - 2], cloud[i] - ch[k - 2])) >= int(allow_collinear))
                --k;

        for (int i = n - 2, t = k; i >= 0; ch[k++] = cloud[i--])
            while (k > t && sign(cross(ch[k - 1] - ch[k - 2], cloud[i] - ch[k - 2])) >= int(allow_collinear))
                --k;

        ch.resize(k - (k > 1));

        if (ccw)
        {
            std::reverse(ch.begin() + 1, ch.end());
        }

        return ch;
    }

    template <typename numeric_type>
    std::vector<int> arg_convex_hull(const std::vector<point<numeric_type>> &cloud, bool allow_collinear = false, bool ccw = false)
    {
        int n = cloud.size(), k;
        std::vector<int> ch(2 * n);

        std::vector<int> o(n);
        std::iota(o.begin(), o.end(), 0);
        std::sort(o.begin(), o.end(), [&](int u, int v) {
            return cloud[u] < cloud[v];
        });

        for (int i = k = 0; i < n; ch[k++] = o[i++])
            while (k > 1 && sign(cross(cloud[ch[k - 1]] - cloud[ch[k - 2]], cloud[o[i]] - cloud[ch[k - 2]])) >= int(allow_collinear))
                --k;

        for (int i = n - 2, t = k; i >= 0; ch[k++] = o[i--])
            while (k > t && sign(cross(cloud[ch[k - 1]] - cloud[ch[k - 2]], cloud[o[i]] - cloud[ch[k - 2]])) >= int(allow_collinear))
                --k;

        ch.resize(k - (k > 1));

        if (ccw)
        {
            std::reverse(ch.begin() + 1, ch.end());
        }

        return ch;
    }
} 

