struct Point {
    int x, y;

    Point() = default;
    Point(int x, int y) : x(x), y(y) {}

    Point operator+(const Point &rhs) const {
        return Point(x + rhs.x, y + rhs.y);
    }

    Point operator-(const Point &rhs) const {
        return Point(x - rhs.x, y - rhs.y);
    }

    long long operator*(const Point &rhs) const {
        return 1ll * x * rhs.x + 1ll * y * rhs.y;
    }

    long long operator%(const Point &rhs) const {
        return 1ll * x * rhs.y - 1ll * y * rhs.x;
    }

    bool operator<(const Point &rhs) const {
        return x == rhs.x ? y < rhs.y : x < rhs.x;
    }
};

vector<Point> convex(vector<Point> p) {
    sort(p.begin(), p.end());
    vector<Point> ch;
    int n = (int)p.size();
    for (int i = 0; i < n; ++i) {
        while (ch.size() >= 2 && (p[i] - ch[ch.size() - 2]) % (ch[ch.size() - 1] - ch[ch.size() - 2]) > 0) ch.pop_back();
        ch.push_back(p[i]);
    }
    int t = ch.size();
    for (int i = n - 2; i >= 0; --i) {
        while (ch.size() > t && (p[i] - ch[ch.size() - 2]) % (ch[ch.size() - 1] - ch[ch.size() - 2]) > 0) ch.pop_back();
        ch.push_back(p[i]);
    }
    ch.pop_back();
    // ch is of clock-wise order.
    return ch;
}

