    Point() : x(0), y(0) {}
    Point(double _x, double _y) : x(_x), y(_y) {}
};

inline bool operator < (const Point& P, const Point& Q)
{
    if (P.y < Q.y) {
        return true;
    } else if (P.y > Q.y) {
        return false;
    } else if(P.x < Q.x) {
        return true;
    } else {
        return false;
    }
}

istream& operator >> (istream& in, Point& P)
{
    in >> P.x >> P.y;
    return in;
}

ostream& operator << (ostream& out, const Point& P)
{
    out << P.x << " " << P.y;
    return out;
}

class Vector
{
public:
    double x, y;
    Vector() : x(0), y(0) {}
    Vector(const Point& Start, const Point& End) : x(End.x - Start.x), y(End.y - Start.y) {}
    inline double OuterProd(const Vector& V)
    {
        return x * V.y - y * V.x;
    }
    inline bool IsLeftTurn(const Vector& V)
    {
        return (*this).OuterProd(V) > eps;
    }
    inline bool IsRightTurn(const Vector& V)
    {
        return (*this).OuterProd(V) < -eps;
    }
};

void FindHalfHull(const vector<Point>& vP, vector<Point>& vRes)
{
    vRes.clear();
    size_t n = vP.size();
    Point Prev, Now, Next;
    Prev = vP[0];
    Now = vP[1];
    vRes.push_back(Prev);
    vRes.push_back(Now);
    Vector VecPrev(Prev, Now);
    Vector VecNow;
    for (int i = 2; i < n; ++i) {
        Next = vP[i];
        VecNow = Vector(Now, Next);
        if (!VecPrev.IsRightTurn(VecNow)) {
            vRes.push_back(Next);
        } else {
            while (VecPrev.IsRightTurn(VecNow) && vRes.size() >= 3) {
                vRes.pop_back();
                auto it = vRes.end();
                Now = *(--it);
                Prev = *(--it);
                VecNow = Vector(Now, Next);
                VecPrev = Vector(Prev, Now);
            }
            if (VecPrev.IsRightTurn(VecNow) && vRes.size() == 2) {
                vRes.pop_back();
                Now = vRes[0];
                VecNow = Vector(Now, Next);
            }
            vRes.push_back(Next);
        }
        Prev = Now;
        Now = Next;
        VecPrev = VecNow;
    }
    vRes.pop_back();
}

