  point& operator += (const point& P) {
    x += P.x;
    y += P.y;
    return *this;
  }

  point& operator -= (const point& P) {
    x -= P.x;
    y -= P.y;
    return *this;
  }

  point& operator *= (const T& k) {
    x *= k;
    y *= k;
    return *this;
  }

  point& operator /= (const T& k) {
    x /= k;
    y /= k;
    return *this;
  }

  point operator + (const point& P) const {
    return {x + P.x, y + P.y};
  }

  point operator - (const point& P) const {
    return {x - P.x, y - P.y};
  }

  point operator * (const T& k) const {
    return {x * k, y * k};
  }

  bool operator == (const point& P) const {
    return (x == P.x && y == P.y);
  }

  T norm() const {
    return dot(*this, *this);
  }

  auto length() const -> double {
    return sqrt(static_cast<double>(norm()));
  }

  static auto dot(const point& P, const point& Q) -> T {
    return P.x * Q.x + P.y * Q.y;
  }

  static auto cross(const point& P, const point& Q) -> T {
    return P.x * Q.y - P.y * Q.x;
  }

  static auto half_plane(const point& P) -> int const {
    if (P.y != 0) {
      return P.y < 0 ? -1 : +1;
    }
    return P.x < 0 ? -1 : +1;
  }

  static auto xy_comparator() {
    return [] (const point& P, const point& Q) {
      if (P.x != Q.x) {
        return P.x < Q.x;
      }
      return P.y < Q.y;
    };
  }

  static auto yx_comparator() {
    return [] (const point& P, const point& Q) {
      if (P.y != Q.y) {
        return P.y < Q.y;
      }
      return P.x < Q.x;
    };
  }

  static auto angle_comparator(const point& O) {
    return [O] (const point& P, const point& Q) {
      auto hP = half_plane(P);
      auto hQ = half_plane(Q);
      if (hP != hQ) {
        return hP < hQ;
      }
      auto c = sign(cross(P - O, Q - O));
      if (c != 0) {
        return (c > 0);
      }
      return sign(norm(P - O) - norm(Q - O)) == -1;
    };
  }
};

template <typename T>
std::vector<point<T>> convex_hull(std::vector<point<T>> pts) {
  sort(pts.begin(), pts.end(), point<T>::yx_comparator());

  std::vector<point<T>> hull(2 * pts.size());
  std::size_t size = 0;

  hull[size++] = pts[0];

  for (std::size_t step = 0; step < 2; step++) {
    auto prev_size = size;
    for (std::size_t i = 1; i < pts.size(); i++) {
      while (size > prev_size && point<T>::sign(point<T>::cross(pts[i] - hull[size - 2], hull[size - 1] - hull[size - 2])) < 0) {
        size--;
      }
      hull[size++] = pts[i];
    }
    std::reverse(pts.begin(), pts.end());
  }

  if (size > 1 && hull[0] == hull[size - 1]) {
    size--;
  }

  hull.resize(size);

  return hull;
}

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  std::cout.tie(nullptr);

  std::size_t n;
  std::cin >> n;

  std::vector<point<std::int32_t>> pts(n);
  for (auto& P: pts) {
    std::cin >> P;
  }

  auto hull = convex_hull(pts);

  std::cout << hull.size() << "\n";
  for (int i = 0; i < hull.size(); i++) {
    int j = (static_cast<int>(hull.size()) - i) % static_cast<int>(hull.size());
    std::cout << hull[j].x << " " << hull[j].y << "\n";
  }
}

