using namespace std;

struct P {
  int x, y;
  P() : x(0), y(0) { }
  P(int x, int y) : x(x), y(y) { }
};

bool operator < (const P& a, const P& b) {
  return a.x != b.x ? a.x < b.x : a.y < b.y;
}

P operator - (const P& a, const P& b) {
  return P(a.x - b.x, a.y - b.y);
}

int dot(const P& a, const P& b) {
  return a.x * b.x + a.y * b.y;
}

int cross(const P& a, const P& b) {
  return a.x * b.y - a.y * b.x;
}

int norm(const P& p) {
  return p.x * p.x + p.y * p.y;
}

int ccw(P a, P b, P c) {
  b = b - a; c = c - a;

  if(cross(b, c) > 0) return +1;
  if(cross(b, c) < 0) return -1;
  if(dot(b, c) < 0) return +2;
  if(norm(b) < norm(c)) return +2;

  return 0;
}

vector<P> convex_hull(vector<P> ps) {
  int n = ps.size(), k = 0;

  sort(ps.begin(), ps.end());

  vector<P> ch(2 * ps.size());

  for (int i = 0; i < n; ch[k++] = ps[i++]) // lower-hull
    while (k >= 2 && ccw(ch[k-2], ch[k-1], ps[i]) <= 0) --k;

  for (int i = n-2, t = k+1; i >= 0; ch[k++] = ps[i--]) // upper-hull
    while (k >= t && ccw(ch[k-2], ch[k-1], ps[i]) <= 0) --k;

  ch.resize(k-1);

  return ch;
}

int main() {
  int n;
  cin >> n;

  vector<P> points;

  for(int i = 0; i < n; i++) {
    int x, y;
    cin >> x >> y;

    points.push_back(P(x, y));
  }

  auto ch = convex_hull(points);

  auto i = min_element(ch.begin(), ch.end(), [](const P& a, const P& b) {
    return a.y != b.y ? a.y < b.y : a.x < b.x;
  }) - ch.begin();

  cout << ch.size() << endl;

  for(int j = 0; j < ch.size(); j++) {
    cout << ch[(i + j) % ch.size()].x << " " << ch[(i + j) % ch.size()].y << endl;
  }
}

