VP convex_hull(VP pol) {
    int n = pol.size(), k = 0, t = 1;

    auto cmp_x = [](P a, P b)->bool{
        int sr = sgn(real(a - b)), si = sgn(imag(a - b));
        return sr ? sr < 0 : si < 0;
    };

    sort(begin(pol), end(pol), cmp_x);
    VP res(2 * n);

