struct cmp_xy { bool operator()(const point& pi, const point& pj) { return pi.x < pj.x || (eq(pi.x, pj.x) && pi.y < pj.y); } };



//****************************************
// 関数の定義
//****************************************

polygon_t andrew_scan(polygon_t& P, bool degenerate)
{
    index_t n = P.size(), k = 0;

    // 与えられた点の中からすべての点を左から右に順序付けする
    std::sort(P.begin(), P.end(), cmp_xy());  // NOTE: xが等しい場合、yの昇順とする

    // 上側チェーンと下側チェーンを構成する(それぞれ凸包の上半分と下半分に相当する)
    polygon_t L(2 * n);  // NOTE: Pの点を1点ずつ加えながら解を更新する

    // 縮退を考慮するか否かを決定する述語を設定する
    auto pred = degenerate
        ? std::function<bool(index_t, index_t)>([&](index_t i, index_t k) -> bool { return ccw(L[k - 2], L[k - 1], P[i]) != orientation::ccw; })
        : std::function<bool(index_t, index_t)>([&](index_t i, index_t k) -> bool { return ccw(L[k - 2], L[k - 1], P[i]) == orientation::cw;  });


    // まず、凸包上の点の中で上部凸包(upper hull)上にあるものだけ求める
    for (index_t i = 0; i < n; i++) {
        while (k >= 2 && pred(i, k)) { k = k - 1; }
        L[k] = P[i]; k = k + 1;
    }

    // 右から左へと実行される2番目の走査で、凸包の残りの部分、すなわち下部凸包(lower hull)を計算する
    for (index_t i = n - 2, t = k + 1; i >= 0; i--) {
        while (k >= t && pred(i, k)) { k = k - 1; }
        L[k] = P[i]; k = k + 1;
    }

    L.resize(k - 1);  // CH(P)の頂点を時計回りの順に並べたリストL
    return L;         // リストLを返す
}



