// 線分s1と線分s2の距離
//verify
double getDistance(Segment s1, Segment s2) {
    if (intersect(s1, s2)) return 0.0;
    return min(min(getDistanceSP(s1, s2.p1), getDistanceSP(s1, s2.p2)), min(getDistanceSP(s2, s1.p1), getDistanceSP(s2, s1.p2)));
}

// 線分の交点
// verify
Point getCrossPoint(Segment s1, Segment s2) {
    Vector base = s2.p2 - s2.p1;
    double d1 = abs(cross(base, s1.p1 - s2.p1));
    double d2 = abs(cross(base, s1.p2 - s2.p1));
    double t = d1 / (d1 + d2);
    return s1.p1 + (s1.p2 - s1.p1) * t;
}


// 円cと線分lの交点
//verify
pair<Point, Point> getCrossPoints(Circle c, Line l) {
    //assert(intersect(c, l)); ?
    Vector pr = project(l, c.c);
    Vector e = (l.p2 - l.p1) / (l.p2 - l.p1).abs();
    double base = sqrt(c.r * c.r - (pr - c.c).norm());
    return make_pair(pr + e * base, pr - e * base);
}

// 円と円の交点
double arg(Vector p) { return atan2(p.y, p.x); }
Vector polar(double a, double r) { return Point(cos(r) * a, sin(r) * a); }

// verify
pair<Point, Point> getCrossPoints(Circle c1, Circle c2) {
    // assert(intersect(c1, c2));
    double d = (c1.c - c2.c).abs();
    double a = acos((c1.r * c1.r + d * d - c2.r * c2.r) / (2  * c1.r * d));
    double t = arg(c2.c - c1.c);
    return make_pair(c1.c + polar(c1.r, t + a), c1.c + polar(c1.r, t-a));
}

// 点の内包
// IN 2, ON 1, OUT 0
// verify
int contains(Polygon g, Point p) {
    int n = g.size();
    bool x = false;
    for (int i = 0; i < n; ++i) {
        Point a = g[i] - p, b = g[(i + 1) % n] - p;
        if (abs(cross(a, b)) < eps and dot(a, b) < eps) return 1;
        if (a.y > b.y) swap(a, b);
        if (a.y < eps and eps < b.y and cross(a, b) > eps) x = !x;
    }
    return (x ? 2 : 0);
}

// 凸包
Polygon andrewScan(Polygon s) {
    Polygon u, l;
    if (s.size() < 3) return s;
    sort(s.begin(), s.end());
    u.push_back(s[0]);
    u.push_back(s[1]);
    l.push_back(s[s.size()-1]);
    l.push_back(s[s.size()-2]);

    for (int i = 2; i < s.size(); ++i) {
        for (int n = u.size(); n >= 2 and ccw(u[n-2], u[n-1], s[i]) == COUNTER_CLOCKWISE; --n) {
            u.pop_back();
        }
        u.push_back(s[i]);
    }

    for (int i = s.size()-3; i>=0; --i) {
        for (int n = l.size(); n>=2 and ccw(l[n-2], l[n-1], s[i]) == COUNTER_CLOCKWISE; --n) {
            l.pop_back();
        }
        l.push_back(s[i]);
    }

    reverse(l.begin(), l.end());
    for (int i = u.size() - 2; i >= 1; --i) l.push_back(u[i]);
    return l;
}

// 平面走査
#define BOTTOM 0
#define LEFT 1
#define RIGHT 2
#define TOP 3

class EndPoint {
public:
    Point p;
    int seg, st;
    EndPoint() {}
    EndPoint(Point p, int seg, int st) : p(p), seg(seg), st(st) {}

    bool operator<(const EndPoint &ep) const {
        if (p.y == ep.p.y) {
            return st < ep.st;
        }else return p.y < ep.p.y;
    }
};

EndPoint EP[2 * 100000];

int manhattanIntersection(vector<Segment> S) {
    int n = S.size();

    for (int i = 0, k = 0; i < n; ++i) {
        if (S[i].p1.y == S[i].p2.y) {
            if (S[i].p1.x > S[i].p2.x) swap(S[i].p1, S[i].p2);
        } else if (S[i].p1.y > S[i].p2.y) swap(S[i].p1, S[i].p2);

        if (S[i].p1.y == S[i].p2.y) {
            EP[k++] = EndPoint(S[i].p1, i, LEFT);
            EP[k++] = EndPoint(S[i].p2, i, RIGHT);
        }
        else {
            EP[k++] = EndPoint(S[i].p1, i, BOTTOM);
            EP[k++] = EndPoint(S[i].p2, i, TOP);
        }
    }

    sort(EP, EP + (2 * n));

    set<int> BT;
    BT.insert(100000001); // 番兵
    int cnt = 0;

    for (int i = 0; i < 2 * n; ++i) {
        if (EP[i].st == TOP) {
            BT.erase(EP[i].p.x);
        }
        else if (EP[i].st == BOTTOM) {
            BT.insert(EP[i].p.x);
        }
        else if (EP[i].st == LEFT) {
            auto b = lower_bound(BT.begin(), BT.end(), S[EP[i].seg].p1.x);
            auto e = upper_bound(BT.begin(), BT.end(), S[EP[i].seg].p2.x);
            cnt += distance(b, e);
        }
    }

    return cnt;

}

