    Polygon g;

    rep(i, n) {
        int x, y;
        cin >> x >> y;
        Point a(x, y);
        g.push_back(a);
    }

    Polygon ret = andrewScan(g);
    cout << ret.size() << endl;

    int p = 0;
    double a= 1e9, b = 1e9;
    rep(i, ret.size()) {
        if (ret[i].y < b) {
            a = ret[i].x;
            b = ret[i].y;
            p = i;
        }
        else if (ret[i].y == b and ret[i].x < a) {
            a = ret[i].x;
            p = i;
        }
    }

    rep(i, ret.size()) {
        cout << ret[(p+i)%ret.size()].x << " " << ret[(p+i)%ret.size()].y << endl;
    }
}

