struct Point
{
    int x,y;
    Point() {}
    Point(int _x,int _y):x(_x),y(_y) {}
    Point operator -(Point p)
    {
        return Point(x-p.x,y-p.y);
    }
    bool operator <(Point p)
    {
        return x==p.x?y<p.y:x<p.x;
    }
    int cross(Point p)
    {
        return x*p.y-y*p.x;
    }
    int dot(Point p)
    {
        return x*p.x+y*p.y;
    }
    int norm()
    {
        return x*x+y*y;
    }

};
vector<Point> ps;
bool cmp(Point A,Point B)
{
    if(A.y!=B.y) return A.y<B.y;
    return A.x<B.x;
}
int ccw(Point p,Point p1,Point p2)
{
    #define CLOCKWISE -1
    #define COUNT_CLOCKWISE 1
    #define ON_SEGMENT 0
    #define ONLINE_BACK 2
    #define ONLINE_FRONT -2
    Point a=p1-p;
    Point b=p2-p;
    if(a.cross(b)<-EPS) return CLOCKWISE;
    if(a.cross(b)>EPS) return COUNT_CLOCKWISE;
    if(a.dot(b)<-EPS) return ONLINE_BACK;
    if(a.norm()<b.norm()) return ONLINE_FRONT;
    return ON_SEGMENT;
}
vector<Point> convex_hull(vector<Point> ps,int n)
{
    vector<Point> qs;
    if(ps.size()<3) return ps;
    sort(ps.begin(),ps.end());


    for(int i=0;i<ps.size();i++)
    {
        for(int n=qs.size();n>=2&&ccw(qs[n-2],qs[n-1],ps[i])>0;n--) qs.pop_back();
        qs.push_back(ps[i]);
    }

    for(int i=ps.size()-2;i>=0;i--)
    {
        for(int n=qs.size();n>=2&&ccw(qs[n-2],qs[n-1],ps[i])>0;n--) qs.pop_back();
        qs.push_back(ps[i]);
    }
    reverse(qs.begin(),qs.end());
    qs.pop_back();
    return qs;



}
