		vec.push_back(Point(a, b));
	}
	Polygon ans = convex_hull(vec);
	cout << ans.size() << endl;
	for(int i=0;i<(int)ans.size();i++){
		cout << ans[i].real() << ' ' << ans[i].imag() << endl;
	}
}

