inline bool direct(Point& base, Point& a, Point& b) {
    return (a.x - base.x)*(b.y - base.y) - (a.y - base.y)*(b.x - base.x) < 0;
}

inline void swap(Point* a, Point* b) {
    Point p;
    p = *a;
    *a = *b;
    *b = p;
}

