    typedef vector<P> Poly,ConvexPoly;

    //O(nlogn)
    ConvexPoly convex_hull(Poly ps) {
        int n = ps.size(), k = 0;
        sort(ALL(ps));
        Poly ch(2*n);
        REP(i,n){ // lower-hull
            while (k > 1 && cross(ch[k-1]-ch[k-2],ps[i]-ch[k-1]) < 0) --k;
            ch[k++]=ps[i];
        }
        for(int i=n-2,t=k;i>=0;i--){// upper-hull
            while (k > t && cross(ch[k-1]-ch[k-2],ps[i]-ch[k-1]) < 0) --k;
            ch[k++]=ps[i];
        }
        ch.resize(k-1);
        return ch;
    }

    //O(nlogn)
    void ccw_sort(ConvexPoly &ps){
        const int n=ps.size();
        sort(ALL(ps));
        const P& O = ps[0];
        sort(ps.begin()+1,ps.end(),[n,&O,&ps](const P&l,const P&r) -> bool{
            int cr=cross(l-O,r-O);
            if(cr!=0)return cr > 0;
            if(cross(r-O,ps[1]-O)==0 && cross(l-O,ps[1]-O)==0) return abs(l-O)<abs(r-O);
            if(cross(r-O,ps[n-1]-O)==0 && cross(l-O,ps[n-1]-O)==0) return abs(l-O)>abs(r-O);
            assert(false);
        });

