double dot(Point a, Point b){
    return a.x * b.x + a.y * b.y;
}
double cross(Point a, Point b){
    return a.x * b.y - a.y * b.x;
}
bool isOrthogonal(Point a, Point b){
    return equals(dot(a, b), 0.0);
}
bool isParallel(Point a, Point b){
    return equals(cross(a, b), 0.0);
}
bool isOrthogonal(Segment s1, Segment s2){
    return equals(dot(s1.p2 - s1.p1, s2.p2 - s1.p1), 0.0);
}
bool isParallel(Segment s1, Segment s2){
    return equals(cross(s1.p2 - s1.p1, s2.p2 - s1.p1), 0.0);
}

Point project(Segment s, Point p){
    Vector base = s.p2 - s.p1;
    double r = dot(p - s.p1, base) / base.norm();
    //Vector tmp = s.p1 + base * r;
    Vector tmp = base * r;
    return s.p1 + base * r;
}

Point reflect(Segment s, Point p){
    return p + (project(s, p) - p) * 2;
}

int ccw(Point p1, Point p2, Point p3){
    Vector a = p2 - p1;
    Vector b = p3 - p1;
    if( cross(a, b) > EPS ) return 1;
    else if( cross(a, b) < -EPS ) return -1;
    else if( dot(a, b) < -EPS ) return 2;
    else if( a.norm() < b.norm() ) return -2;
    //std::cout << std::fixed << std::setprecision(10) << ans.x << " " << ans.y << std::endl;
    else return 0;
}

bool intersect(Point p1, Point p2, Point p3, Point p4){
    return(ccw(p1, p2, p3) * ccw(p1, p2, p4) <= 0 && ccw(p3, p4, p1) * ccw(p3, p4, p2) <= 0);
}

bool intersect(Segment s1, Segment s2){
    return intersect(s1.p1, s1.p2, s2.p1, s2.p2);
}



double getDistance(Point a, Point b){
    return (a - b).abs();
}

double getDistanceLP(Line l, Point p){    
    return abs(cross(l.p2 - l.p1, p - l.p1)) / (l.p2 - l.p1).abs();
}

double getDistanceSP(Segment s, Point p){
    if(dot(s.p2 - s.p1, p - s.p1) < 0.0) return (p - s.p1).abs();
    if(dot(s.p1 - s.p2, p - s.p2) < 0.0) return (p - s.p2).abs();
    return getDistanceLP(s, p);
}

double getDistance(Segment s1, Segment s2){
    if( intersect(s1, s2) ) return 0.0;
    return std::min(std::min(getDistanceSP(s1, s2.p1), getDistanceSP(s1, s2.p2)), std::min(getDistanceSP(s2, s1.p1), getDistanceSP(s2, s1.p2)));
}

Point getCrossPoint(Segment s1, Segment s2){
    Vector base = s2.p2 - s2.p1;
    double d1 = abs(cross(base, s1.p1 - s2.p1));
    double d2 = abs(cross(base, s1.p2 - s2.p1));
    double t = d1 / (d1 + d2);
    return s1.p1 + (s1.p2 - s1.p1) * t;
}

std::pair<Point, Point> getCrossPoints(Circle c, Line l){
    //assert(intersect(c, l));
    Vector pr = project(l, c.c);
    Vector e = (l.p2 - l.p1) / (l.p2 - l.p1).abs();
    double base = sqrt(c.r * c.r - (pr - c.c).norm());
    return std::make_pair(pr + e * base, pr - e * base);

}

double arg(Vector p){
    return atan2(p.y, p.x);
}

Vector polar(double a, double r){
    return Point(cos(r) * a, sin(r) * a);
}

std::pair<Point, Point> getCrossPoints(Circle c1, Circle c2){
    double d = (c1.c - c2.c).abs();
    double a = acos((c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d));
    double t = arg(c2.c - c1.c);
    return std::make_pair(c1.c + polar(c1.r, t+ a), c1.c + polar(c1.r, t-a));

}

int contains(Polygon g, Point p){
    int n = g.size();
    bool x = false;
    for(int i = 0; i < n; i++){
        Point a = g[i] - p, b = g[(i+1) % n] - p;
        if( abs(cross(a, b) ) < EPS && dot(a, b) < EPS ) return 1;
        if( a.y > b.y ) std::swap(a, b);
        if( a.y < EPS && EPS < b.y && cross(a, b) > EPS) x = !x;
    }
    return( x ? 2 : 0);

}

Polygon andrewScan( Polygon s){
    Polygon u, l;

    std::sort(s.begin(), s.end());
    u.push_back(s[0]);
    u.push_back(s[1]);

    l.push_back(s[s.size() - 1]);
    l.push_back(s[ s.size() - 2 ]);

    for ( int i = 2; i < s.size(); i++ ) {
        for ( int n = u.size(); n >=2 && ccw(u[n-2], u[n-1], s[i]) > 0; n--){
            u.pop_back();
        }
        u.push_back(s[i]);
    }


    for ( int i = s.size() - 3; i >= 0; i-- ) {
        for ( int n = l.size(); n >=2 && ccw(l[n-2], l[n-1], s[i]) > 0; n--){
            l.pop_back();
        }
        l.push_back(s[i]);
    }

    std::reverse(l.begin(), l.end());

    for ( int i = u.size() - 2; i >= 1; i-- ){
        l.push_back( u[i] );
    }

    return l;


}

