	double a = acos((c1.r * c1.r + d * d - c2.r * c2.r) / (2.0 * c1.r * d));
	double t = arg(c2.c - c1.c);
	return mp(c1.c + polar(c1.r, t + a), c1.c + polar(c1.r, t - a));
}
int contains(Polygon g, Point p) {
	int n = len(g);
	bool x = false;
	Point a, b;
	rep(i, 0, n) {
		a = g[i] - p;
		b = g[(i + 1) % n] - p;
		if(abs(cross(a, b)) < EPS && dot(a, b) < EPS) return 1;
		if(a.imag() > b.imag()) swap(a, b);
		if(a.imag() < EPS && EPS < b.imag() && cross(a, b) > EPS) x = !x;
	}
	return (x ? 2 : 0);
}
Polygon andrewScan(Polygon s) {
	if(len(s) < 3) return s;
	Polygon u, l;
	sort(all(s), [](const Point& a, const Point& b){return a.imag() == b.imag() ? a.real() < b.real() : a.imag() < b.imag();});
	u.eb(s[0]);
	u.eb(s[1]);
	l.eb(s[len(s) - 1]);
	l.eb(s[len(s) - 2]);
	int _ccw;
	rep(i, 2, len(s)) {
		rrep(n, len(u), 1) {
			_ccw = ccw(u[n - 2], u[n - 1], s[i]);
			if(!(_ccw != CLOCKWISE && _ccw != ONLINE_FRONT)) break;
			u.pop_back();
		}
		u.eb(s[i]);
	}
	rrep(i, len(s) - 3, -1) {
		rrep(n, len(l), 1) {
			_ccw = ccw(l[n - 2], l[n - 1], s[i]);
			if(!(_ccw != CLOCKWISE && _ccw != ONLINE_FRONT)) break;
			l.pop_back();
		}
		l.eb(s[i]);
	}
	reverse(all(l));
	rrep(i, len(u) - 2, 0) l.eb(u[i]);
	return l;
}
