int sign(let x) { return (x < -EPS) ? -1 : (x > EPS ? 1 : 0); }

struct Point {
  let x, y;

  friend Point operator + (Point a, Point b) {
    return (Point) {a.x + b.x, a.y + b.y};
  }

  friend Point operator - (Point a, Point b)  {
    return (Point) {a.x - b.x, a.y - b.y};
  }

  Point operator ~ () { return (Point) {x, -y}; }

  friend int sTimes(Point a, Point b) {
    return sign(Times(a, b));
  }

  friend let Times(Point a, Point b) {
    return a.x * b.y - a.y * b.x;
  }

  Point Rotate(let sink, let cosk) {
    return (Point) {
      x * cosk - y * sink, x * sink + y * cosk
    };
  }

  let dist() {
    return sqrt(x * x + y * y);
  }

};

bool CampByYX(Point a, Point b) {
  if (sign(a.y - b.y) == 0) return sign(a.x - b.x) < 0;
  return sign(a.y - b.y) < 0;
}

typedef Point Vec;

struct Polygon {
  vector<Point> p;

  Point &operator [](int k) { return p.at(k); }
  void push(Point pt) { p.push_back(pt); }
  int size() { return p.size(); }
  void pop() { p.pop_back(); }

  void Rotate(let sink, let cosk) {
    for (size_t i = 0; i < p.size(); ++i)
      p[i] = p[i].Rotate(sink, cosk);
  }

  void Rotate(let k) {
    return Rotate(sin(k), cos(k));
  }

  void Rotate(Vec v) {
    let z = v.dist();
    return Rotate(v.y / z, v.x / z);
  }

  friend Polygon GetConvexHull(Polygon poly) {

    sort(poly.p.begin(), poly.p.end(), CampByYX);

    let angle = ((let) rand() / RAND_MAX) * Pi;
    poly.Rotate(angle);
    Polygon res;

    int cnt = -1;
    for (int i = 0; i < poly.size(); ++i) {
      while (cnt > 0 && sTimes(res[cnt] - res[cnt - 1], poly[i] - res[cnt]) < 0)
        res.pop(), cnt--;
      res.push(poly[i]);
      cnt++;
    }

    int downhull_cnt = cnt;

    for (int i = poly.size() - 2; i >= 0; --i) {
      while (cnt > downhull_cnt && 
          sTimes(res[cnt] - res[cnt - 1], poly[i] - res[cnt]) < 0)
        res.pop(), cnt--;
      res.push(poly[i]);
      cnt++;
    }

    res.pop();
    res.Rotate(-angle);

    return res;
  }

  void Echo() {
    printf("%d\n", size());
    for (int i = 0; i < size(); ++i) {
      if (sign(p[i].x) == 0) p[i].x = 0;
      if (sign(p[i].y) == 0) p[i].y = 0;
      printf("%.0Lf %.0Lf\n", p[i].x, p[i].y);
    }
  }
};

