vector<Point> convex_hull(vector<Point>& P, long n)
{
    long k = 1;
    vector<Point> H;
    H.push_back(P[0]);
    H.push_back(P[1]);
    for (long i = 0; i < n - 2; i++) {
        while (k >= 1 && (H[k].x - H[k - 1].x) * (P[i + 2].y - H[k - 1].y) - (H[k].y - H[k - 1].y) * (P[i + 2].x - H[k - 1].x) < 0) {
            H.pop_back();
            k--;
        }
        H.push_back(P[i + 2]);
        k++;
    }
    H.push_back(P[n - 2]);
    for (long i = n; i > 2; i--) {
        while ((H[k + 1].x - H[k].x) * (P[i - 3].y - H[k].y) - (H[k + 1].y - H[k].y) * (P[i - 3].x - H[k].x) < 0) {
            H.pop_back();
            k--;
        }
        H.push_back(P[i - 3]);
        k++;
    }
    H.pop_back();
    return H;
}

