	return abs(cross(l.p2 - l.p1, p - l.p1) / (l.p2 - l.p1).abs());
}
double getDistanceSP(Segment &s, Point &p) {
	if(dot(s.p2 - s.p1, p - s.p1) < 0.0) return (p - s.p1).abs();
	if(dot(s.p1 - s.p2, p - s.p2) < 0.0) return (p - s.p2).abs();
	return getDistanceLP(s, p);
}
double getDistance(Segment &s1, Segment &s2) {
	if(intersect(s1, s2)) return 0.0;
	return min(min(getDistanceSP(s1, s2.p1), getDistanceSP(s1, s2.p2)),
				min(getDistanceSP(s2, s1.p1), getDistanceSP(s2, s1.p2)));
}
Point getCrossPoint(Segment s1, Segment s2) {
	Vector base = s2.p2 - s2.p1;
	double d1 = abs(cross(base, s1.p1 - s2.p1));
	double d2 = abs(cross(base, s1.p2 - s2.p1));
	double t = d1 / (d1 + d2);
	return s1.p1 + (s1.p2 - s1.p1) * t;
}
double arg(Vector p) { return atan2(p.y, p.x); }
Vector polar(double a, double r) { return Point(cos(r) * a, sin(r) * a); }
pair<Point, Point> getCrossPoints(Circle c, Line l) {
	Vector pr = project(l, c.c);
	Vector e = (l.p2 - l.p1) / (l.p2 - l.p1).abs();
	double base = sqrt(c.r * c.r - (pr - c.c).norm());
	return mp(pr + e * base, pr - e * base);
}
pair<Point, Point> getCrossPoints(Circle c1, Circle c2) {
	double d = (c1.c - c2.c).abs();
	double a = acos((c1.r * c1.r + d * d - c2.r * c2.r) / (2.0 * c1.r * d));
	double t = arg(c2.c - c1.c);
	return mp(c1.c + polar(c1.r, t + a), c1.c + polar(c1.r, t - a));
}
int contains(Polygon g, Point p) {
	int n = len(g);
	bool x = false;
	Point a, b;
	rep(i, 0, n) {
		a = g[i] - p;
		b = g[(i + 1) % n] - p;
		if(abs(cross(a, b)) < EPS && dot(a, b) < EPS) return 1;
		if(a.y > b.y) swap(a, b);
		if(a.y < EPS && EPS < b.y && cross(a, b) > EPS) x = !x;
	}
	return (x ? 2 : 0);
}
Polygon andrewScan(Polygon s) {
	if(len(s) < 3) return s;
	Polygon u, l;
	sort(all(s), [](const Point& a, const Point& b){return a.y == b.y ? a.x < b.x : a.y < b.y;});
	u.eb(s[0]);
	u.eb(s[1]);
	l.eb(s[len(s) - 1]);
	l.eb(s[len(s) - 2]);
	int _ccw;
	rep(i, 2, len(s)) {
		rrep(n, len(u), 1) {
			_ccw = ccw(u[n - 2], u[n - 1], s[i]);
			if(!(_ccw != CLOCKWISE && _ccw != ONLINE_FRONT)) break;
			u.pop_back();
		}
		u.eb(s[i]);
	}
	rrep(i, len(s) - 3, -1) {
		rrep(n, len(l), 1) {
			_ccw = ccw(l[n - 2], l[n - 1], s[i]);
			if(!(_ccw != CLOCKWISE && _ccw != ONLINE_FRONT)) break;
			l.pop_back();
		}
		l.eb(s[i]);
	}
	reverse(all(l));
	rrep(i, len(u) - 2, 0) l.eb(u[i]);
	return l;
}
int main() {
	cout << setprecision(10) << fixed;
	int n; cin >> n;
	Polygon pg(n);
	rep(i, 0, n) {
		cin >> pg[i].x >> pg[i].y;
	}
	Polygon ans = andrewScan(pg);
	P(len(ans));
	rep(i, 0, len(ans)) {
		cout << int(ans[i].x) << " " << int(ans[i].y) << "\n";
	}
	return 0;
}

