    //O(n logn)
    ConvexPoly convex_hull(Poly ps) {
        int n = ps.size(), k = 0;
        sort(ALL(ps));
        Poly ch(2*n);
        REP(i,n){ // lower-hull
            while (k > 1 && cross(ch[k-1]-ch[k-2],ps[i]-ch[k-1]) < 0) --k;
            ch[k++]=ps[i];
        }
        for(int i=n-2,t=k;i>=0;i--){// upper-hull
            while (k > t && cross(ch[k-1]-ch[k-2],ps[i]-ch[k-1]) < 0) --k;
            ch[k++]=ps[i];
        }
        ch.resize(k-1);
        return ch;
    }
    void ccw_sort(ConvexPoly &ps){
        sort(ALL(ps));
        P r=ps[ps.size()-1];
        sort(ps.begin()+1,ps.end(),[&ps](const P& l,const P& r) -> bool{
            int cr=cross(l-ps[0],r-ps[0]);
            if(cr==0)return abs(l-ps[0])>abs(r-ps[0]);
            return cr>0;
        });
        int ri=-1;REP(i,ps.size())if(eq(ps[i],r))ri=i;
        sort(ps.begin(),ps.begin()+ri,[ri,&ps](const P& l,const P& r) -> bool{
            int cr=cross(l-ps[0],r-ps[0]);
            if(cr==0)return abs(l-ps[0])<abs(r-ps[0]);
            return cr>0;
        });

    }
}
