bool isConvex(Polygon s) {
  int n = s.size();
  int a;
  for (int i = 0; i < n; i++) {
    a = ccw(s[i], s[(i+1)%n], s[(i+2)%n]);
    if (abs(a) == 1) break;
  }
  for (int i = 0; i < n; i++) {
    int b = ccw(s[i], s[(i+1)%n], s[(i+2)%n]);
    if (a*b < 0 && abs(b) == 1) {
      return false;
    }
  }
  return true;
}

