    else if(!dcmp(v ^ w) && sqr(v) > sqr(w))    return false;
    return true;
}
void graham()
{
    sort(p + 1, p + n, cmp);
    n = unique(p, p + n) - p;
    int t = n - 1;
    while(!dcmp((p[t] - p[0]) ^ (p[n-1] - p[0])))   t --;
    reverse(p + t + 1, p + n);
    sta[0] = p[0], sta[1] = p[1], top = 2;
    p[n ++] = p[0];
    for(int i = 2; i < n; i ++)
    {
        while(top >1 && dcmp((sta[top - 1] - sta[top - 2]) ^ (p[i] - sta[top - 2])) < 0)  top --;
        sta[top ++] = p[i];
    }
    top --;
}
