typedef long double ldb;
typedef complex<ldb> P;
struct L {
  P a,b;
  L(){}
  L(P a,P b):a(a),b(b){}
  ldb len(){return abs(a-b);}
  P vec(){return b-a;}
};

const ldb eps = 1e-8;
const ldb pi = acos(-1);
int sig(ldb a) {return (a<-eps)?-1:(a>eps)?1:0;}
bool eq(ldb a,ldb b){return abs(a-b)<eps;}
ldb dot(P a, P b) {
  return (a.real() * b.real() + a.imag() * b.imag());
}
ldb cross(P a, P b) {
  return (a.real() * b.imag() - a.imag() * b.real());
}
enum CCW{FRONT = 1, RIGHT = 2, BACK = 4, LEFT = 8, ON = 16};
int ccw(L s, P p) {
  P a = s.vec();
  p -= s.a;
  ldb cr = cross(a, p);
  if (eq(cr, 0)) {
    if (sig(dot(a, p)) < 0) return BACK;
    if (sig(norm(a) - norm(p)) < 0) return FRONT;
    return ON;
  }
  return (cr > 0) ? LEFT : RIGHT;
}

bool cmp(const P& a,const P& b)
{
  if( eq(a.real(),b.real()) ) return a.imag()<b.imag();
  return a.real()<b.real();
}

vector<P> convex_hull(vector<P> p)
{
  if( p.size() <= 1 ) return p;
  sort(p.begin(),p.end(),cmp);
  int k = 0;
  int n = p.size();
  vector<P> ret(n*2);
  //sitagawa
  for( int i = 0; i < n; i++ ) {
    while( k > 1 && ccw(L(ret[k-2],p[i]),ret[k-1])==LEFT ) k--;
    ret[k++] = p[i];
  }
  int t = k;
  //uegawa
  for( int i = n-2; i >= 0; i-- ) {
    while( k > t && ccw(L(ret[k-2],p[i]),ret[k-1])==LEFT ) k--;
    ret[k++] = p[i];
  }
  ret.resize(k-1);
  return ret;
}

