namespace std{
  template<class T> bool operator<(const complex<T> &a, const complex<T> &b){
    return a.real() == b.real() ? a.imag() < b.imag() : a.real() < b.real();
  }
};

P rotate(P p, double theta){
  return p * P(cos(theta), sin(theta));
}

//内積
double dot(P a, P b) {
  return (a * conj(b)).real();
}

//外積
double cross(P a, P b) {
  return (conj(a) * b).imag();
}

//反時計回り
int ccw(P a, P b, P c){
  if(cross(b-a,c-a) > 0) return 1; //COUNTER_CLOCKWISE
  if(cross(b-a,c-a) < 0) return -1; //CLOCKWISE
  if(dot(b-a,c-a) < 0) return -2; //ONLINE_BACK
  if(dot(a-b,c-b) < 0) return 2; //ONLINE_FRONT
  return 0; //ON_SEGMENT
}

/* ConvexHull(凸包) */

vector<P> ConvexHull(vector<P> s){
  vector<P> g;
  int n = (int)s.size();

  if(n<3) return s;

  sort(s.begin(),s.end());

  for(int i=0;i<n;i++){
    for(int m = (int)g.size();m>=2 && ccw(g[m-2],g[m-1],s[i]) == 1; m--){
      g.pop_back();
    }
    g.push_back(s[i]);
  }

  int t = (int)g.size();

  for(int i=n-2;i>=0;i--){
    for(int m = (int)g.size();m>t && ccw(g[m-2],g[m-1],s[i]) == 1; m--){
      g.pop_back();
    }
    g.push_back(s[i]);
  }

  reverse(g.begin(),g.end());
  g.pop_back();

  return g;
}


int main(){
  int n;
  vector<P> vec;

  scanf("%d",&n);

  for(int i=0;i<n;i++){
    int x, y;
    scanf("%d%d",&x,&y);
    vec.push_back(P(x,y));
  }

  auto res = ConvexHull(vec);

  printf("%d\n",(int)res.size());

  int start = 0;

  for(int i=1;i<(int)res.size();i++){
    if(res[i] < res[start]){
      start = i;
    }
  }

  for(int i=0;i<res.size();i++){
    printf("%d %d\n",(int)res[(start+i)%vec.size()].real(), (int)res[(start+i)%vec.size()].imag());
  }

  return 0;
}

