using namespace std;

typedef complex<double> C;

namespace std {
  bool operator < (const C& a, const C& b) {
    return real(a) != real(b) ? real(a) < real(b) : imag(a) < imag(b);
  }
}
//??????
double cross(const C& a, const C& b) {
  return imag(conj(a)*b);
}
//??????
double dot(const C& a, const C& b) {
  return real(conj(a)*b);
}

int ccw(C a, C b, C c) {
  b -= a; c -= a;
  if (cross(b, c) > 0)   return +1;       // counter clockwise
  if (cross(b, c) < 0)   return -1;       // clockwise
  if (dot(b, c) < 0)     return +2;       // c--a--b on line
  if (norm(b) < norm(c)) return -2;       // a--b--c on line
  return 0;
}

vector<C> convex_hull(vector<C> ps) {
  int n = ps.size(), k = 0;
  sort(ps.begin(), ps.end());
  vector<C> ch(2*n);
  for (int i = 0; i < n; ch[k++] = ps[i++]) // lower-hull
    while (k >= 2 && (ccw(ch[k-2], ch[k-1], ps[i]) == 0 || ccw(ch[k-2], ch[k-1], ps[i]) == -1)) --k;
  for (int i = n-2, t = k+1; i >= 0; ch[k++] = ps[i--]) // upper-hull
    while (k >= t && (ccw(ch[k-2], ch[k-1], ps[i]) == 0 || ccw(ch[k-2], ch[k-1], ps[i]) == -1)) --k;
  ch.resize(k-1);
  return ch;
}

