        vec.push_back(C(x,y));
    }
    res = convex_hull(vec);
    rep(i,res.size()){
        mp[res[i]] = i;
    }
    bf = res;
    sort(bf.begin(),bf.end(),[](C c1,C c2){return imag(c1) == imag(c2)?real(c1) < real(c2):imag(c1) < imag(c2);});
    int st = mp[bf[0]];
    cout << res.size() << "\n";
