bool asc(const complex<int>& a, const complex<int>& b) {
  if(a.real() != b.real()) return a.real() < b.real();
  else return a.imag() < b.imag();
}

int cross_product(complex<int> a, complex<int> b) {
  return (conj(a)*b).imag();
}

int main() {
  int n, x, y, size;
  cin >> n;
  vector<complex<int> > vertex(n), ans_under, ans_above;
  for(int i = 0; i < n; i++) {
    cin >> x >> y;
    vertex[i] = complex<int>(x, y);
  }
  sort(vertex.begin(), vertex.end(), asc);
  int i = 0;
  while(i < n) {
    size = ans_under.size();
    if(size < 2) {
      ans_under.push_back(vertex[i]);
      i++;
    }
    else {
      int t = cross_product(vertex[i]-ans_under[size-1], ans_under[size-2]-ans_under[size-1]);
      if(t >= 0) {
	ans_under.push_back(vertex[i]);
	i++;
      }
      else {
	ans_under.pop_back();
      }
    }
  }
  i = n-1;
  while(i >= 0) {
    size = ans_above.size();
    if(size < 2) {
      ans_above.push_back(vertex[i]);
      i--;
    }
    else {
      int t = cross_product(vertex[i]-ans_above[size-1], ans_above[size-2]-ans_above[size-1]);
      if(t >= 0) {
	ans_above.push_back(vertex[i]);
	i--;
      }
      else
	ans_above.pop_back();
    }
  }
  int minIndex = 0;
  for(int j = 1; j < ans_under.size(); j++) {
    if(ans_under[minIndex].imag() > ans_under[j].imag()) {
      minIndex = j;
    }
