    cout << ans_under.size()+ans_above.size()-2 << endl;
    for(int j = minIndex; j < ans_under.size(); j++) {
      cout << ans_under[j].real() << " " << ans_under[j].imag() << endl;
    }
    for(int j = 1; j < ans_above.size(); j++) {
      cout << ans_above[j].real() << " " << ans_above[j].imag() << endl;
    }
    for(int j = 1; j < minIndex; j++) {
      cout << ans_under[j].real() << " " << ans_under[j].imag() << endl;
    }
  }
  else
