{
    //O(nlgn)
    sort(v.begin(),v.end(),[&](const Point &a,const Point &b){return tie(a.y,a.x) < tie(b.y,b.x);});
    v.erase(unique(v.begin(),v.end(),[&](const Point &a,const Point &b){return tie(a.y,a.x)==tie(b.y,b.x);}),v.end());
    if(v.size()<=2u) return v;

    vector<Point> up;
    for(auto p:v)
    {
        while(up.size()>=2u && (p-up.back())%(up.back()-up[up.size()-2])<0)
            up.pop_back();
        up.push_back(p);
    }
    vector<Point> dn;
    for(auto p:v)
    {
        while(dn.size()>=2u && (p-dn.back())%(dn.back()-dn[dn.size()-2])>0)
            dn.pop_back();
        dn.push_back(p);
    }
    reverse(dn.begin(),dn.end());
    up.insert(up.end(),dn.begin()+1,dn.end()-1);
    return move(up);
}

