static const int counter_clockwise = 2;
static const int clockwise = -2;
static const int online_back = -1;
static const int online_front = 1;
static const int onSegment = 0;

template<typename T>
int getPointPositionToSegment(const Point<T>& p, const Segment<T>& s)
{
	return getPointPositionToSegment(p, s.p1, s.p2);
}

template<typename T>
int getPointPositionToSegment(const Point<T>& p, const Point<T>& sp1, const Point<T>& sp2)
{
	const Point<NUM> a = sp2 - sp1;
	const Point<NUM> b = p - sp1;
	const NUM outer = cross(a, b);
	if (outer > EPS) return counter_clockwise;
	if (outer < -EPS) return clockwise;
	if (dot(a, b) < -EPS) return online_back;
	if (norm(b) > norm(a) + EPS) return online_front;
	return onSegment;
}
