template<typename T>
vector<Point<T>> convexHull(vector<Point<T>> points)
{
	const int n = points.size();
	sort(points.begin(), points.end(), Point<T>::compByCrd);

	vector<Point<T>> u; {
		u.reserve(points.size());
		u.insert(u.end(), points.begin(), points.begin() + 2);
		for (int i = 2; i != n; ++i) {
			for (int j = u.size() - 1; j != 0 ; --j) {
				const int pos = getPointPositionToSegment(points.at(i), u.at(j - 1), u.at(j));
				if (pos == clockwise || pos == online_front) break;
				u.pop_back();
			}
			u.push_back(points.at(i));
		}
	}

	vector<Point<NUM>> l; {
		l.reserve(points.size());
		l.insert(l.end(), points.rbegin(), points.rbegin() + 2);
		for (int i = points.size() - 3; i != -1; --i) {
			for (int j = l.size() - 1; j != 0 ; --j) {
				const int pos = getPointPositionToSegment(points.at(i), l.at(j - 1), l.at(j));
				if (pos == clockwise || pos == online_front) break;
				l.pop_back();
			}
			l.push_back(points.at(i));
		}
	}

	u.insert(u.end(), l.begin()+1, l.end() - 1);
	return u;
}



