    Polygon g(n);
    for (size_t i=0; i<n; ++i) {
        int x, y;
        scanf("%d %d", &x, &y);
        g[i] = Point(x, y);
    }

    Polygon h=convex_hull(g);
    printf("%zu\n", h.size());
    for (size_t i=0; i<h.size(); ++i)
        printf("%d %d\n", real(h[i]), imag(h[i]));

    return 0;
}

