vector<Point> makeConvexHull() {

	if (points.size() < 3)
		return points;

	vector<Point> top;
	vector<Point> under;

	sort(points.begin(), points.end());

	top.push_back(points[0]);
	top.push_back(points[1]);
	under.push_back(points[n - 1]);
	under.push_back(points[n - 2]);

	for (int i = 2; i < n; ++i) {
		for (int j = top.size(); j > 1; --j) {
			if (isClockwise(top[j - 2], top[j - 1], points[i]) != true)
				top.pop_back();
			else
				break;
		}
		top.push_back(points[i]);
	}

	for (int i = n - 3; i >= 0; --i) {
		for (int j = under.size(); j > 1; --j) {
			if (isClockwise(under[j - 2], under[j - 1], points[i]) != true)
				under.pop_back();
			else
				break;
		}
		under.push_back(points[i]);
	}

	/*
	cout << "top" << endl;
	print(top);
	cout << endl << "under" << endl;
	print(under);
	cout << endl << endl;
	*/

	vector<Point> answerPoint;
	vector<Point> tempPoint;
	int startIndex = 0;

	reverse(under.begin(), under.end());



	while (under[startIndex].y > minY) {
		tempPoint.push_back(under[startIndex]);
		startIndex++;
	}

	for(int i = startIndex; i < under.size(); ++i) 
		answerPoint.push_back(under[i]);

	for (int i = top.size() - 2; i >= 1; --i)
		answerPoint.push_back(top[i]);

	for (int i = 0; i < tempPoint.size(); ++i)
		answerPoint.push_back(tempPoint[i]);
	return answerPoint;



}

bool isClockwise(const Point &a, const Point &b, const Point &c) {

	Point a2b = b - a;
	Point a2c = c - a;

	return a2b.x * a2c.y - a2b.y * a2c.x < e;

}

