/*線分(x1,y1)(x2,y2)と線分(x3,y3)(x4,y4)の距離*/

double distance_between_two_line_segment(double x1, double y1, double x2, double y2, double x3, double y3, double x4, double y4){
    //同一直線上にある場合

    //ぶつかる場合
    if(line_segment_cross_decision(x1, y1, x2, y2, x3, y3, x4, y4)){
        return 0.0;
    }

    //ぶつからない場合
    double l1,l2,l3,l4;
