  cin >> n;
  Polygon pol(n);

  for(int i=0;i<n;i++)cin >> pol[i].x >> pol[i].y;

  Polygon ans=convex_hull(pol,n);

  cout << ans.size() << endl;
  for(int i=0;i<ans.size();i++)
    cout << ans[i].x << " " << ans[i].y << endl;

  return 0;
}

