double area_of_the_polygon(int n, double p_xy[10000][2]){
    double s=0.0;
    for(int i=0; i<n; i++){
        s+=(p_xy[i][0]-p_xy[(i+1)%n][0])*(p_xy[i][1]+p_xy[(i+1)%n][1])/2;
    }
    return s;
}


