// complexをpair-likeに
bool complexSort(Point lhs,Point rhs){
    if (sgn(lhs.imag()-rhs.imag())){
        return lhs.imag() < rhs.imag();
    }
    else{
        return lhs.real() < rhs.real();
    }
}

double cross(Point z1,Point z2){
    return (conj(z1)*z2).imag();
}
//graham scan
vector<Point> convex_hull(vector<Point> p){
    sort(all(p),complexSort);
    int cnt = 0,n = p.size();
    vector<Point> s(n*2);
    rep(i,n){
        while (cnt > 1 && sgn(cross(s[cnt-1]-s[cnt-2],p[i]-s[cnt-1])) < 0) cnt--;
        s[cnt++] = p[i];
    }
    for (ll i = n-2,t = cnt;i >= 0;i--){
        while (cnt > t && sgn(cross(s[cnt-1]-s[cnt-2],p[i]-s[cnt-1])) < 0) cnt--;
        s[cnt++] = p[i];
    }
    s.resize(cnt-1);
    return s;
}

//caliper
double convex_diameter(vector<Point> p){
    int n = p.size();
    if (n == 2){
        return abs(p[0]-p[1]);
    }
    int i = 0,j = 0;
    rep(k,n){
        if (!complexSort(p[i],p[k])) i = k;
        if (complexSort(p[j],p[k])) j = k;
    }
    double res = 0;
    int si = i,sj = j;
    while (i != sj || j != si){
        chmax(res,abs(p[i]-p[j]));
        if (sgn(cross(p[(i+1)%n]-p[i],p[(j+1)%n]-p[j])) < 0){
            i = (i+1)%n;
        }
        else{
            j = (j+1)%n;
        }
    }
    return res;
}

