struct cmp_xy { bool operator()(const point& pi, const point& pj) { return pi.x < pj.x || (eq(pi.x, pj.x) && pi.y < pj.y); } };



//****************************************
// 関数の定義
//****************************************

polygon_t andrew_scan(polygon_t& P, bool degenerate)
{
    index_t n = P.size(), i, k;
    if (n < 3) { return { }; }  // 入力は|P| >= 3を仮定する

    // 与えられた点の中からすべての点を左から右に順序付けする
    std::sort(P.begin(), P.end(), cmp_xy());  // NOTE: xが等しい場合、yの昇順とする

    // 縮退を考慮するか否かを決定する述語を設定する
    auto pred = degenerate
        ? std::function<bool(const polygon_t&, index_t, index_t)>([&](const polygon_t& L, index_t i, index_t k) -> bool
            { return ccw(L[k - 2], L[k - 1], P[i]) != orientation::cw; })
        : std::function<bool(const polygon_t&, index_t, index_t)>([&](const polygon_t& L, index_t i, index_t k) -> bool
            { return ccw(L[k - 2], L[k - 1], P[i]) == orientation::ccw;  });


    // まず、凸包上の点の中で上部凸包(upper hull)上にあるものだけ求める
    polygon_t Lu(n); Lu[0] = P[0]; Lu[1] = P[1];      // Lupperを(p0, p1)と初期化する
    for (i = 2, k = 2; i < n; i++, k++) {
        while (k >= 2 && pred(Lu, i, k)) { k = k - 1; }
        Lu[k] = P[i];
    }
    Lu.resize(k);

    // 右から左へと実行される2番目の走査で、凸包の残りの部分、すなわち下部凸包(lower hull)を計算する
    polygon_t Ll(n); Ll[0] = P[n-1]; Ll[1] = P[n-2];  // Llowerを(p(n-1), p(n-2))と初期化する
    for (i = n - 3, k = 2; i >= 0; i--, k++) {
        while (k >= 2 && pred(Ll, i, k)) { k = k - 1; }
        Ll[k] = P[i];
    }
    Ll.resize(k);


    index_t u = Lu.size(), l = Ll.size();
    std::reverse(Ll.begin(), Ll.end()); Ll.resize(u + l - 2);

    // 上部と下部の凸包は最初の点と最後の点が同一であるので、その重複を避けるためにLlowerからそれら2点を除いてLupperとLlowerを連結する
    for (i = u - 2, k = l; i >= 1; i--, k++) {
        Ll[k] = Lu[i];
    }
    return Ll;         // LupperとLlowerを連結して得られたリストLを返す
}


