    real d1 = abs(cross(s.b-s.a, t.b-t.a));
    real d2 = abs(cross(s.b-s.a, s.b-t.a));
    if(d1 < EPS && d2 < EPS) return t.a;
    return t.a+(t.b-t.a)*d2/d1;
}

