real area(Polygon &v){
    if(v.size() < 3) return 0.0;
    real ans = 0.0;
    for (int i = 0; i+1 < v.size(); ++i) {
        ans += cross(v[i], v[i+1]);
    }
    ans += cross(v.back(), v.front());
    return ans/2;
}

Polygon convex_hull(Polygon v){
    int n = v.size();
    sort(v.begin(),v.end(), sorty);
    int k = 0;
    Polygon ret(n*2);
    for (int i = 0; i < n; ++i) {
        while(k > 1 && cross(ret[k-1]-ret[k-2], v[i]-ret[k-1]) < 0) k--;
        ret[k++] = v[i];
    }
    for(int i = n-2, t=k; i >= 0; i--){
        while(k > t && cross(ret[k-1]-ret[k-2], v[i]-ret[k-1]) < 0) k--;
        ret[k++] = v[i];
    }
    ret.resize(k-1);
    return ret;
}

bool isconvex(Polygon &P){
    int n = P.size();
    for (int i = 0; i < n; ++i) {
        if(ccw(P[(i+n-1)%n], P[i], P[(i+1)%n]) == CLOCKWISE) return false;
    }
    return true;
}

