// 凸包 3点が一直線上に並ぶときに注意
G convex_hull(G ps) {
  int n = ps.size(), k = 0;
  sort(ps.begin(), ps.end(), cmp_y);
  G r(2*n);
  for(int i=0; i<n; i++){
    while(k>1 && ccw(r[k-2],r[k-1],ps[i])==RIGHT) k--;
    r[k++] = ps[i];
  }
  // cout << r << endl;
  for(int i=n-2,t=k; i>=0; i--){
    while(k>t && ccw(r[k-2],r[k-1],ps[i])==RIGHT) k--;
    r[k++] = ps[i];
  }
  // cout << r << endl;
  r.resize(k-1);
  return r;
}

