    for(int i=2;i<ps.size();i++)
    {
        for(int n=u.size();n>=2&&ccw(u[n-2],u[n-1],ps[i])!=CLOCKWISE;n--) u.pop_back();
        u.push_back(ps[i]);
    }
     for(int i=ps.size()-3;i>=0;i--)
