inline vector<Point> convex_hull(vector<Point> P)
{
    int n = P.size(), k = 0;
    if (n == 1) return P;
    vector<Point> H(2*n);

    sort(P.begin(), P.end());

    for (int i = 0; i < n; ++i) {
        while (k >= 2 && outer_product(H[k-2], H[k-1], P[i])) k--;
        H[k++] = P[i];
    }
#if 0
    for (int i = n-2, t = k+1; i >= 0; i--) {
        while (k >= t && outer_product(H[k-2], H[k-1], P[i])) k--;
        H[k++] = P[i];
    }
#endif
    H.resize(k-1);
    return H;
}

