takaku andrew(takaku g){
	takaku u,b;
	if(g.size()<3)return g;
	sort(ALL(g));
	u.pub(g[0]);u.pub(g[1]);
	b.pub(g.back());b.pub(g[g.size()-2]);
	rep(i,2,g.size()){
		rrep(j,u.size(),2){
			if(ccw(u[j-2],u[j-1],g[i])!=-1)break;
			u.pob();
		}
		u.pub(g[i]);
