using namespace std;
typedef complex<double> xy_t;
typedef vector<xy_t> Polygon;

constexpr double eps=numeric_limits<double>::epsilon();
double x,y;
int n;
Polygon p_set,convex;


double dot(xy_t a,xy_t b){
    return a.real()*b.real()+a.imag()*b.imag();
}

double cross(xy_t a,xy_t b){
    return a.real()*b.imag()-a.imag()*b.real();
}

int ccw(xy_t p0,xy_t p1,xy_t p2){
    /*
    counter clockwise:1
    clockwise:-1
    online back:2
    online front:-2
   */
    xy_t line1=p1-p0;
    xy_t line2=p2-p0;
    if(cross(line1,line2)>eps) return 1;
    else if(cross(line1,line2)<-eps) return -1;
    else if(dot(line1,line2)<-eps) return 2;
    else if(norm(line1)>norm(line2)) return -2;
    return 0;
}

bool myway(xy_t a,xy_t b){
    if(a.real()==b.real()){
        return a.imag()<b.imag();
    }
    return a.real()<b.real();
}

void print(Polygon a){
    cout<<a.size()<<endl;
    for(int i=0;i<a.size();++i){
        x=a[i].real();
        y=a[i].imag();
        cout<<x<<" "<<y<<endl;
    }
}

Polygon andrew(Polygon p){
    Polygon upper,lower;

    if(p.size()<3) return p;

    sort(p.begin(),p.end(),myway);
    upper.push_back(p[0]); upper.push_back(p[1]);
    lower.push_back(p[p.size()-1]); lower.push_back(p[p.size()-2]);

    for(int i=2;i<p.size();++i){

        for(int j=upper.size()-1;j>=1;--j){
            if(ccw(upper[j-1],upper[j],p[i])!=1){
                break;
            }
            else upper.pop_back();
        }
        for(int j=lower.size()-1;j>=1;--j){
            if(ccw(lower[j-1],lower[j],p[p.size()-i-1])!=1){
                break;
            }
            else lower.pop_back();

        }

        upper.push_back(p[i]);
        lower.push_back(p[p.size()-i-1]);
    }

    reverse(lower.begin(),lower.end());
    for(int i=upper.size()-2;i>=1;--i){
        lower.push_back(upper[i]);
    }

    Polygon ans;
    double min=10100.0;
    int min_index;
    for(int i=0;i<lower.size();++i){
        if(lower[i].imag()<min){
            min=lower[i].imag(); min_index=i;
        }
    }

    for(int i=0;i<lower.size();++i){
        ans.push_back(lower[(i+min_index)%lower.size()]);
    }
    return ans;
}

