// エントリポイント
//****************************************

int main()
{
    using namespace std;
    int n;
    cin >> n;

    polygon_t poly(n);
    for (int i = 0; i < n; i++) {
        coord_t x, y;
        cin >> x >> y;
        poly[i] = point(x, y);
    }

    polygon_t convex_hull = andrew_scan(poly, false);

    cout << convex_hull.size() << endl;
    for (auto& p : convex_hull) {
        cout << p.x << " " << p.y << endl;
    }

    return 0;
}

