struct angle {
	long double r;
	angle() :r(0) {}
	angle(long double r_) :r(arr(std::fmod(r_, 2.0 * PI) + 2.0 * PI)) {}
	static long double arr(const long double &o) { return o < 2.0 * PI - eps ? o : o - 2.0 * PI; }
	static angle make(const long double &o) { angle ret;ret.r = o;return ret; }
	const angle operator+(const angle &o)const { return make(arr(r + o.r)); }
	const angle operator-(const angle &o)const { return make(arr(r - o.r + 2.0 * PI)); }
	const angle operator*(const long double &o)const { return angle(r * o); }
	const angle operator/(const long double &o)const { return angle(r / o); }
	angle &operator+=(const angle &o) { return *this = *this + o; }
	angle &operator-=(const angle &o) { return *this = *this - o; }
	angle &operator*=(const long double &o) { return *this = *this * o; }
	angle &operator/=(const long double &o) { return *this = *this / o; }
	const angle operator~()const { return make(arr(3.0 * PI - r)); }
	const angle operator-()const { return make(arr(2.0 * PI - r)); }
	const bool operator==(const angle &o)const { return std::abs(r - o.r) <= eps; }
	const bool operator!=(const angle &o)const { return std::abs(r - o.r) > eps; }
	const bool operator< (const angle &o)const { return r <  o.r; }
	const bool operator<=(const angle &o)const { return r <= o.r; }
	const bool operator> (const angle &o)const { return r >  o.r; }
	const bool operator>=(const angle &o)const { return r >= o.r; }
	explicit operator bool()const { return r > eps; }
	explicit operator long double()const { return r; }
	const long double sin()const { return std::sin(r); }
	const long double cos()const { return std::cos(r); }

	const long double degree()const { return r*(180.0 / PI); }
	const long double ratio()const { return r / (2.0 * PI); }
private:
	static constexpr long double eps = 0.000000001;
};
angle operator"" _deg(long  double x) { return angle(x*(PI / 180.0)); }
