vector<xy_t> convhull;
pii g[1000000];
xy_t cg[1000000];

int convexHull(int n) {
    sort(g, g + n);
    for (int i = 0; i < n; i++) {
        cg[i] = xy_t(g[i].first, g[i].second);
    }
    vector<xy_t> down;
    down.push_back(cg[0]);
    for (int i = 1; i < n; i++) {
        while (true) {
            if (down.size() == 1) {
                down.push_back(cg[i]);
                break;
            } else {
                xy_t a = down[down.size() - 2];
                xy_t b = down[down.size() - 1];
                double diff = cross_product(b - a, cg[i] - a);
                if (diff > -1 * eps) {
                    down.push_back(cg[i]);
                    break;
                } else {
                    down.pop_back();
                }
            }
        }
    }
    vector<xy_t> up;
    up.push_back(down[down.size() - 1]);
    for (int i = n - 2; i >= 0; i--) {
        while (true) {
            if (up.size() == 1) {
                up.push_back(cg[i]);
                break;
            } else {
                xy_t a = up[up.size() - 2];
                xy_t b = up[up.size() - 1];
                double diff = cross_product(b - a, cg[i] - a);
                if (diff > -1 * eps) {
                    up.push_back(cg[i]);
                    break;
                } else {
                    up.pop_back();
                }
            }
        }
    }
    int downlen = down.size();
    for (int i = 0; i < downlen; i++) {
        convhull.push_back(down[i]);
    }
    int uplen = up.size();
    for (int i = 1; i < uplen - 1; i++) {
        convhull.push_back(up[i]);
    }
    int num = downlen + uplen - 2;
    return num;
}

