const int INF = ~(1 << 31);

int main() {
	int n, x, y;
	vector< pair< int, int > > ps;
	vector< int > order;
	vector< int > used;
	double angle = 0;
	int cur;
	int left = INF, down = INF;

	cin >> n;
	ps.resize(n);
	used.resize(n);
	for(int i = 0; i < n; ++i){
		cin >> x >> y;
		ps[i] = make_pair(x, y);

		if(x < left){
			left = x;
			cur = i;
		}
		if(y < down){
			down = y;
			cur = i;
		}
	}

	do{
		order.push_back(cur);
		used[cur] = 1;

		int next;
		double min_angle = INF;

		for(int i = 0; i < n; ++i){
			if(i != cur){
				double t = atan2(ps[i].second - ps[cur].second, ps[i].first - ps[cur].first);
				if(t < 0) t = 180 - t;

				t = t - angle;

				if(t < min_angle){
					min_angle = t;
					next = i;
				}
			}
		}
		angle += min_angle;
		cur = next;
	}while(!used[cur]);

	cout << order.size() << endl;
	for(vector< int >::iterator it = order.begin(); it != order.end(); ++it){
		cout << ps[*it].first << " " << ps[*it].second << endl;
	}

