{
  int n;
  cin >> n;

  ConvexHull ch(n);

  for ( auto i = 0; i < n; ++i )
    {
      double x, y;
      cin >> x >> y;
      ch.v[i] = Vector( x, y );
    }

  ch.solve();

  return 0;
}

