    if (abs(cross(a, b)) < EPS && dot(a, b) < EPS) return 1;
    if (a.y > b.y) swap(a, b);
    if (a.y < EPS && EPS < b.y && cross(a, b) > EPS) x = !x;
  }
  return (x ? 2 : 0);
}

int main() {
  Polygon poly;
  int n;
  cin >> n;
  for (int i = 0; i < n; i++) {
    int x, y;
    cin >> x >> y;
    poly.push_back(Vector(x, y));
  }
  Polygon convexhull = andrewScan(poly);
  int m = convexhull.size();
  cout << m << endl;
  int p = 0;
  for (int i = 0; i < m; i++) {
    if (convexhull[i] < convexhull[p]) p = i;
  }
  for (int i = 0; i < m; i++) {
    cout << convexhull[(p+i)%m].x << " " << convexhull[(p+i)%m].y << endl;
  }
}

