	REP(i,n) {
		cin >> x >> y;
		pp[i] = Point(x,y);
	}
	vector<Point> ans = convexHull(pp);
	cout << ans.size() << endl;
	sort_y(ans);
	REP(i,ans.size()) {
		cout << ans[i].x << " " << ans[i].y << endl;
	}
}

