  rep(i,len){
    if(ans[i].y < mini){
      mini = ans[i].y;
      piv = i;
    }
  }
  rep(i,len){
    cout << ans[(i+piv) % len].x << " " << ans[(i+piv) % len].y << endl;
  }
}

