    for (int i = 0; i < n - 2; i++) {
        if ((H[k].x - H[k - 1].x) * (P[i + 2].y - H[k - 1].y) - (H[k].y - H[k - 1].y) * (P[i + 2].x - H[k - 1].x) < 0) {
            H.pop_back();
