    H.push_back(P[n - 2]);
    for (int i = n; i > 2; i--) {
        if ((H[k + 1].x - H[k].x) * (P[i - 3].y - H[k].y) - (H[k + 1].y - H[k].y) * (P[i - 3].x - H[k].x) < 0) {
            H.pop_back();
            k--;
            while ((H[k + 1].x - H[k].x) * (P[i - 3].y - H[k].y) - (H[k + 1].y - H[k].y) * (P[i - 3].x - H[k].x) < 0) {
                H.pop_back();
                k--;
            }
            H.push_back(P[i - 3]);
            k++;
        }
        else {
            H.push_back(P[i - 3]);
            k++;
        }
    }
    H.pop_back();
#if 0
    if ((H[k].x - H[k - 1].x) * (H[0].y - H[k - 1].y) - (H[k].y - H[k - 1].y) * (H[0].x - H[k - 1].x) < 0) {
        H.pop_back();
    }
#endif
    return H;
}

