class Geom{
	public:
	double IP(point p,point q){
		return p.x*q.x+p.y*q.y;
	}
	double CP(point p,point q){
		return p.x*q.y-q.x*p.y;
	}
	VP Convex_Hull(VP p){
		sort(p.begin(),p.end(),[](point a,point b){
			if(fabs(a.y-b.y)>eps) return a.y<b.y;
			return a.x<b.x;
		});
		int v=0,n=p.size();
		VP q(n*2);
		for(int i=0;i<n;i++){
			while(v>1&&CP(q[v-1]-q[v-2],p[i]-q[v-2])<-eps) v--;
			q[v++]=p[i];
		}
		for(int i=n-2,t=v;i>=0;i--){
			while(v>t&&CP(q[v-1]-q[v-2],p[i]-q[v-2])<-eps) v--;
			q[v++]=p[i];
		}
		q.resize(v-1);
		return q;
	}
	void Point_in(point& p){
		cin>>p.x>>p.y;
	}
	void Point_out(point p){
		cout<<p.x<<' '<<p.y<<endl;
	}
};

