bool overline (int s, int m, int e){
	long double m1 = atan2(radian[m].yy - radian[s].yy, radian[m].xx - radian[s].xx);
	long double m2 = atan2(radian[e].yy - radian[s].yy, radian[e].xx - radian[s].xx);
	return same(m1, m2);
}

short int side(int s, int m, int e){
	if (overline(s, m, e)) return 0;

	// cerr << "params:\nxs " << radian[s].xx << " ys " << radian[s].yy << "\nxm "<< radian[m].xx << " ym "<< radian[m].yy << "\nxe " << radian[e].xx << " ye " << radian[e].yy << endl;
	//Data Set Over Radian // R:1 // O:0 // L : -1
	if (radian[s].xx == radian[e].xx){
		if (radian[s].yy < radian[e].yy) {
			if (radian[s].xx < radian[m].xx) return 1;
			else return -1;
		} else {
			if (radian[s].xx < radian[m].xx) return -1;
			else return 1;
		}
	} // pi/2 Radian cut out!

	double th = atan2(radian[e].yy - radian[s].yy, radian[e].xx - radian[s].xx);
	double ml = (radian[e].yy - radian[s].yy) / (radian[e].xx - radian[s].xx);
	double c = radian[s].yy - (ml * radian[s].xx);

	// cerr << "th " << th << "->" << atan2(1,0) << " ml " << ml << " c " << c << endl;

	if (abs(th) < atan2(1,0) ) return (radian[m].yy > (ml * radian[m].xx) + c? -1:1);
	else return (radian[m].yy > (ml * radian[m].xx) + c? 1:-1);
}

void plan_init(int &lst){
	doted.push_back(0);
	doted.push_back(1);
	lst = 2;
	while (radian[lst].thetha == radian[doted.back()].thetha)
		doted.push_back(lst++);
	reverse (doted.begin() + 1, doted.end());
}

bool valid (int late, int mid, int head){
	//if (radian[late])
	return !(side(late, mid, head) == 1);
}

void normalize(){
	bool flag; do{
		int header = doted.back(); doted.pop_back();
		int mid = doted.back(); doted.pop_back();
		int late = doted.back();
		flag = true;
		// cerr << "Checking for : " << radian[late].second.second << ' ' << radian[mid].second.second << ' ' << radian[header].second.second << "->" << side(late, mid, header) << endl;
		if (valid(late, mid, header)){
			flag = false;
			doted.push_back(mid);
			doted.push_back(header);
		} else doted.push_back(header);
	} while (flag && doted.size() > 2);
}

void add(int i){
	doted.push_back(i);
