typedef complex<double> P;
namespace std{
	bool operator < (const P& a, const P& b){
		return fabs(real(a) - real(b)) > EPS ? real(a) < real(b) : imag(a) < imag(b);
	}
}
double cross(const P& a, const P& b){
	return imag(conj(a) * b);
}
double dot(const P& a, const P& b){
	return real(conj(a) * b);
}
typedef vector<P> G;

int ccw(P a, P b, P c){
	b -= a; c -= a;
	if(cross(b, c) > EPS) return 1;
	if(cross(b, c) < -EPS) return -1;
	if(dot(b, c) < -EPS) return 2;
	if(norm(b) < norm(c)) return -2;
	return 0;
}

G convex_hull(G ps){
	int n = ps.size(), k = 0;
	if(n == 3){
		if(ccw(ps[0], ps[1], ps[2]) < 0) swap(ps[1], ps[2]);
		return ps;
	}
	sort(ps.begin(), ps.end());
	G ch(2 * n);
	for(int i = 0; i < n; ch[k++] = ps[i++]){
		while(k >= 2 && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0 && ccw(ch[k - 2], ch[k - 1], ps[i]) != -2) --k;
	}
	for(int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]){
		while(k >= t && ccw(ch[k - 2], ch[k - 1], ps[i]) <= 0 && ccw(ch[k - 2], ch[k - 1], ps[i]) != -2) --k;
	}
	ch.resize(k - 1);
	return ch;
}

