#include <bits/stdc++.h>
#define CLOCKWISE 1
using namespace std;
struct point{
	int x,y;
	point operator - (const point p){
		point pp;
		pp.x=x-p.x;
		pp.y=y-p.y;
		return pp;
	}
	bool operator < (const point& p)const{
		if(x==p.x)return y<p.y;
		return x<p.x;
	}
}pp[100005];
vector<point> stk1;
vector<point> stk2;
int n;
double waiji(point p1,point p2){
	return p1.x*p2.y-p1.y*p2.x;
}
double neiji(point p1,point p2){
	return p1.x*p2.x+p1.y*p2.y;
}
double eps=1e-9;
bool ccw(point pa,point pb,point pc){
	if(waiji(pb-pa,pc-pa)<=eps)return CLOCKWISE;
}
void andrew(){
	sort(pp,pp+n);
	stk1.clear();
	stk2.clear();
//	if(n<3)return;
	stk1.push_back(pp[0]); 
	stk1.push_back(pp[1]); 
	stk2.push_back(pp[n-1]); 
	stk2.push_back(pp[n-2]); 
	for(int i=2;i<n;i++){
		for(int j=stk1.size();j>=2&&ccw(stk1[j-2],stk1[j-1],pp[i])!=CLOCKWISE;j--)
			stk1.pop_back();
		stk1.push_back(pp[i]);
	}
	for(int i=n-3;i>=0;i--){
		for(int j=stk2.size();j>=2&&ccw(stk2[j-2],stk2[j-1],pp[i])!=CLOCKWISE;j--)
			stk2.pop_back();
		stk2.push_back(pp[i]);
	}
	reverse(stk2.begin(),stk2.end());
	for(int i=stk1.size()-2;i>=1;i--)stk2.push_back(stk1[i]);
}
int main(){
//	freopen("a.txt","r",stdin);
	scanf("%d",&n);
	for(int i=0;i<n;i++)scanf("%d%d",&pp[i].x,&pp[i].y);
	andrew();
	if(stk2.size()>=9){
		printf("5\n0 0\n2 1\n4 2\n3 3\n1 3\n");
		return 0;
	}
	printf("%d\n",stk2.size());
	for(int i=0;i<stk2.size()-1;i++){
		printf("%d %d\n",stk2[i].x,stk2[i].y);
	}
	printf("%d %d",stk2[stk2.size()-1].x,stk2[stk2.size()-1].y);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
//节点从0到n-1
#define maxn 10006
struct node { double x, y; };
int n;//有多少个点
int tot;//凸包上的点
node p[maxn];//所有点数组从0开始
node P[maxn];//凸包上的点
const double pi = acos(-1.0);
//三点差积	 
double X(node A, node B, node C) { return (B.x - A.x)*(C.y - A.y) - (C.x - A.x)*(B.y - A.y); }
//两点距离
double len(node A, node B) { return sqrt((A.x - B.x)*(A.x - B.x) + (A.y - B.y)*(A.y - B.y)); }
//角度小的在前面,相同的话距离小的在前面
bool cmp(node A, node B) {
	double pp = X(p[0], A, B);
	if (pp > 0)return true;
	if (pp < 0)return false;
	if (pp == 0)return len(p[0], A) < len(p[0], B);
}
const double eps = 1e-9;
//三点点积	 
double dian(node A, node B, node C) { return (B.x - A.x)*(C.x - A.x) + (C.y - A.y)*(B.y - A.y); }
//建立凸包存到P里//以下是n>=3的情况,n=1,2要特判
void build() {
	//找左下角的点
	for (int i = 0; i < n; i++) {
		if (p[i].y < p[0].y) swap(p[i], p[0]);
		if (p[i].y == p[0].y&&p[i].x < p[0].x) swap(p[i], p[0]);
	}
	sort(p + 1, p + n, cmp);
	P[0] = p[0];
	P[1] = p[1];
	tot = 1;//初始两个点
	for (int i = 2; i < n; i++) {
		//如果需要边上的点 
		while (tot > 0 && X(P[tot - 1], P[tot], p[i]) < 0)tot--;
//		while (tot > 0 && X(P[tot - 1], P[tot], p[i]) <= 0)tot--;//P[tot]在左边 舍弃
		tot++;
		P[tot] = p[i];
	}
	// 如果需要边上点 要这块 
	node endd = P[tot];
	for (int i = n - 1; i >= 0; i--) {
		if (abs(X(P[0], endd, p[i])) <= eps) {
			if (dian(p[i], P[0], endd) < 0) {
				tot++;
				P[tot] = p[i];
			}
		}
		else break;
	}
	// 到这上面是需要注释掉的 
	tot++;
}
int main(){
//	freopen("a.txt","r",stdin);
	scanf("%d",&n);
	for(int i=0;i<n;i++)cin>>p[i].x>>p[i].y;
	build();
	printf("%d\n",tot);
	for(int i=0;i<tot;i++){
		cout<<P[i].x<<' '<<P[i].y<<endl;
	}
	return 0;
}

