}

int main() {
    int n;
    cin >> n;
    pii c[n];
    int x, y;
    for (int i = 0; i < n; i++) {
        cin >> x >> y;
        c[i] = pii(x, y);
    }
    sort(c, c + n);
    xy_t cc[n];
    for (int i = 0; i < n; i++) {
        cc[i] = xy_t(c[i].first, c[i].second);
    }
    vector<xy_t> down;
    down.push_back(cc[0]);
    for (int i = 1; i < n; i++) {
        while (true) {
            if (down.size() == 1) {
                down.push_back(cc[i]);
                break;
            } else {
                xy_t a = down[down.size() - 2];
                xy_t b = down[down.size() - 1];
                double diff = cross_product(b - a, cc[i] - a);
                if (diff > -1 * eps) {
                    down.push_back(cc[i]);
                    break;
                } else {
                    down.pop_back();
                }
            }
        }
    }
    vector<xy_t> up;
    up.push_back(down[down.size() - 1]);
    for (int i = n - 2; i >= 0; i--) {
        while (true) {
            if (up.size() == 1) {
                up.push_back(cc[i]);
                break;
            } else {
                xy_t a = up[up.size() - 2];
                xy_t b = up[up.size() - 1];
                double diff = cross_product(b - a, cc[i] - a);
                if (diff > -1 * eps) {
                    up.push_back(cc[i]);
                    break;
                } else {
                    up.pop_back();
                }
            }
        }
    }
    int num = down.size() + up.size() - 2;
    cout << num << endl;
    int bottom = 0;
    for (int i = 0; i < down.size() - 1; i++) {
        if (down[i].imag() <= down[i + 1].imag()) {
            break;
        }
        bottom++;
    }
    cout << bottom << endl;
    for (int i = bottom; i < down.size(); i++) {
        cout << down[i].real() << " " << down[i].imag() << endl;
    }
    for (int i = 1; i < up.size() - 1; i++) {
        cout << up[i].real() << " " << up[i].imag() << endl;
    }
    for (int i = 0; i < bottom; i++) {
        cout << down[i].real() << " " << down[i].imag() << endl;
    }
}

#include<bits/stdc++.h>
using namespace std;
typedef complex<double> P;
typedef complex<double> V;
typedef vector<P> vecP;
typedef pair<P,P> L;
typedef pair<P,P> S;
typedef pair<P,double> C;
const double eps=1e-8;
const double PI=acos(-1);
const double PI2=PI*2.0;

namespace std{
  bool operator < (const P &a,const P &b){
    return (a.imag()==b.imag()?
            a.real()<b.real():
            a.imag()<b.imag());
  }
};

V normal(V a){
  assert( abs(a)>0 );
  return a/abs(a);
}

double Sqrt( double x ){
  if(x<0)return 0;
  else return sqrt(x);
}

P Vector(L a){
  return a.second-a.first;
}

bool eq(double a,double b){
  return (-eps<a-b&&a-b<eps);
}

bool eq(P a,P b){
  return ( eq(a.real(),b.real()) && eq(a.imag(),b.imag()) );
}

double dot(P a,P b){
  return real(b*conj(a));
}

double cross(P a,P b){
  return imag(b*conj(a));
}

double getArg(P a,P b){
  return arg(b*conj(a));
}

double getTime(V a,V b){
  assert( eq(cross(a,b),0) );
  return ( dot(a,b) < 0 ? -1.0 : 1.0 ) * abs(b) / abs(a);
}


P project(P a,P b,P c){
  b-=a,c-=a;
  return a+b*real(c/b);
}

P reflect(P a,P b,P c){
  b-=a,c-=a;
  return a+b*conj(c/b);
}

int ccw(P a,P b,P c){
  P ab=b-a,ac=c-a;
  P k=ac*conj(ab);
  if(k.imag()>0)return 1;
  if(k.imag()<0)return -1;
  if(k.real()<0)return 2;
  if(abs(ab)<abs(ac))return -2;
  return 0;
}

bool isParallel(P a,P b){
  return eq(0, cross(a,b));
}

bool isParallel(S a,S b){
  return eq(0, cross( Vector(a) , Vector(b) ) );
}

bool onLP(L l,P p){
  P a=l.first, b=l.second;
  return eq(0, cross(b-a,p-a));
}

bool onSP(S s,P p){
  P a=s.first, b=s.second;
  return eq( abs(b-a) , abs(a-p)+abs(b-p) );
}

bool isCrossSS(S s0,S s1){
  P a=s0.first, b=s0.second;
  P c=s1.first, d=s1.second;
  int f0 = ccw(a,b,c) * ccw(a,b,d);
  int f1 = ccw(c,d,a) * ccw(c,d,b);
  return (f0<=0 && f1<=0);
}

bool isCrossLS(L l,S s){
  P a=l.first, b=l.second;
  P c=s.first, d=s.second;
  return ( ccw(a,b,c) * ccw(a,b,d) <= 0 );
}

double distLP(L l,P p){
  P a=l.first, b=l.second;
  double res = cross(b-a,p-a) / abs(b-a);
  return abs(res);
}

double distSP(S s,P p){
  P a=s.first, b=s.second;
  if( dot(b-a,p-a) < eps )return abs(p-a);
  if( dot(a-b,p-b) < eps )return abs(p-b);
  return distLP(s,p);
}

double distSS(S s0,S s1){
  if( isCrossSS(s0,s1) )return 0;
  double res0 = min( distSP( s0, s1.first ) , distSP(s0, s1.second) );
  double res1 = min( distSP( s1, s0.first ) , distSP(s1, s0.second) );
  return min(res0,res1);
}

P getCrossLL(L l0,L l1){
  P a=l0.first, b=l0.second;
  P c=l1.first, d=l1.second;
  a-=d;b-=d;c-=d;
  return d+a+(b-a)*imag(a/c)/imag(a/c-b/c);
}



int inPolygon(vecP &t,P p){
