class Vector
{
public:
  double x;
  double y;

  Vector(){}
  Vector( double x, double y ) : x(x), y(y) {}

  Vector operator + ( const Vector v ) { return Vector( x + v.x, y + v.y ); }
  Vector operator - ( const Vector v ) { return Vector( x - v.x, y - v.y ); }
  Vector operator * ( const double k ) { return Vector( x * k, y * k ); }
  Vector operator / ( const double k ) { return Vector( x / k, y / k ); }
  bool operator < ( const Vector &v ) const { if ( y == v.y ) return x < v.x; else return y < v.y; }
  bool operator == ( const Vector &v ) const { return x == v.x && y == v.y; }
  double abs() { return sqrt( norm() ); }
  double norm() { return x * x + y * y; }

  static double dot( Vector v1, Vector v2 ) { return v1.x * v2.x + v1.y * v2.y; }
  static double cross( Vector v1, Vector v2 ) { return v1.x * v2.y - v1.y * v2.x; }
};

class ConvexHull
{
public:
  int n;
  vector<Vector> v;
  ConvexHull(){}
  ConvexHull( int n ) : n(n), v(n) {}
  int solve();
};

int ConvexHull::solve()
{
  sort( v.begin(), v.end() );

  vector<Vector> ret;
  Vector sp, pp, cp, np;

  sp = v[0];
  cp = sp;
  pp = Vector( sp.x - 1, sp.y );

  ret.push_back( sp );

  while( true )
    {
      double maxc = -2;

      for ( auto i = 0; i < n; ++i )
        {
          if ( v[i] == cp ) continue;

          Vector v1 = cp - pp;
          Vector v2 = v[i] - cp;

          double c = Vector::dot( v1, v2 ) / ( v1.abs() * v2.abs() );

          if ( c > maxc )
            {
              maxc = c;
              np = v[i];
            }
        }

      if ( np == sp ) break;

      ret.push_back( np );
      pp = cp;
      cp = np;
    }

  cout << ret.size() << endl;

  for ( auto it = ret.begin(); it != ret.end(); ++it )
    cout << (*it).x << " " << (*it).y << endl;

  return 0;
}

int main()
{
  int n;
  cin >> n;

  ConvexHull ch(n);

  for ( auto i = 0; i < n; ++i )
    {
      double x, y;
      cin >> x >> y;
      ch.v[i] = Vector( x, y );
    }

  ch.solve();

  return 0;
}

