double EPS = 1e-10;

double add(double a, double b){
	if(abs(a + b) < EPS * (abs(a) + abs(b))){
		return 0;
	}
	return a + b;
}

struct P{
	double x, y;
	P(){}
	P(double x, double y) : x(x), y(y){}
	P operator + (P p){
		return P(add(x, p.x), add(y, p.y));
	}
	P operator - (P p){
		return P(add(x, -p.x), add(y, -p.y));
	}
	P operator * (double d){
		return P(x * d, y * d);
	}
	double dot(P p){
		return add(x * p.x, y * p.y);
	}
	double det(P p){
		return add(x * p.y, -y * p.x);
	}
};

// x -> y の順で比較
bool cmp_x(const P& p, const P& q){
	if(p.x != q.x){
		return p.x < q.x;
	}
	return p.y < q.y;
}

bool cmp_y(const P& p, const P& q){
	if(p.y != q.y){
		return p.y < q.y;
	}
	return p.x < q.x;
}

// P* ps に対し、破壊的な操作を行う点に注意
vector<P> convex_hull(P* ps, int n){
	sort(ps, ps + n, cmp_x);
	int k = 0; // 凸包の頂点数
	vector<P> qs(n * 2); // 構築中の凸包

	// 上側凸包の作成
	for(int i = 0; i < n; i++){
		while(k > 1 && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= -EPS){
			k--;
		}
		qs[k++] = ps[i];
	}

	// 下側凸包の作成
	for(int i = n - 2, t = k; i >= 0; i--){
		while(k > t && (qs[k - 1] - qs[k - 2]).det(ps[i] - qs[k - 1]) <= -EPS){
			k--;
		}
		qs[k++] = ps[i];
	}
	qs.resize(k - 1);
	return qs;
}

