		if(cmp_y(qs[i], p)){
			p = qs[i];
			id = i;
		}
	}

	for(int i = 0; i < sz; i++){
		cout << qs[(i + id) % sz].x << " " << qs[(i + id) % sz].y << endl;
	}

	return 0;
}

