  ConvexHull(){}
  ConvexHull( int n ) : n(n), v(n) {}
  int solve();
};

int ConvexHull::solve()
{
  sort( v.begin(), v.end() );

  vector<Vector> ret;
  Vector sp, pp, cp, np;

  sp = v[0];
  cp = sp;
  pp = Vector( sp.x - 1, sp.y );

  ret.push_back( sp );

  while( true )
    {
      double maxc = -2;
      double minn = 800000000;

      for ( auto i = 0; i < n; ++i )
        {
          if ( v[i] == cp ) continue;

          Vector v1 = cp - pp;
          Vector v2 = v[i] - cp;

          double c = Vector::dot( v1, v2 ) / ( v1.abs() * v2.abs() );

          if ( c - maxc > eps || ( fabs( c - maxc ) < eps && minn > v2.norm() ) )
            {
              maxc = c;
              minn = v2.norm();
              np = v[i];
            }
        }

      if ( np == sp ) break;

      ret.push_back( np );
      pp = cp;
      cp = np;
    }

  cout << ret.size() << endl;

  for ( auto it = ret.begin(); it != ret.end(); ++it )
    // cout << (*it).x << " " << (*it).y << endl;
    printf( "%d %d\n", (int)(*it).x, (int)(*it).y);
  return 0;
}

