/* Three points are a counter-clockwise turn if ccw > 0, clockwise if
 * ccw < 0, and collinear if ccw = 0 because ccw is a determinant that
 * gives the signed area of the triangle formed by p1, p2 and p3.
 */
static long
ccw(point_t* p1, point_t* p2, point_t* p3)
{
    return (p2->x - p1->x)*(p3->y - p1->y) - (p2->y - p1->y)*(p3->x - p1->x);
}

/* Returns a list of points on the convex hull in counter-clockwise order.
 * Note: the last point in the returned list is the same as the first one.
 */
void
convex_hull(point_t* points, long npoints, point_t*** out_hull, long* out_hullsize)
{
    point_t** hull;
    long i, t, k = 0;

    hull = *out_hull;

/* lower hull */
    for (i = 0; i < npoints; ++i) {
      while (k >= 2 && ccw(hull[k-2], hull[k-1], &points[i]) <= 0) --k;
      hull[k++] = &points[i];
    }

/* upper hull */
    for (i = npoints-2, t = k+1; i >= 0; --i) {
      while (k >= t && ccw(hull[k-2], hull[k-1], &points[i]) <= 0) --k;
      hull[k++] = &points[i];
    }

    *out_hull = hull;
    *out_hullsize = k;
}

