double distanceLP(LINE a,POINT p){
if(dot(make_vec(a.s,a.e),make_vec(a.s,p)) < 0.0)
return norm(make_vec(a.s,p));
if(dot(make_vec(a.e,a.s),make_vec(a.e,p)) < 0.0)
return norm(make_vec(a.e,p));
return norm(make_vec(p,perpendicular(a,p)));
}

