	static void sort( Point[] query ){
		for(int i=0;i<query.length;i++){
			for(int j=0;j<query.length-1-i;j++){
				if(query[j].x > query[j+1].x){
					query[j].temp(query[j+1]);
				}
				else if(query[j].x == query[j+1].x && query[j].y > query[j+1].y){
					query[j].temp(query[j+1]);
				}
			}
		}
	}
	static int[] andrewScan( Point[] query ){
        sort(query);
        final int n = query.length;
        int[] idx = new int[n];
        int ptr = 0;
        int[] ret = new int[n*2];
		if(n<3){
            for(int i=0;i<n;i++){
                ret[i] = i;
            }
        }
        else{
            for(int i=0;i<n;i++){
                idx[i] = i;
            }
            for(int i=0;i<n;i++){
                if(ptr>0 && query[ret[ptr-1]].judge(query[idx[i]])){
                    continue;
                }
                while(ptr>1 && query[ret[ptr-2]].CCW(query[idx[i]],query[ret[ptr-1]]) == -1){
                    ptr--;
                }
                ret[ptr++] = idx[i];
            }

            int end = ptr;
            for(int i=n-2;i>=0;i--){
                if(query[ret[ptr-1]].judge(query[idx[i]])){
                    continue;
                }
                while(ptr>end && query[ret[ptr-2]].CCW(query[idx[i]],query[ret[ptr-1]]) == -1){
                    ptr--;
                }
                ret[ptr++] = idx[i];
            }
        }
        return copyOf(ret,ptr-1);
	}
	double area( Point[] query ){
		double area = 0;
		for(int i=0;i<query.length-1;i++){
			area += (query[i].x - query[i+1].x) * (query[i].y + query[i+1].y)/2;
		}
		area += (query[query.length-1].x - query[0].x) * (query[query.length-1].y + query[0].y)/2;
		area = Math.abs(area);
		return area;
	}

	Point polarCos(double cos_a){
