			Vector v2 = new Vector(this.x,this.y,query[(i+1)%query.length].x,query[(i+1)%query.length].y);
			if(v1.y<=0 && v2.y>0 && v1.cross(v2)<0){
				flag2 = !flag2;
			}
			else if(v2.y<=0 && v1.y>0 && v2.cross(v1)<0){
				flag2 = !flag2;
			}
		}
		if(flag1){
			return 1;
		}
		else if(flag2){
			return 2;
		}
		return 0;
	}

