					list1.add(query[query.length-1]);
					flag1 = false;
				}
				else{
					list1.remove(list1.size()-1);
					if(list1.size()<2){
						list1.add(query[query.length-1]);
						flag1 = false;
					}
				}
			}
			list2.add(query[query.length-1]);
			list2.add(query[query.length-2]);
			next = query.length-3;
			while(next>0){
				if(list2.size()<2){
					list2.add(query[next]);
					next--;
				}
				else{
					Point a = list2.get(list2.size()-2);
					Point b = list2.get(list2.size()-1);
					if(a.CCW(b,query[next])!=-1){
						list2.add(query[next]);
						next--;
					}
					else{
						list2.remove(list2.size()-1);
					}
				}
			}
			boolean flag2 = true;
			while(flag2){
				Point p1 = list2.get(list2.size()-2);
				Point p2 = list2.get(list2.size()-1);
				if(p1.CCW(p2,query[0])>=0){
					list2.add(query[0]);
					flag2 = false;
				}
				else{
					list2.remove(list2.size()-1);
					if(list2.size()<2){
						list2.add(query[0]);
						flag2 = false;
					}
				}
			}
			for(int i=list2.size()-1;i>=0;i--){
				list.add(list2.get(i));
			}
			for(int i=list1.size()-2;i>=1;i--){
				list.add(list1.get(i));
			}
		}
		return list;
	}
	double area( Point[] query ){
		double area = 0;
		for(int i=0;i<query.length-1;i++){
			area += (query[i].x - query[i+1].x) * (query[i].y + query[i+1].y)/2;
		}
		area += (query[query.length-1].x - query[0].x) * (query[query.length-1].y + query[0].y)/2;
		area = Math.abs(area);
		return area;
	}

	Point polarCos(double cos_a){
		double sin_a = Math.sqrt(1-Math.pow(cos_a,2));
		double x = cos_a*this.x - sin_a*this.y;
		double y = sin_a*this.x + cos_a*this.y;
		return new Point(x,y); 
	}
	Point polarSin(double sin_a){
		double cos_a = Math.sqrt(1-Math.pow(sin_a,2));
		double x = cos_a*this.x - sin_a*this.y;
		double y = sin_a*this.x + cos_a*this.y;
		return new Point(x,y); 
	}

	boolean judge( Point a ){	
		if( Math.abs( this.x - a.x ) < EPS && Math.abs( this.y - a.y ) < EPS){
			return true;
		}
		else{
			return false;
		}
	}
	double rounding(double a){
		BigDecimal bi = new BigDecimal(String.valueOf(a));
		return bi.setScale(cutoff,BigDecimal.ROUND_HALF_UP).doubleValue();
	}
}
class Vector{
	public final double EPS = Math.pow(10,-8);
	public double x,y;

	Vector( double x1 , double y1 , double x2 , double y2 ){
		this.x = x2 - x1;
		this.y = y2 - y1;
	}

	double dot( Vector a ){	
		return this.x * a.x + this.y * a.y;
	}
	double cross( Vector a ){	
		return this.x * a.y - this.y * a.x;
	}

	void add( Vector a ){
		this.x += a.x;
		this.y += a.y;
	}
	void sub( Vector a ){
		this.x -= a.x;
		this.y -= a.y;
	}
	void mul( double z ){
		this.x *= z;
		this.y *= z;
	}
	void div( double z ){
		this.x /= z;
		this.y /= z;
	}

	double abs(){
		return Math.sqrt(norm());
	}
	double norm(){
		return this.x * this.x + this.y * this.y;
	}

	double cos(Vector a){
		Vector b = new Vector(0,0,this.x,this.y);
		Vector c = new Vector(a.x,a.y,b.x,b.y);
		if(judge(a.dot(b))){
			return 0.0;
		}
		double cos = (Math.pow(a.abs(),2)+Math.pow(b.abs(),2)-Math.pow(c.abs(),2))/(2*a.abs()*b.abs());
		return cos;
	}
	double sin(Vector a){
		Vector b = new Vector(0,0,this.x,this.y);
		if(judge(a.cross(b))){
			return 0.0;
		}
		double height = a.cross(b)/a.abs();
		double sin = b.abs()/height;
		return sin;
	}
	double cosLength( double a , double b , double c ){
		double cos = (Math.pow(a,2) + Math.pow(b,2) - Math.pow(c,2))/(2 * a * b);
		if(judge(cos)){
			return 0.0;
		}
		return cos;
	}
	double sinLength( double a , double b , double c ){
		double cos = cosLength(a,b,c);
		if(judge(1-cos)){
			return 0.0;
		}
		return Math.sqrt(1-Math.pow(cos,2));

	}

	void projection( Vector a ){
		double cos = dot(a)/(abs() * a.abs());
		double frac = a.abs() * cos/abs();
		mul(frac);
	}
	Vector reflection( Vector a ){
		projection(a);
		return new Vector(a.x,a.y,this.x,this.y);
	}

	boolean judgeisOrthogonal( Vector a ){	
		return judge(dot(a)) ? true : false;
	}  
	boolean judgeisParallel( Vector a ){	
		return judge(cross(a)) ? true : false;
	}

	boolean judge( double a ){	
		return Math.abs(a)<EPS ? true : false;
	}
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		// 入力
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		List<Vector2d> p = new ArrayList<>();
		for (int i=0; i<n; i++) {
			int x = sc.nextInt();
			int y = sc.nextInt();
			p.add(new Vector2d(x, y));
		}
		sc.close();
		printAns(solve(p));
	}

	static class Vector2d {
		Vector2d(int x, int y){
			this.x = x;
			this.y = y;
		}
		int x;
		int y;
		public String toString() {
			return String.format("%d %d", x, y);
		}

		public static Vector2d sub(Vector2d v1, Vector2d v2){
			return new Vector2d(v2.x - v1.x, v2.y - v1.y);
		}

		// 3点が反時計回りになっているならばtrue
		public static boolean isCounterClockwise(Vector2d v1, Vector2d v2, Vector2d v3) {
			Vector2d a = sub(v1, v2);
			Vector2d b = sub(v1, v3);
			double angle = a.x * b.y - a.y * b.x;
			return angle >= 0;
		}

	}

	static class Vector2dComparator implements Comparator<Vector2d>{
		@Override
		public int compare(Vector2d v1, Vector2d v2) {
			int y = v1.y - v2.y;
			if (y == 0) {
				return v1.x - v2.x;
			}
			return y;
		}
	}

	public static List<Vector2d> solve(List<Vector2d> p) {
		int s = p.size();
		p.sort(new Vector2dComparator());
		// 凸包
		// 右部凸包
		List<Vector2d> ansR = new ArrayList<>();
		ansR.add(p.get(0));
		ansR.add(p.get(1));
		for(int i=2; i<s; i++) {
			ansR.add(p.get(i));
			// ansRが3点以上含み、
			// 最後の3点が反時計回りになってない
			while(ansR.size() >= 3 && !Vector2d.isCounterClockwise(ansR.get(ansR.size()-3), ansR.get(ansR.size()-2), ansR.get(ansR.size()-1))) {
				ansR.remove(ansR.size()-2);
			}
		}
		// 左部凸包
		List<Vector2d> ansL = new ArrayList<>();
		ansL.add(p.get(s-1));
		ansL.add(p.get(s-2));
		for(int i=s-3; i>=0; i--) {
			ansL.add(p.get(i));
			// ansLが3点以上含み、
			// 最後の3点が反時計回りになってない
			while(ansL.size() >= 3 && !Vector2d.isCounterClockwise(ansL.get(ansL.size()-3), ansL.get(ansL.size()-2), ansL.get(ansL.size()-1))) {
				ansL.remove(ansL.size()-2);
			}
		}
		// ansRとかぶる点を除去
		ansL.remove(ansL.size()-1);
		ansL.remove(0);
		// 左右の凸包を合体
		ansR.addAll(ansL);
		return ansR;
	}

	public static void printAns(List<Vector2d> l) {
		for (int i=0; i<l.size(); i++) {
			System.out.println(l.get(i));
		}
	}
}

