						next--;
					}
					else{
						list2.remove(list2.size()-1);
					}
				}
			}
			boolean flag2 = true;
			while(flag2){
				Point p1 = list2.get(list2.size()-2);
				Point p2 = list2.get(list2.size()-1);
				if(p1.CCW(p2,query[0])>=0){
					list2.add(query[0]);
					flag2 = false;
				}
				else{
					list2.remove(list2.size()-1);
				}
			}
			for(int i=list2.size()-1;i>=0;i--){
				list.add(list2.get(i));
			}
			for(int i=list1.size()-2;i>=1;i--){
				list.add(list1.get(i));
			}
		}
		return list;
	}
	double area( Point[] query ){
		double area = 0;
		for(int i=0;i<query.length-1;i++){
			area += (query[i].x - query[i+1].x) * (query[i].y + query[i+1].y)/2;
		}
		area += (query[query.length-1].x - query[0].x) * (query[query.length-1].y + query[0].y)/2;
		area = Math.abs(area);
		return area;
	}

	Point polarCos(double cos_a){
		double sin_a = Math.sqrt(1-Math.pow(cos_a,2));
		double x = cos_a*this.x - sin_a*this.y;
		double y = sin_a*this.x + cos_a*this.y;
		return new Point(x,y); 
	}
	Point polarSin(double sin_a){
		double cos_a = Math.sqrt(1-Math.pow(sin_a,2));
		double x = cos_a*this.x - sin_a*this.y;
		double y = sin_a*this.x + cos_a*this.y;
		return new Point(x,y); 
	}

	boolean judge( Point a ){	
		if( Math.abs( this.x - a.x ) < EPS && Math.abs( this.y - a.y ) < EPS){
			return true;
		}
		else{
			return false;
		}
	}
	double rounding(double a){
		BigDecimal bi = new BigDecimal(String.valueOf(a));
		return bi.setScale(cutoff,BigDecimal.ROUND_HALF_UP).doubleValue();
	}
}
class Vector{
	public final double EPS = Math.pow(10,-8);
	public double x,y;

	Vector( double x1 , double y1 , double x2 , double y2 ){
		this.x = x2 - x1;
		this.y = y2 - y1;
	}

	double dot( Vector a ){	
		return this.x * a.x + this.y * a.y;
	}
	double cross( Vector a ){	
		return this.x * a.y - this.y * a.x;
	}

	void add( Vector a ){
		this.x += a.x;
		this.y += a.y;
	}
	void sub( Vector a ){
		this.x -= a.x;
		this.y -= a.y;
	}
	void mul( double z ){
		this.x *= z;
		this.y *= z;
	}
	void div( double z ){
		this.x /= z;
		this.y /= z;
	}

	double abs(){
		return Math.sqrt(norm());
	}
	double norm(){
		return this.x * this.x + this.y * this.y;
	}

	double cos(Vector a){
		Vector b = new Vector(0,0,this.x,this.y);
		Vector c = new Vector(a.x,a.y,b.x,b.y);
		if(judge(a.dot(b))){
			return 0.0;
		}
		double cos = (Math.pow(a.abs(),2)+Math.pow(b.abs(),2)-Math.pow(c.abs(),2))/(2*a.abs()*b.abs());
		return cos;
	}
	double sin(Vector a){
		Vector b = new Vector(0,0,this.x,this.y);
		if(judge(a.cross(b))){
			return 0.0;
		}
		double height = a.cross(b)/a.abs();
		double sin = b.abs()/height;
		return sin;
	}
	double cosLength( double a , double b , double c ){
		double cos = (Math.pow(a,2) + Math.pow(b,2) - Math.pow(c,2))/(2 * a * b);
		if(judge(cos)){
			return 0.0;
		}
		return cos;
	}
	double sinLength( double a , double b , double c ){
		double cos = cosLength(a,b,c);
		if(judge(1-cos)){
			return 0.0;
		}
		return Math.sqrt(1-Math.pow(cos,2));

	}

	void projection( Vector a ){
		double cos = dot(a)/(abs() * a.abs());
		double frac = a.abs() * cos/abs();
		mul(frac);
	}
	Vector reflection( Vector a ){
		projection(a);
		return new Vector(a.x,a.y,this.x,this.y);
	}

	boolean judgeisOrthogonal( Vector a ){	
		return judge(dot(a)) ? true : false;
	}  
	boolean judgeisParallel( Vector a ){	
		return judge(cross(a)) ? true : false;
	}

	boolean judge( double a ){	
		return Math.abs(a)<EPS ? true : false;
	}
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main{
	static final double EPS = 0.00000000001;
	static final int COUNTER_CLOCKWISE = 1;
	static final int CLOCKWISE = -1;
	static final int ONLINE_BACK = 2;
	static final int ONLINE_FRONT = -2;
	static final int ON_SEGMENT = 0;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		List<Point> s = new ArrayList<Point>();
		for(int i = 0; i < n; i++) {
			s.add(new Point(sc.nextInt(), sc.nextInt()));
		}
		sc.close();
		List<Point> l = andrewScan(s);
		System.out.println(l.size());
		for(int i = 0; i < l.size(); i++) {
			System.out.println((int)l.get(i).x + " " + (int)l.get(i).y);
		}
	}
	static List<Point> andrewScan(List<Point> s){
		List<Point> u = new ArrayList<Point>();
		List<Point> l = new ArrayList<Point>();
		if(s.size() < 3) return s;
		Collections.sort(s, new MyComp(1));
//		for(int i = 0; i < s.size(); i++) {
//			System.out.printf("%d %d %d\n", i, s.get(i).x, s.get(i).y);
//		}
		// x が小さいものから2つ u に追加
		u.add(s.get(0));
		u.add(s.get(1));
		// x が大きいものから2つ l に追加
		l.add(s.get(s.size() - 1));
		l.add(s.get(s.size() - 2));

		// 凸包の上部を生成
		for(int i = 2; i < s.size(); i++) {
			for(int n = u.size(); n >= 2 && ccw(u.get(n - 2), u.get(n - 1), s.get(i)) != CLOCKWISE; n--) {
				u.remove(u.size() - 1);
			}
			u.add(s.get(i));
		}

		// 凸包の下部を生成
		for(int i = s.size() - 3; i >= 0; i--) {
			for(int n = l.size(); n >= 2 && ccw(l.get(n - 2), l.get(n - 1) , s.get(i)) != CLOCKWISE; n--) {
				l.remove(l.size() - 1);
			}
			l.add(s.get(i));
		}

		// 時計回りになるように凸包の点を列に生成
		Collections.reverse(l);
		for(int i = u.size() - 2; i >= 1; i--) {
			l.add(u.get(i));
		}
		return l;
	}
	static class Point{
		double x, y;
		Point(double x, double y){
			this.x = x;
			this.y = y;
		}
	}
	static class MyComp implements Comparator<Point>{
		int sign;
		MyComp(int sign) {
			this.sign = sign;
		}
		public int compare(Point p1, Point p2) {
			if(p1.y < p2.y) {
				return -1 * sign;
			}else if(p1.y == p2.y) {
				if(p1.x < p2.x) {
					return -1 * sign;
				}else if(p1.x == p2.x) {
					return 0;
				}else {
					return 1 * sign;
				}
			}else {
				return 1 * sign;
			}
		}
	}

	static int ccw(Point p0, Point p1, Point p2) {
		Point a = vec(p0, p1);
		Point b = vec(p0, p2);
		if(cross(a, b) > EPS) return COUNTER_CLOCKWISE;
		if(cross(a, b) < EPS) return CLOCKWISE;
		if(dot(a, b) < EPS) return ONLINE_BACK;
		if(norm(a) < norm(b)) return ONLINE_FRONT;
		return ON_SEGMENT;
	}
	static double norm(Point p) {
		return p.x * p.x + p.y * p.y;
	}
	static Point vec(Point p1, Point p2) {
		return new Point(p2.x - p1.x, p2.y - p1.y);
	}
	static double dot(Point u, Point v) {
		return u.x * v.x + u.y * v.y;
	}
	static double cross(Point u, Point v) {
		return u.x * v.y - u.y * v.x;
	}
}

