					return 1;
				}
			}
		});

		int i = 1;
		int j = 0;
		while(i < p.size()) {
			if(checkCounterClockwise(p.get(i-1), p.get(i), p.get((i+1)%p.size())) == 1) {
				j = i;
				i++;
			} else if(checkCounterClockwise(p.get(i-1), p.get(i), p.get((i+1)%p.size())) == -1) {
				p.remove(i);
