				return 0;
			} else if((p1.y < p2.y && p3.x < p1.x) || (p1.y > p2.y && p3.x > p1.x)) {
				return 1;
			} else {
				return -1;
			}	

		} else {
			if(Math.abs(p3.y - (a * p3.x + b)) < ALLOWABLE_ERROR) {
				return 0;
			} else if((p1.x < p2.x && p3.y - (a * p3.x + b) > 0) || (p1.x > p2.x && p3.y - (a * p3.x + b) < 0)) {
				return 1;
			} else {
				return -1;
			}				
		}
