				return true;
			} else {
				return false;
			}	

		} else {
			if(Math.abs(p3.y - (a * p3.x + b)) < ALLOWABLE_ERROR) {
				return true;
			} else if((p1.x < p2.x && p3.y - (a * p3.x + b) > 0) || (p1.x > p2.x && p3.y - (a * p3.x + b) < 0)) {
				return true;
			} else {
				return false;
			}				
		}
	}

