      if(ansx[num - 1] == x[n - 1] && ansy[num - 1] == y[n - 1])num--;
    }

    return num;
  }

  private static void quicksort(int[] x, int[] y, int p, int r){
    int q, i;
    if(p < r){
      q = partition(x, y, p, r);
      quicksort(x, y, p, q);
      quicksort(x, y, q + 1, r);
    }
    return;
  }
  private static int partition(int[] x, int[] y, int t, int s){
    int k, j, tmp;
    for(k = t - 1;;){
      for(j = k + 1;j < s;j++){
        if(alow(x[j], y[j], x[s - 1], y[s - 1])){
          k++;
          tmp = x[k];
          x[k] = x[j];
          x[j] = tmp;
          tmp = y[k];
          y[k] = y[j];
          y[j] = tmp;
          if(j == s - 1)return k;
          break;
        }
      }
    }
  }
  private static boolean alow(int ax, int ay, int bx, int by){
    if(ay < by || (ay == by && ax <= bx)){
      return true;
    }else{
      return false;
    }
  }
  private static void reverse(int[] x, int[] y){
    int n, tmp, i;
    n = x.length;
    for(i = 0;i < n / 2;i++){
      tmp = x[i];
      x[i] = x[n - 1 - i];
      x[n - 1 - i] = tmp;
      tmp = y[i];
      y[i] = y[n - 1 - i];
      y[n - 1 - i] = tmp;
    }
    return;
  }
}

