    }
    sc.close();

    quicksort(x, y, 0, n);

    numr = rcovering(x, y, ansrx, ansry);
    reverse(x, y);
    numl = rcovering(x, y, anslx, ansly);

    ncon = numr + numl;
    for(i = 0;i < numr;i++){
      conx[i] = ansrx[i];
      cony[i] = ansry[i];
    }
