      System.out.println(conx[i] + " " + cony[i]);
    }

  }
  public static void main(String[] args){
    (new Main()).run(System.in, System.out);
  }

  private static int rcovering(int[] x, int[] y, int[] ansx, int[] ansy){
    int i, n, num;
    n = x.length;

    ansx[0] = x[0];
    ansy[0] = y[0];
    ansx[1] = x[1];
    ansy[1] = y[1];
    num = 2;
    for(i = 2;i < n;i++){
      ansx[num] = x[i];
      ansy[num] = y[i];
      num = gscan(ansx, ansy, num);
    }
    if(ansx[num - 1] == x[n - 1] && ansy[num - 1] == y[n - 1])num--;

    return num;
  }

  private static void quicksort(int[] x, int[] y, int p, int r){
    int q, i;
    if(p < r){
      q = partition(x, y, p, r);
      quicksort(x, y, p, q);
      quicksort(x, y, q + 1, r);
    }
    return;
  }
  private static int partition(int[] x, int[] y, int t, int s){
    int k, j, tmp;
    for(k = t - 1;;){
      for(j = k + 1;j < s;j++){
        if(alow(x[j], y[j], x[s - 1], y[s - 1])){
          k++;
          tmp = x[k];
          x[k] = x[j];
          x[j] = tmp;
          tmp = y[k];
          y[k] = y[j];
          y[j] = tmp;
          if(j == s - 1)return k;
          break;
        }
      }
    }
  }
  private static boolean alow(int ax, int ay, int bx, int by){
    if(ay < by || (ay == by && ax <= bx)){
      return true;
    }else{
      return false;
    }
  }
  private static void reverse(int[] x, int[] y){
    int n, tmp, i;
    n = x.length;
    for(i = 0;i < n / 2;i++){
      tmp = x[i];
      x[i] = x[n - 1 - i];
      x[n - 1 - i] = tmp;
      tmp = y[i];
      y[i] = y[n - 1 - i];
      y[n - 1 - i] = tmp;
    }
    return;
  }
  private static int gscan(int[] ansx, int[] ansy, int num){
    int s1x, s1y, s2x, s2y;
    if(num == 1)return num;
    s1x = ansx[num - 1] - ansx[num];
    s1y = ansy[num - 1] - ansy[num];
    s2x = ansx[num - 2] - ansx[num];
    s2y = ansy[num - 2] - ansy[num];
    if(s1x * s2y - s2x * s1y > 0){
      ansx[num - 1] = ansx[num];
      ansy[num - 1] = ansy[num];
      num--;
      num = gscan(ansx, ansy, num);
    }else{
      num++;
    }
    return num;
  }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		// 入力
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		List<Vector2d> p = new ArrayList<>();
		for (int i=0; i<n; i++) {
			int x = sc.nextInt();
			int y = sc.nextInt();
			p.add(new Vector2d(x, y));
		}
		sc.close();
		printAns(solve(p));
	}

	static class Vector2d {
		Vector2d(int x, int y){
			this.x = x;
			this.y = y;
		}
		int x;
		int y;
		public String toString() {
			return String.format("%d %d", x, y);
		}

		public static Vector2d sub(Vector2d v1, Vector2d v2){
			return new Vector2d(v2.x - v1.x, v2.y - v1.y);
		}

		// 3点が反時計回りになっているならばtrue
		public static boolean isCounterClockwise(Vector2d v1, Vector2d v2, Vector2d v3) {
			Vector2d a = sub(v1, v2);
			Vector2d b = sub(v1, v3);
			double angle = a.x * b.y - a.y * b.x;
			return angle >= 0;
		}

	}

	static class Vector2dComparator implements Comparator<Vector2d>{
		@Override
		public int compare(Vector2d v1, Vector2d v2) {
			int y = v1.y - v2.y;
			if (y == 0) {
				return v1.x - v2.x;
			}
			return y;
		}
	}

	public static List<Vector2d> solve(List<Vector2d> p) {
		int s = p.size();
		p.sort(new Vector2dComparator());
		// 凸包
		// 右部凸包
		List<Vector2d> ansR = new ArrayList<>();
		ansR.add(p.get(0));
		ansR.add(p.get(1));
		for(int i=2; i<s; i++) {
			ansR.add(p.get(i));
			// ansRが3点以上含み、
			// 最後の3点が反時計回りになってない
			while(ansR.size() >= 3 && !Vector2d.isCounterClockwise(ansR.get(ansR.size()-3), ansR.get(ansR.size()-2), ansR.get(ansR.size()-1))) {
				ansR.remove(ansR.size()-2);
			}
		}
		// 左部凸包
		List<Vector2d> ansL = new ArrayList<>();
		ansL.add(p.get(s-1));
		ansL.add(p.get(s-2));
		for(int i=s-3; i>=0; i--) {
			ansL.add(p.get(i));
			// ansLが3点以上含み、
			// 最後の3点が反時計回りになってない
			while(ansL.size() >= 3 && !Vector2d.isCounterClockwise(ansL.get(ansL.size()-3), ansL.get(ansL.size()-2), ansL.get(ansL.size()-1))) {
				ansL.remove(ansL.size()-2);
			}
		}
		// ansRとかぶる点を除去
		ansL.remove(ansL.size()-1);
		ansL.remove(0);
		// 左右の凸包を合体
		ansR.addAll(ansL);
		return ansR;
	}

	public static void printAns(List<Vector2d> l) {
		System.out.println(l.size());
		for (int i=0; i<l.size(); i++) {
			System.out.println(l.get(i));
		}
	}
}

