            int m = ans.Length;
            double minX = int.MaxValue, minY = int.MaxValue;
            int minIndex = 0;

            for (int i = 0; i < m; i++)
            {
                if (minY > ans[i].y || (minY == ans[i].y && minX > ans[i].x))
                {
                    minY = ans[i].y;
                    minX = ans[i].x;
                    minIndex = i;
                }
            }

            StringBuilder sb = new StringBuilder();
            sb.AppendLine(m.ToString());
