namespace CGL_4_A_Convex_Hull
{
	class Program
	{
		static void Main ( string[] args )
		{
			int inputCount = int.Parse (Console.ReadLine ());
			Vector2[] polygon = new Vector2[inputCount];

			for (int lp = 0; lp < inputCount; lp++)
			{
				decimal[] i = Array.ConvertAll (Console.ReadLine ().Split (' '), decimal.Parse);
				polygon[lp] = new Vector2 (i[0], i[1]);
			}

			var result = Vector2.ConvexHull (polygon);
			result = result.OrderBy (item => item.Y).ThenBy (item => -item.X).ToArray ();

			StringBuilder output = new StringBuilder (result.Length * 9);

			output.Append (result.Length);
			output.AppendLine ();

			foreach (var item in result)
			{
				output.Append (item.X);
				output.Append (" ");
				output.Append (item.Y);
				output.AppendLine ();
			}

			Console.Write (output);
		}
	}

	class Vector2
	{
		public Vector2 ( decimal x, decimal y )
		{
			this.X = x;
			this.Y = y;
		}

		public decimal X { private set; get; }
		public decimal Y { private set; get; }

		public static Vector2 operator - ( Vector2 ob1, Vector2 ob2 )
		{
			return new Vector2 (ob1.X - ob2.X, ob1.Y - ob2.Y);
		}

		public decimal Length ()
		{
			return X * X + Y * Y;
		}
		public static decimal DotProduct ( Vector2 line1, Vector2 line2 )
		{
			return line1.X * line2.X + line1.Y * line2.Y;
		}
		public static decimal CrossProduct ( Vector2 line1, Vector2 line2 )
		{
			return line1.X * line2.Y - line1.Y * line2.X;
		}

		public const int Counter_Clockwise = 1;
		public const int Clockwise = -1;
		public const int OnlineBack = 2;
		public const int OnlineFront = -2;
		public const int OnSegment = 0;

		public static int PointState ( Vector2 point1, Vector2 point2, Vector2 point3 )
		{
			Vector2 line1 = point2 - point1;
			Vector2 line2 = point3 - point1;

			decimal crossProduct = CrossProduct (line1, line2);

			if (crossProduct > 0m)
			{
				return Counter_Clockwise;
			}
			else if (crossProduct < 0m)
			{
				return Clockwise;
			}
			else if (DotProduct (line1, line2) < 0m)
			{
				return OnlineBack;
			}
			else if (line1.Length () < line2.Length ())
			{
				return OnlineFront;
			}

			return OnSegment;
		}

		public static Vector2[] ConvexHull ( Vector2[] polygon )
		{
			polygon = polygon.OrderBy (item => item.X).ThenBy (item => item.Y).ToArray ();
			int count = polygon.Length;

			//上部
			List<Vector2> topPoint = new List<Vector2> (count);
			topPoint.Add (polygon[0]);
			topPoint.Add (polygon[1]);

			for (int lp = 2; lp < count; lp++)
			{
				for (int n = topPoint.Count; 2 <= n && 0 <= Vector2.PointState (topPoint[n - 2], topPoint[n - 1], polygon[lp]); n--)
				{
					topPoint.RemoveAt (n - 1);
				}

				topPoint.Add (polygon[lp]);
			}

			//下部
			List<Vector2> buttomPoint = new List<Vector2> (count);
			buttomPoint.Add (polygon[count - 1]);
			buttomPoint.Add (polygon[count - 2]);

			for (int lp = count - 3; 0 <= lp; lp--)
			{
				for (int n = buttomPoint.Count; 2 <= n && 0 <= Vector2.PointState (buttomPoint[n - 2], buttomPoint[n - 1], polygon[lp]); n--)
				{
					buttomPoint.RemoveAt (n - 1);
				}

				buttomPoint.Add (polygon[lp]);
			}

			//結合
			buttomPoint.Reverse ();

			for (int lp = topPoint.Count - 2; 1 <= lp; lp--)
			{
				buttomPoint.Add (topPoint[lp]);
			}

			return buttomPoint.ToArray ();
		}
	}

}

