                G[i] = new Point(input[0], input[1]);
            }

            Array.Sort(G);


            Point startP = G[0];
            Point nextP = new Point();
            Point target = new Point();
            double minRd = 1.0;

            for (int i = 1; i < n; i++)
            {
                double r = Math.Atan2((G[i].y - startP.y), (G[i].x - startP.x));

                if (r < minRd)
                {
                    nextP = G[i];
                    minRd = r;
                }
            }

            StringBuilder sb = new StringBuilder();
            sb.AppendLine(startP.ToString());
            int addCnt = 1;

            do
            {
                double maxRd = 0.0;

                for (int i = 0; i < n; i++)
                {
                    if (G[i] != startP || G[i] != nextP)
                    {
                        double rd = CalcAngle(startP, nextP, G[i]);

                        if (rd > maxRd)
                        {
                            target = G[i];
                            maxRd = rd;
                        }
                    }
                }

                startP = nextP;
                nextP = target;

                sb.AppendLine(startP.ToString());
                addCnt++;

            } while (target.x != G[0].x || target.y != G[0].y);

            Console.WriteLine(addCnt);
            Console.Write(sb);
        }

        static double CalcAngle(Point a, Point b, Point c)
        {
            double baX = a.x - b.x;
            double baY = a.y - b.y;
            double bcX = c.x - b.x;
            double bcY = c.y - b.y;

            double babc = baX * bcX + baY * bcY;
            double ban = baX * baX + baY * baY;
            double bcn = bcX * bcX + bcY * bcY;

            return Math.Acos(babc / Math.Sqrt(ban * bcn));
        }
    }

