namespace ConsoleApplication1
{
    class Program
    {
        static readonly double EPS = 1E-10;

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());

            List<Point> s = new List<Point>();

            for (int i = 0; i < n; i++)
            {
                double[] input = Array.ConvertAll(Console.ReadLine().Split(' '), double.Parse);
                s.Add(new Point(input[0], input[1]));
            }

            List<Point> ans = AndrewScan(s);
            int m = ans.Count;
            double minX = int.MaxValue, minY = int.MaxValue;
            int minIndex = 0;

            for (int i = 0; i < m; i++)
            {
                if (minY > ans[i].y || (minY == ans[i].y && minX > ans[i].x))
                {
                    minY = ans[i].y;
                    minX = ans[i].x;
                    minIndex = i;
                }
            }

            StringBuilder sb = new StringBuilder();
            sb.AppendLine(m.ToString());
            for(int i = 0; i < m; i++)
            {
                sb.AppendLine(ans[(i + minIndex) % m].ToString());
            }
            Console.Write(sb);
        }

        static List<Point> AndrewScan(List<Point> s)
        {
            int n = s.Count;

            if (n < 3) return s;

            s.Sort();

            List<Point> u = new List<Point>();
            u.Add(s[0]);
            u.Add(s[1]);

            List<Point> l = new List<Point>();
            l.Add(s[n - 1]);
            l.Add(s[n - 2]);

            for (int i = 2; i < n; i++)
            {
                for (int j = u.Count; j >= 2 && (u[j - 1] - u[j - 2]).Cross(s[i] - u[j - 2]) > EPS; j--)
                {
                    u.RemoveAt(u.Count - 1);
                }
                u.Add(s[i]);
            }

            for (int i = s.Count - 3; i >= 0; i--)
            {
                for (int j = l.Count; j >= 2 && (l[j - 1] - l[j - 2]).Cross(s[i] - l[j - 2]) > EPS; j--)
                {
                    l.RemoveAt(l.Count - 1);
                }
                l.Add(s[i]);
            }

            l.Reverse();
            for (int i = u.Count - 2; i >= 1; i--) l.Add(u[i]);

            return l;
        }
    }

