namespace ConsoleApplication1
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());

            Point[] G = new Point[n];

            for (int i = 0; i < n; i++)
            {
                double[] input = Array.ConvertAll(Console.ReadLine().Split(' '), double.Parse);
                G[i] = new Point(input[0], input[1]);
            }

            Point startP = G[0];
            Point nextP = G[1];
            Point target = new Point();

            StringBuilder sb = new StringBuilder();
            sb.AppendLine(startP.ToString());
            int addCnt = 1;

            do
            {
                double maxRd = 0.0;

                for (int i = 0; i < n; i++)
                {
                    if (G[i] != startP || G[i] != nextP)
                    {
                        double rd = CalcAngle(startP, nextP, G[i]);

                        if (rd > maxRd)
                        {
                            target = G[i];
                            maxRd = rd;
                        }
                    }
                }

                startP = nextP;
                nextP = target;

                sb.AppendLine(startP.ToString());
                addCnt++;

            } while (target.x != G[0].x || target.y != G[0].y);

            Console.WriteLine(addCnt);
            Console.Write(sb);
        }

        static double CalcAngle(Point a, Point b, Point c)
        {
            double baX = a.x - b.x;
            double baY = a.y - b.y;
            double bcX = c.x - b.x;
            double bcY = c.y - b.y;

            double babc = baX * bcX + baY * bcY;
            double ban = baX * baX + baY * baY;
            double bcn = bcX * bcX + bcY * bcY;

            return Math.Acos(babc / Math.Sqrt(ban * bcn));
        }
    }

