public class Gs{
	public class Dt{
		public int n;
		public long x,y;
		public double d;
		public Dt(double d,int n,long x,long y){this.d=d;this.n=n;this.x=x;this.y=y;}
	}
	private Dt[] arr;
	private double cd;
	private long cx;
	public List<Dt> li=new List<Dt>();
	public Gs(int[][] a,int p){
		int n=a.Length,q=2;
		arr=new Dt[n];
		for(int i=0;i<n;i++){
			if(i!=p){arr[i]=new Dt(Atan2(a[i][1]-a[p][1],a[i][0]-a[p][0])*180/PI,i,a[i][0],a[i][1]);cd=Max(cd,arr[i].d);}
		}
		arr[p]=new Dt(-512,p,a[p][0],a[p][1]);
		cx=a[p][0];
		Array.Sort(arr,Ca2);
		li.Add(arr[0]);
		li.Add(arr[1]);
		while(q!=n){
			li.Add(arr[q]);
			q++;
			while(li.Count>2&&(li[li.Count-1].x-li[li.Count-2].x)*(li[li.Count-3].y-li[li.Count-2].y)-(li[li.Count-1].y-li[li.Count-2].y)*(li[li.Count-3].x-li[li.Count-2].x)<0){
				li.RemoveAt(li.Count-2);
			}
		}
	}
	private int Ca1(Dt a,Dt b){
		if(a.d>b.d){return 1;}
		else if(a.d<b.d){return -1;}
		else if(a.x>b.x){return 1;}
		else if(a.x<b.x){return -1;}
		else if(a.y>b.y){return 1;}
		else if(a.y<b.y){return -1;}
		return 0;
	}
	private int Ca2(Dt a,Dt b){
		if(a.d>b.d){return 1;}
		else if(a.d<b.d){return -1;}
		else if(a.d==cd){
			if(cx==a.x){if(a.y<b.y){return 1;}else if(a.y>b.y){return -1;}}
			else if(cx>a.x){if(a.x>b.x){return 1;}else if(a.x<b.x){return -1;}}
			else{if(a.x<b.x){return 1;}else if(a.x>b.x){return -1;}}
		}
		else{
			if(cx==a.x){if(a.y>b.y){return 1;}else if(a.y<b.y){return -1;}}
			else if(cx<a.x){if(a.x>b.x){return 1;}else if(a.x<b.x){return -1;}}
			else{if(a.x<b.x){return 1;}else if(a.x>b.x){return -1;}}
		}
		return 0;
	}
	public double Diameter(){
		double q=(li[0].x-li[li.Count-1].x),p=(li[0].y-li[li.Count-1].y),d=Math.Sqrt(q*q+p*p);
		for(int i=1;i<li.Count;i++){
			q=(li[i].x-li[i-1].x);
			p=(li[i].y-li[i-1].y);
			d+=Sqrt(q*q+p*p);
		}
		return d;
	}
}

