def solve(N, P):
    v = min(P, key=lambda p: (p.y, p.x))
    P.remove(v)

    def cmp_angle(a, b):
        return b[1].cross(a[1])

    PV = [(p, p - v) for p in P]
    key_fn = functools.cmp_to_key(cmp_angle)
    PV.sort(key=key_fn)

    hull = [v]

    i = 0
    j = 1
    while j < N - 1 and cmp_angle(PV[i], PV[j]) == 0:
        j += 1
    sub = list(PV[i : j])
    sub.sort(key=lambda pv: pv[1].abs2())
    hull += [p for p, _ in sub]
    i = j

    while i < N - 1:
        a = hull[-2]
        b = hull[-1]
        j = i + 1
        while j < N - 1 and cmp_angle(PV[i], PV[j]) == 0:
            j += 1
        sub = [(p, p - b) for p, _ in PV[i : j]]

        sub.sort(key=key_fn)

        for p, pb in sub:
            hull.append(p)
            while len(hull) >= 3:
                a = hull[-3]
                b = hull[-2]
                c = hull[-1]
                if (b - a).cross(c - b) >= 0:
                    break
                hull[-2] = c
                del hull[-1]

        i = j

    return hull


