def det(p1, p2, org=(0, 0)):
    """cross product"""
    return (p1[0]-org[0])*(p2[1]-org[1]) - (p2[0]-org[0])*(p1[1]-org[1])

def convex_hull(points):
    s = sorted(set(points), key=lambda x: (x[1], x[0]))
    hull = []
    for i in range(len(s)):
        while len(hull) > 1 and det(hull[-2], s[i], hull[-1]) > 0:
            hull.pop()
        hull.append(s[i])
    t = len(hull)
    for i in range(len(s) - 2, -1, -1):
        while len(hull) > t and det(hull[-2], s[i], hull[-1]) > 0:
            hull.pop()
        hull.append(s[i])

    return hull[:-1]


