    h = []
    s = sorted(set(p), key=lambda x: (x[1], x[0]))
    for i in range(len(s)):
        while len(h) > 1 and determinants(h[-2], s[i], h[-1]) > 0:
            h.pop()
        h.append(s[i])
    l = len(h)
    for i in range(len(s) - 2, -1, -1):
        while len(h) > l and determinants(h[-2], s[i], h[-1]) > 0:
            h.pop()
        h.append(s[i])
    return h[:-1]


