        while len(stack)>=2 and calc(stack[-1], li[i], stack[-2])<0:
            # 次が時計回り側にある時は1つ前を外す
            stack.pop()
        # 次が反時計回り側にあればOKなので進める
        stack.append(li[i])
    res=list(stack)[:-1]

