#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum CCW {
    /// a--b--c
    OnlineFront = -2,
    /// a--b-vc
    Clockwise = -1,
    /// a--c--b
    OnSegment = 0,
    /// a--b-^c
    CounterClockwise = 1,
    /// c--a--b
    OnlineBack = 2,
}
fn ccw(a: Complex, b: Complex, c: Complex) -> CCW {
    let x = b - a;
    let y = c - a;
    if x.cross(y) > 0. {
        CCW::CounterClockwise
    } else if x.cross(y) < 0. {
        CCW::Clockwise
    } else if x.dot(y) < 0. {
        CCW::OnlineBack
    } else if x.abs() < y.abs() {
        CCW::OnlineFront
    } else {
        CCW::OnSegment
    }
}
#[derive(PartialEq, PartialOrd)]
pub struct TotalOrd<T>(pub T);
impl<T: PartialEq> Eq for TotalOrd<T> {}
impl<T: PartialOrd> Ord for TotalOrd<T> {
    fn cmp(&self, other: &TotalOrd<T>) -> std::cmp::Ordering {
        self.0.partial_cmp(&other.0).unwrap()
    }
}
fn convex_hull(ps: Vec<Complex>) -> Vec<Complex> {
    let mut ps = ps;
    ps.sort_by(|p1, p2| ((p1.x, p1.y).partial_cmp(&(p2.x, p2.y)).unwrap()));
    let mut qs = Vec::new();
    for &p in ps.iter().chain(ps.iter().rev().skip(1)) {
        while {
            let k = qs.len();
            k > 1 && ccw(qs[k - 2], qs[k - 1], p) == CCW::Clockwise
        } {
            qs.pop();
        }
        qs.push(p);
    }
    qs.pop();
    qs
}
fn main() {
    input! { n, ps: [(f64, f64); n] };
    let ps = ps
        .into_iter()
        .map(|(x, y)| Complex::new(x, y))
        .collect::<Vec<_>>();
    let ch = convex_hull(ps);
    let n = ch.len();
    let j = (0..n)
        .map(|i| (TotalOrd(ch[i].y), TotalOrd(ch[i].x), i))
        .min()
        .unwrap()
        .2;
    println!("{}", n);
    for i in 0..n {
        let k = (i + j) % n;
        println!("{} {}", ch[k].x, ch[k].y);
    }
}

