    let mut sc = Scanner::new();

    let g: Vec<Pt> = sc.next_vec_len();
    let g = g
        .into_iter()
        .map(|r| Pt::new(r.im, r.re))
        .collect::<Vec<_>>();
    let ch = convex_hull(g);
    let mut ch = ch
        .into_iter()
        .map(|r| Pt::new(r.im, r.re))
        .collect::<Vec<_>>();

    let t = ch[0];
    ch.push(t);
    ch.reverse();
    ch.pop();

    println!("{}", ch.len());
    for p in ch {
        println!("{} {}", p.re, p.im);
    }
}

